def register_public_actions_aliases(app: Any) -> None:
    for rule in list(app.url_map.iter_rules()):
        if not rule.rule.startswith(f"{BASE_PATH}/"):
            continue
        public_rule = PUBLIC_BASE_PATH + "/" + rule.rule.removeprefix(f"{BASE_PATH}/")
        public_endpoint = f"{rule.endpoint}_public_actions"
        if public_endpoint in app.view_functions:
            continue
        app.add_url_rule(
            public_rule,
            endpoint=public_endpoint,
            view_func=app.view_functions[rule.endpoint],
            methods=sorted((rule.methods or set()) - {"HEAD", "OPTIONS"}),
            strict_slashes=rule.strict_slashes,
        )
