@actions_v2_api.errorhandler(HTTPException)
def _http_error(exc: HTTPException):
    return _error("http_error", str(getattr(exc, "description", "")) or getattr(exc, "name", "HTTP error"), int(exc.code or 500))


@actions_v2_api.errorhandler(Exception)
def _unhandled(exc: Exception):
    return _error("internal_error", str(exc)[:500] or "Internal error", 500)


def _error(code: str, message: str, status: int = 400):
    return jsonify({"ok": False, "error": {"code": code, "message": message}}), status


def _ok(**payload: Any):
    return jsonify({"ok": True, **payload})


def _plan_management_error(exc: ValueError, *, mode: str = "write"):
    code = str(exc)
    status = 404 if code in {"plan_not_found", "no_matching_slot", "food_not_found"} else 400
    return (
        jsonify(
            {
                "ok": False,
                "error": {"code": code, "message": code, "details": {}},
                "execution": {"mode": mode, "live_state_changed": False},
            }
        ),
        status,
    )


def action_error(
    error: str,
    message: str,
    *,
    status: int = 400,
    expected: list[Any] | None = None,
    received: Any = None,
    example_valid_call: dict[str, Any] | None = None,
    **extra: Any,
):
    payload: dict[str, Any] = {"ok": False, "error": error, "message": message}
    if expected is not None:
        payload["expected"] = expected
    if received is not None:
        payload["received"] = received
    if example_valid_call is not None:
        payload["example_valid_call"] = example_valid_call
    payload.update(extra)
    return jsonify(payload), status


def validation_error(field: str, message: str, *, expected: list[Any] | None = None, received: Any = None, example_valid_call: dict[str, Any] | None = None, status: int = 400):
    return action_error("invalid_detail", message, status=status, expected=expected, received=received, example_valid_call=example_valid_call, field=field)


def action_success(
    action: str,
    *,
    dry_run: bool = False,
    parsed_payload: dict[str, Any] | None = None,
    before: dict[str, Any] | None = None,
    after: dict[str, Any] | None = None,
    warnings: list[Any] | None = None,
    will_change: list[str] | None = None,
    will_not_change: list[str] | None = None,
    **extra: Any,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "ok": True,
        "action": action,
        "dry_run": bool(dry_run),
        "dry_run_supported": True,
        "parsed_payload": parsed_payload or {},
        "before": before or {},
        "after": after or {},
        "warnings": warnings or [],
        "will_change": will_change or [],
        "will_not_change": will_not_change or [],
    }
    payload.update(extra)
    return payload


def _body() -> dict[str, Any]:
    data = request.get_json(silent=True)
    return data if isinstance(data, dict) else {}


def _call_actions_view(
    view_func: Callable[..., Any],
    *,
    method: str,
    query: dict[str, Any] | None = None,
    body: dict[str, Any] | None = None,
):
    target = getattr(view_func, "__wrapped__", view_func)
    with current_app.test_request_context(
        "/__actions_v2_facade__",
        method=method.upper(),
        query_string=query or None,
        json=body if method.upper() != "GET" else None,
    ):
        response = current_app.make_response(target())
    payload = response.get_json(silent=True)
    return payload if isinstance(payload, dict) else {}, int(response.status_code or 200)


def _filters_dict(body: dict[str, Any]) -> dict[str, Any]:
    filters = body.get("filters")
    return filters if isinstance(filters, dict) else {}


def _today() -> str:
    return datetime.now(ZoneInfo("Europe/Berlin")).date().isoformat()


def _parse_date(value: Any, field: str, *, required: bool = False) -> str | None:
    if value in (None, ""):
        if required:
            raise ValueError(f"{field} is required")
        return None
    text = str(value).strip()
    try:
        date.fromisoformat(text)
    except ValueError as exc:
        raise ValueError(f"{field} must be ISO date YYYY-MM-DD") from exc
    return text


def _parse_datetime(value: Any, field: str, *, required: bool = False) -> str | None:
    if value in (None, ""):
        if required:
            raise ValueError(f"{field} is required")
        return None
    text = str(value).strip()
    try:
        datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValueError(f"{field} must be ISO datetime") from exc
    return text


def _limit(raw: Any, default: int = 100, maximum: int = 500) -> int:
    try:
        value = int(raw)
    except Exception:
        value = default
    return max(1, min(maximum, value))


def _list(raw: Any, field: str, *, strings: bool = True, maximum: int = 50) -> list[Any]:
    if raw in (None, ""):
        return []
    if not isinstance(raw, list):
        raise ValueError(f"{field} must be a list")
    values = raw[:maximum]
    if strings:
        return [str(item).strip() for item in values if str(item).strip()]
    return values


def _float_or_none(value: Any) -> float | None:
    try:
        if value in (None, ""):
            return None
        return float(value)
    except Exception:
        return None


_GPT_LOGGING_WEIGHT_RPE_PATTERN = re.compile(r"^(?P<weight>\d+)[.,](?P<rpe>10|[6-9])$")


def _split_gpt_logging_weight_rpe(weight_value: Any, rpe_value: Any) -> tuple[float | None, float | None]:
    weight = _float_or_none(weight_value)
    rpe = _float_or_none(rpe_value)
    if weight is None:
        return None, rpe
    if rpe is not None:
        return weight, rpe
    text = str(weight_value).strip()
    match = _GPT_LOGGING_WEIGHT_RPE_PATTERN.match(text)
    if not match:
        return weight, None
    split_weight = _float_or_none(match.group("weight"))
    split_rpe = _float_or_none(match.group("rpe"))
    if split_weight is None or split_rpe is None:
        return weight, None
    return split_weight, split_rpe


def _int_or_none(value: Any) -> int | None:
    try:
        if value in (None, ""):
            return None
        return int(value)
    except Exception:
        return None


