def _plan_days_from_plan(plan: dict[str, Any] | None) -> dict[str, Any]:
    return _plan_core(plan)["days"]


def _plan_core(plan: dict[str, Any] | None) -> dict[str, Any]:
    if not plan:
        return {
            "available": False,
            "reason": "no_active_plan",
            "id": None,
            "plan_id": None,
            "title": None,
            "name": None,
            "is_active": False,
            "is_archived": False,
            "active_version": None,
            "updated_at": None,
            "days": {},
            "active_weekdays": [],
            "current_exercise_map": {},
        }
    raw = plan.get("plan")
    days: dict[str, Any] = {}
    mode = "fixed_week"
    rolling_pattern: dict[str, Any] = {}
    if isinstance(raw, dict):
        meta = raw.get("meta") if isinstance(raw.get("meta"), dict) else {}
        mode = str(meta.get("mode") or "").strip().lower()
        rolling_pattern = meta.get("rolling_week_pattern") if isinstance(meta.get("rolling_week_pattern"), dict) else {}
        sequence = raw.get("sequence") if isinstance(raw.get("sequence"), list) else []
        if sequence and mode == "rolling_sequence":
            days["rotation"] = _serialize_plan_day(sequence)
        if isinstance(raw.get("base_week"), dict):
            for day, events in raw["base_week"].items():
                days[str(day)] = _serialize_plan_day(events)
        elif isinstance(raw.get("days"), list):
            for item in raw["days"]:
                if isinstance(item, dict) and item.get("day"):
                    days[str(item["day"])] = _serialize_plan_day(item.get("events") or item.get("items") or [])
        elif isinstance(raw.get("days"), dict):
            for day, value in raw["days"].items():
                days[str(day)] = _serialize_plan_day(value.get("events") if isinstance(value, dict) else value)
        elif isinstance(raw.get("base_week"), list):
            for item in raw["base_week"]:
                if isinstance(item, dict):
                    days[str(item.get("day") or len(days) + 1)] = _serialize_legacy_plan_day(item)
    exercise_map = {
        day: [ex["display_name"] for ex in info.get("exercises", [])]
        for day, info in days.items()
        if info.get("exercises")
    }
    reason = None if days else "plan_days_not_mapped"
    weekdays = ("Mo", "Di", "Mi", "Do", "Fr", "Sa", "So")
    weekly_training_status: dict[str, str] = {}
    if mode == "rolling_sequence":
        for day in weekdays:
            raw_status = str(rolling_pattern.get(day) or "").strip().casefold()
            if raw_status in {"train", "training", "gym"}:
                weekly_training_status[day] = "gym"
            elif raw_status in {"rest", "off", "pause"}:
                weekly_training_status[day] = "rest"
            elif raw_status in {"optional", "flex", "flexible"}:
                weekly_training_status[day] = "optional_gym"
            else:
                weekly_training_status[day] = "unresolved"
    else:
        for day in weekdays:
            events = (days.get(day) or {}).get("events") or []
            event_kinds = {str(event.get("kind") or "").strip().casefold() for event in events if isinstance(event, dict)}
            weekly_training_status[day] = "gym" if "gym" in event_kinds else "other_training" if events else "rest"
    return {
        "available": bool(days),
        "id": plan.get("id"),
        "plan_id": plan.get("id"),
        "title": plan.get("name"),
        "name": plan.get("name"),
        "is_active": bool(plan.get("is_active")),
        "is_archived": bool(plan.get("is_archived")),
        "active_version": plan.get("name"),
        "updated_at": plan.get("updated_at") or ((raw.get("meta") or {}).get("updated_at") if isinstance(raw, dict) else None),
        "source": plan.get("source"),
        "mode": mode or "fixed_week",
        "rolling_week_pattern": rolling_pattern if mode == "rolling_sequence" else None,
        "weekly_training_status": weekly_training_status,
        "blocked_rest_days": [day for day, status in weekly_training_status.items() if status == "rest"],
        "gym_days": [day for day, status in weekly_training_status.items() if status == "gym"],
        "scheduled_gym_days_per_week": sum(1 for status in weekly_training_status.values() if status == "gym"),
        "scheduled_rest_days_per_week": sum(1 for status in weekly_training_status.values() if status == "rest"),
        "days": days,
        "active_weekdays": [day for day, info in days.items() if info.get("events")],
        "current_exercise_map": exercise_map,
        **({"reason": reason} if reason else {}),
    }


def _compact_plan_core(core: dict[str, Any]) -> dict[str, Any]:
    days = {}
    for day, info in (core.get("days") or {}).items():
        row: dict[str, Any] = {
            "label": info.get("label"),
            "available": bool(info.get("available")),
            "exercises": [ex.get("display_name") for ex in info.get("exercises", []) if ex.get("display_name")],
        }
        days[day] = row
    return {
        "available": bool(core.get("available")),
        "id": core.get("id"),
        "plan_id": core.get("plan_id"),
        "title": core.get("title"),
        "name": core.get("name"),
        "is_active": bool(core.get("is_active")),
        "is_archived": bool(core.get("is_archived")),
        "active_version": core.get("active_version"),
        "updated_at": core.get("updated_at"),
        "source": core.get("source"),
        "mode": core.get("mode") or "fixed_week",
        "rolling_week_pattern": core.get("rolling_week_pattern"),
        "weekly_training_status": core.get("weekly_training_status") or {},
        "blocked_rest_days": core.get("blocked_rest_days") or [],
        "gym_days": core.get("gym_days") or [],
        "scheduled_gym_days_per_week": int(core.get("scheduled_gym_days_per_week") or 0),
        "scheduled_rest_days_per_week": int(core.get("scheduled_rest_days_per_week") or 0),
        "active_weekdays": core.get("active_weekdays") or [],
        "days": days,
        "current_exercise_map": core.get("current_exercise_map") or {},
        "detail": "compact",
        **({"reason": core["reason"]} if core.get("reason") else {}),
    }


def _compact_plan_exercise_target(exercise: dict[str, Any]) -> dict[str, Any]:
    allowed = {"exercise_id", "display_name", "name", "variation", "device", "sets", "rep_range", "rpe_list", "note"}
    return {key: value for key, value in exercise.items() if key in allowed and value not in (None, {}, [])}


_TRAINING_CARDIO_KIND_ALIASES = {
    "run": "run",
    "cardio": "cardio",
    "ergo": "ergo",
    "bike": "bike",
    "ergometer": "ergo",
    "row": "row",
    "swim": "swim",
}


def _training_cardio_mode(value: Any) -> str:
    return _TRAINING_CARDIO_KIND_ALIASES.get(str(value or "").strip().lower(), "cardio")


def _is_training_cardio_kind(value: Any) -> bool:
    return str(value or "").strip().lower() in _TRAINING_CARDIO_KIND_ALIASES


def _string_join_nonempty(parts: list[str], separator: str) -> str:
    clean = [str(part).strip() for part in parts if str(part or "").strip()]
    return separator.join(clean)


def _build_training_cardio_display(item: dict[str, Any]) -> str | None:
    duration = _float_or_none(item.get("duration_min"))
    if duration is None:
        duration = _float_or_none(item.get("amount_value")) if str(item.get("amount_unit") or "").strip().lower() == "min" else None
    duration_text = None
    if duration is not None and duration > 0:
        duration_text = f"{int(duration)} min" if float(duration).is_integer() else f"{round(duration, 1)} min"
    intensity = str(item.get("intensity") or "").strip()
    notes = str(item.get("notes") or "").strip()
    main = _string_join_nonempty([duration_text or "", intensity], " ")
    if main and notes:
        return f"{main} @ {notes}"
    return main or notes or str(item.get("title") or item.get("name") or "").strip() or None


def _normalize_training_cardio_item(item: dict[str, Any], event: dict[str, Any]) -> dict[str, Any]:
    out = json.loads(json.dumps(item))
    event_mode = _training_cardio_mode(event.get("mode") or event.get("kind"))
    item_kind = str(out.get("kind") or "").strip().lower()
    item_mode_hint = out.get("mode") or out.get("sport_type")
    if not item_mode_hint and item_kind not in {"", "cardio"}:
        item_mode_hint = item_kind
    mode = _training_cardio_mode(item_mode_hint or event_mode)
    notes = _string_join_nonempty([str(out.get("notes") or "").strip(), str(out.get("note") or "").strip()], " | ")
    duration = _float_or_none(out.get("duration_min"))
    if duration is None:
        unit = str(out.get("amount_unit") or out.get("unit") or "").strip().lower()
        if unit == "min":
            duration = _float_or_none(out.get("amount_value") or out.get("amount"))
    out["kind"] = "cardio"
    out["mode"] = mode
    out["name"] = str(out.get("name") or out.get("title") or event.get("title") or "").strip() or event.get("title") or mode.upper()
    if duration is not None and duration > 0:
        out["duration_min"] = int(duration) if float(duration).is_integer() else round(duration, 1)
        out["amount_value"] = out["duration_min"]
        out["amount_unit"] = "min"
    if notes:
        out["notes"] = notes
    out.pop("note", None)
    display = _build_training_cardio_display(out)
    if display:
        out["display"] = display
        out["display_text"] = display
    return out


def _normalize_create_training_plan_payload(body: dict[str, Any]) -> dict[str, Any]:
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    plan = body.get("plan") if isinstance(body.get("plan"), dict) else payload.get("plan") if isinstance(payload.get("plan"), dict) else {}
    value = body.get("value") if isinstance(body.get("value"), dict) else payload.get("value") if isinstance(payload.get("value"), dict) else {}
    
    if not isinstance(plan, dict):
        plan = {}
    if not isinstance(value, dict):
        value = {}
    
    name = (
        plan.get("name")
        or value.get("name")
        or payload.get("plan_name")
        or payload.get("name")
        or payload.get("title")
        or body.get("plan_name")
        or body.get("name")
        or body.get("title")
        or plan.get("title")
        or value.get("title")
    )
    name = str(name or "").strip()
    if not name:
        raise ValueError("name is required")
    
    block_length = _int_or_none(
        body.get("block_length")
        if body.get("block_length") not in (None, "")
        else payload.get("block_length")
        if payload.get("block_length") not in (None, "")
        else plan.get("block_length") or value.get("block_length")
    )
    if block_length is None:
        weeks_raw = (
            plan.get("weeks")
            if isinstance(plan.get("weeks"), list)
            else value.get("weeks")
            if isinstance(value.get("weeks"), list)
            else payload.get("weeks")
            if isinstance(payload.get("weeks"), list)
            else body.get("weeks")
        )
        block_length = len(weeks_raw) if isinstance(weeks_raw, list) and weeks_raw else 4
    if block_length <= 0:
        raise ValueError("block_length must be positive")
    
    start_date = _parse_date(
        body.get("start_date") or payload.get("start_date") or plan.get("start_date") or value.get("start_date"),
        "start_date",
        required=False
    )
    end_date = _parse_date(
        body.get("end_date") or payload.get("end_date") or plan.get("end_date") or value.get("end_date"),
        "end_date",
        required=False
    )
    
    set_active = _bool_value(
        body.get("set_active")
        if body.get("set_active") is not None
        else payload.get("set_active") if payload.get("set_active") is not None
        else plan.get("set_active") if plan.get("set_active") is not None else value.get("set_active"),
        default=False
    )
    
    replace_active = _bool_value(
        body.get("replace_active")
        if body.get("replace_active") is not None
        else payload.get("replace_active") if payload.get("replace_active") is not None
        else plan.get("replace_active") if plan.get("replace_active") is not None else value.get("replace_active"),
        default=False
    )
    
    days_input = None

    def _coerce_days_input(candidate: Any) -> list[dict[str, Any]] | None:
        if isinstance(candidate, list):
            return candidate
        if not isinstance(candidate, dict):
            return None
        normalized_rows: list[dict[str, Any]] = []
        for raw_day, raw_value in candidate.items():
            if isinstance(raw_value, dict):
                row = json.loads(json.dumps(raw_value))
                row.setdefault("day", raw_day)
                normalized_rows.append(row)
                continue
            if isinstance(raw_value, list):
                normalized_rows.append({"day": raw_day, "events": json.loads(json.dumps(raw_value))})
                continue
            raise ValueError(f"day {raw_day} must map to an object or events list")
        return normalized_rows

    def _coerce_rotation_input(candidate: Any) -> list[dict[str, Any]] | None:
        if isinstance(candidate, dict):
            events = candidate.get("events") if isinstance(candidate.get("events"), list) else candidate.get("items") if isinstance(candidate.get("items"), list) else None
            if events is not None:
                return events
        if isinstance(candidate, list):
            return candidate
        return None
    
    days_input = (
        _coerce_days_input(value.get("days"))
        or _coerce_days_input(plan.get("days"))
        or _coerce_days_input(payload.get("days"))
        or _coerce_days_input(body.get("days"))
    )
    
    if not isinstance(days_input, list):
        if isinstance(plan.get("base_week"), dict):
            base_week_dict = plan["base_week"]
        elif isinstance(value.get("base_week"), dict):
            base_week_dict = value["base_week"]
        elif isinstance(payload.get("base_week"), dict):
            base_week_dict = payload["base_week"]
        elif isinstance(body.get("base_week"), dict):
            base_week_dict = body["base_week"]
        else:
            base_week_dict = None
    else:
        base_week_dict = None
    
    rules = (
        body.get("rules")
        if isinstance(body.get("rules"), dict)
        else payload.get("rules")
        if isinstance(payload.get("rules"), dict)
        else plan.get("rules")
        if isinstance(plan.get("rules"), dict)
        else value.get("rules")
        if isinstance(value.get("rules"), dict)
        else payload.get("week_rules")
        if isinstance(payload.get("week_rules"), dict)
        else body.get("week_rules")
        if isinstance(body.get("week_rules"), dict)
        else plan.get("week_rules")
        if isinstance(plan.get("week_rules"), dict)
        else value.get("week_rules")
        if isinstance(value.get("week_rules"), dict)
        else {}
    )
    
    blocks = (
        body.get("blocks")
        if isinstance(body.get("blocks"), dict)
        else payload.get("blocks")
        if isinstance(payload.get("blocks"), dict)
        else plan.get("blocks")
        if isinstance(plan.get("blocks"), dict)
        else value.get("blocks")
        if isinstance(value.get("blocks"), dict)
        else {}
    )
    
    weeks = (
        plan.get("weeks")
        if isinstance(plan.get("weeks"), list)
        else value.get("weeks")
        if isinstance(value.get("weeks"), list)
        else payload.get("weeks")
        if isinstance(payload.get("weeks"), list)
        else body.get("weeks")
    )
    weeks = weeks if isinstance(weeks, list) else []
    meta_in = plan.get("meta") if isinstance(plan.get("meta"), dict) else value.get("meta") if isinstance(value.get("meta"), dict) else payload.get("meta") if isinstance(payload.get("meta"), dict) else {}
    mode = str(meta_in.get("mode") or plan.get("mode") or value.get("mode") or payload.get("mode") or body.get("mode") or "fixed_week").strip().lower()
    if mode == "rolling":
        mode = "rolling_sequence"
    mode = mode if mode in {"fixed_week", "rolling_sequence"} else "fixed_week"
    periodization_enabled = _bool_value(meta_in.get("periodization_enabled") if meta_in.get("periodization_enabled") is not None else payload.get("periodization_enabled") if payload.get("periodization_enabled") is not None else body.get("periodization_enabled"), default=False)

    base_week: dict[str, list[dict[str, Any]]] = {}
    sequence_input = plan.get("sequence") if isinstance(plan.get("sequence"), list) else value.get("sequence") if isinstance(value.get("sequence"), list) else payload.get("sequence") if isinstance(payload.get("sequence"), list) else body.get("sequence")
    rotation_input = (
        _coerce_rotation_input(plan.get("rotation"))
        or _coerce_rotation_input(value.get("rotation"))
        or _coerce_rotation_input(payload.get("rotation"))
        or _coerce_rotation_input(body.get("rotation"))
    )
    normalized_sequence: list[dict[str, Any]] = []
    if rotation_input is not None and mode != "rolling_sequence":
        mode = "rolling_sequence"
    if isinstance(sequence_input, list) and mode == "rolling_sequence":
        sequence_source = sequence_input
    elif rotation_input is not None and mode == "rolling_sequence":
        sequence_source = rotation_input
    else:
        sequence_source = None
    if isinstance(sequence_source, list) and mode == "rolling_sequence":
        for idx, raw_event in enumerate(sequence_source):
            if not isinstance(raw_event, dict):
                raise ValueError(f"sequence event {idx + 1} must be an object")
            event = json.loads(json.dumps(raw_event))
            kind = str(event.get("kind") or "").strip().lower() or "gym"
            is_cardio_event = _is_training_cardio_kind(kind)
            cardio_mode = _training_cardio_mode(event.get("mode") or kind) if is_cardio_event else None
            event["kind"] = "cardio" if kind == "cardio" else (cardio_mode or kind if is_cardio_event else kind)
            if cardio_mode:
                event["mode"] = cardio_mode
            items = event.get("items")
            if items is None:
                event["items"] = []
            elif not isinstance(items, list):
                raise ValueError(f"items for sequence event {idx + 1} must be a list")
            else:
                normalized_items = []
                for raw_item in items:
                    if not isinstance(raw_item, dict):
                        raise ValueError(f"items for sequence event {idx + 1} must be objects")
                    item_kind = str(raw_item.get("kind") or "").strip().lower()
                    normalized_items.append(_normalize_training_cardio_item(raw_item, event) if (is_cardio_event or _is_training_cardio_kind(item_kind)) else json.loads(json.dumps(raw_item)))
                event["items"] = normalized_items
            normalized_sequence.append(event)
    elif isinstance(base_week_dict, dict):
        for day, events in base_week_dict.items():
            weekday = _normalize_weekday_label(day)
            if not isinstance(events, list):
                raise ValueError(f"events for day {weekday} must be a list")
            base_week[weekday] = json.loads(json.dumps(events))
    elif isinstance(days_input, list):
        for entry in days_input:
            if not isinstance(entry, dict):
                raise ValueError("days entries must be objects")
            weekday = _normalize_weekday_label(entry.get("day"))
            if weekday == "rotation":
                rotation_events = entry.get("events") if isinstance(entry.get("events"), list) else entry.get("items") if isinstance(entry.get("items"), list) else None
                if rotation_events is None:
                    raise ValueError("rotation requires events")
                if mode != "rolling_sequence":
                    mode = "rolling_sequence"
                for idx, raw_event in enumerate(rotation_events):
                    if not isinstance(raw_event, dict):
                        raise ValueError(f"rotation event {idx + 1} must be an object")
                    event = json.loads(json.dumps(raw_event))
                    kind = str(event.get("kind") or "").strip().lower() or "gym"
                    is_cardio_event = _is_training_cardio_kind(kind)
                    cardio_mode = _training_cardio_mode(event.get("mode") or kind) if is_cardio_event else None
                    event["kind"] = "cardio" if kind == "cardio" else (cardio_mode or kind if is_cardio_event else kind)
                    if cardio_mode:
                        event["mode"] = cardio_mode
                    items = event.get("items")
                    if items is None:
                        event["items"] = []
                    elif not isinstance(items, list):
                        raise ValueError(f"items for rotation event {idx + 1} must be a list")
                    normalized_items = []
                    for raw_item in event.get("items") or []:
                        if not isinstance(raw_item, dict):
                            raise ValueError(f"items for rotation event {idx + 1} must be objects")
                        item_kind = str(raw_item.get("kind") or "").strip().lower()
                        normalized_items.append(_normalize_training_cardio_item(raw_item, event) if (is_cardio_event or _is_training_cardio_kind(item_kind)) else json.loads(json.dumps(raw_item)))
                    event["items"] = normalized_items
                    normalized_sequence.append(event)
                continue
            events = entry.get("events") if isinstance(entry.get("events"), list) else entry.get("items") if isinstance(entry.get("items"), list) else None
            if events is None:
                raise ValueError(f"day {weekday} requires events")
            base_week[weekday] = json.loads(json.dumps(events))
    elif mode != "rolling_sequence":
        raise ValueError("create_training_plan requires days/base_week in one of: plan.days, plan.base_week, value.days, payload.days, payload.base_week, payload.plan.days, payload.value.days")

    normalized_days: list[dict[str, Any]] = []
    strength_days = 0
    run_days = 0
    cardio_days = 0
    cardio_events = 0
    cardio_items = 0
    for weekday, events in base_week.items():
        if not isinstance(events, list):
            raise ValueError(f"events for day {weekday} must be a list")
        normalized_events: list[dict[str, Any]] = []
        has_strength = False
        has_run = False
        has_cardio = False
        for idx, raw_event in enumerate(events):
            if not isinstance(raw_event, dict):
                raise ValueError(f"event {idx + 1} for day {weekday} must be an object")
            event = json.loads(json.dumps(raw_event))
            kind = str(event.get("kind") or "").strip().lower()
            if not kind:
                raise ValueError(f"event {idx + 1} for day {weekday} requires kind")
            is_cardio_event = _is_training_cardio_kind(kind)
            cardio_mode = _training_cardio_mode(event.get("mode") or kind) if is_cardio_event else None
            event["kind"] = "cardio" if is_cardio_event else kind
            if cardio_mode:
                event["mode"] = cardio_mode
            if kind == "gym":
                has_strength = True
            if cardio_mode == "run":
                has_run = True
            if is_cardio_event:
                has_cardio = True
                cardio_events += 1
            items = event.get("items")
            if items is None:
                event["items"] = []
            elif not isinstance(items, list):
                raise ValueError(f"items for day {weekday} event {idx + 1} must be a list")
            else:
                normalized_items: list[dict[str, Any]] = []
                for item_idx, raw_item in enumerate(items):
                    if not isinstance(raw_item, dict):
                        raise ValueError(f"item {item_idx + 1} for day {weekday} must be an object")
                    item = json.loads(json.dumps(raw_item))
                    item_kind = str(item.get("kind") or "").strip().lower() or "exercise"
                    if is_cardio_event or _is_training_cardio_kind(item_kind):
                        item = _normalize_training_cardio_item(item, event)
                        cardio_items += 1
                    else:
                        item["kind"] = item_kind
                    if item_kind == "exercise" and not str(item.get("name") or "").strip():
                        raise ValueError(f"exercise item {item_idx + 1} for day {weekday} requires name")
                    normalized_items.append(item)
                event["items"] = normalized_items
            normalized_events.append(event)
        if has_strength:
            strength_days += 1
        if has_run:
            run_days += 1
        if has_cardio:
            cardio_days += 1
        normalized_days.append({"day": weekday, "events": normalized_events})
        base_week[weekday] = normalized_events

    normalized_weeks: list[dict[str, Any]] = []
    for idx, week in enumerate(weeks):
        if not isinstance(week, dict):
            raise ValueError("weeks entries must be objects")
        row = json.loads(json.dumps(week))
        if row.get("week") in (None, ""):
            row["week"] = idx + 1
        normalized_weeks.append(row)

    rolling_pattern = meta_in.get("rolling_week_pattern") if isinstance(meta_in.get("rolling_week_pattern"), dict) else plan.get("rolling_week_pattern") if isinstance(plan.get("rolling_week_pattern"), dict) else value.get("rolling_week_pattern") if isinstance(value.get("rolling_week_pattern"), dict) else payload.get("rolling_week_pattern") if isinstance(payload.get("rolling_week_pattern"), dict) else body.get("rolling_week_pattern") if isinstance(body.get("rolling_week_pattern"), dict) else {
        "Mo": "train",
        "Di": "optional",
        "Mi": "train",
        "Do": "rest",
        "Fr": "train",
        "Sa": "optional",
        "So": "rest",
    }
    meta = {
        "source": "actions_v2.create_training_plan",
        "created_by": "custom_gpt",
        "block_length": block_length,
        "mode": mode,
        "periodization_enabled": periodization_enabled,
        "rolling_week_pattern": rolling_pattern,
    }
    weekly_reset = meta_in.get("weekly_reset")
    if weekly_reset is None:
        weekly_reset = plan.get("weekly_reset")
    if weekly_reset is None:
        weekly_reset = value.get("weekly_reset")
    if weekly_reset is None:
        weekly_reset = payload.get("weekly_reset")
    if weekly_reset is None:
        weekly_reset = body.get("weekly_reset")
    if weekly_reset is not None:
        meta["weekly_reset"] = _bool_value(weekly_reset, default=False)
    exposures_before_recovery = (
        meta_in.get("gym_exposures_before_run_recovery_day")
        if meta_in.get("gym_exposures_before_run_recovery_day") not in (None, "")
        else plan.get("gym_exposures_before_run_recovery_day")
        if plan.get("gym_exposures_before_run_recovery_day") not in (None, "")
        else value.get("gym_exposures_before_run_recovery_day")
        if value.get("gym_exposures_before_run_recovery_day") not in (None, "")
        else payload.get("gym_exposures_before_run_recovery_day")
        if payload.get("gym_exposures_before_run_recovery_day") not in (None, "")
        else body.get("gym_exposures_before_run_recovery_day")
    )
    exposures_before_recovery = _int_or_none(exposures_before_recovery)
    if exposures_before_recovery is not None:
        meta["gym_exposures_before_run_recovery_day"] = exposures_before_recovery
    if start_date:
        meta["start_date"] = start_date
    if end_date:
        meta["end_date"] = end_date

    return {
        "name": name,
        "plan_name": name,
        "focus": str(body.get("focus") or payload.get("focus") or plan.get("focus") or plan.get("goal") or value.get("focus") or value.get("goal") or payload.get("goal") or body.get("goal") or "").strip(),
        "block_length": int(block_length),
        "start_date": start_date,
        "end_date": end_date,
        "set_active": set_active,
        "replace_active": _bool_value(body.get("replace_active") if body.get("replace_active") is not None else payload.get("replace_active") if payload.get("replace_active") is not None else plan.get("replace_active") if plan.get("replace_active") is not None else value.get("replace_active"), default=set_active),
        "base_week": base_week,
        "days": normalized_days,
        "sequence": normalized_sequence,
        "weeks": normalized_weeks,
        "rules": rules,
        "blocks": blocks or {"weeks": normalized_weeks},
        "plan_json": {"name": name, "meta": meta, "base_week": base_week, "days": normalized_days, "sequence": normalized_sequence, "weeks": normalized_weeks},
        "warnings": [],
        "unresolved_items": [],
        "days_count": len(normalized_days),
        "strength_days": strength_days,
        "run_days": run_days,
        "cardio_days": cardio_days,
        "cardio_events": cardio_events,
        "cardio_items": cardio_items,
        "weeks_count": len(normalized_weeks),
        "sequence_count": len(normalized_sequence),
    }


def _create_training_plan_live(body: dict[str, Any]) -> dict[str, Any]:
    normalized = _normalize_create_training_plan_payload(body)
    conn = connections.get_plans_db()
    conn.row_factory = sqlite3.Row
    source = "plans"
    affected_resources = ["plans.actions_v2_command_log"]
    try:
        now = datetime.utcnow().isoformat()
        plan_json = normalized["plan_json"]
        rules_json = normalized.get("rules") or {}
        blocks_json = normalized.get("blocks") or {"weeks": normalized.get("weeks") or []}
        set_active = bool(normalized.get("set_active"))
        cur = conn.cursor()
        cur.execute("BEGIN")
        if _table_exists(conn, "gym_plans"):
            source = "gym_plans"
            if set_active:
                cur.execute("UPDATE gym_plans SET is_active=0 WHERE is_active=1")
                if _table_exists(conn, "plans"):
                    cur.execute("UPDATE plans SET is_active=0 WHERE is_active=1")
            cur.execute(
                """
                INSERT INTO gym_plans (title, focus, plan_json, is_active, is_archived, created_at, updated_at, rules_json, blocks_json)
                VALUES (?, ?, ?, ?, 0, ?, ?, ?, ?)
                """,
                (
                    normalized["name"],
                    normalized.get("focus") or "",
                    json.dumps(plan_json, ensure_ascii=False),
                    1 if set_active else 0,
                    now,
                    now,
                    json.dumps(rules_json, ensure_ascii=False),
                    json.dumps(blocks_json, ensure_ascii=False),
                ),
            )
            plan_id = int(cur.lastrowid)
            affected_resources.insert(0, "plans.gym_plans")
        elif _table_exists(conn, "plans"):
            if set_active:
                cur.execute("UPDATE plans SET is_active=0 WHERE is_active=1")
            cur.execute(
                """
                INSERT INTO plans (name, data, block_length, is_active, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (
                    normalized["name"],
                    json.dumps(plan_json, ensure_ascii=False),
                    int(normalized["block_length"]),
                    1 if set_active else 0,
                    now,
                    now,
                ),
            )
            plan_id = int(cur.lastrowid)
            affected_resources.insert(0, "plans.plans")
        else:
            raise ValueError("no writable training plan table found")
        conn.commit()
    finally:
        conn.close()

    training_conn = connections.get_training_db()
    try:
        if _table_exists(training_conn, "autopilot_week"):
            training_conn.execute("DELETE FROM autopilot_week")
            training_conn.commit()
    finally:
        training_conn.close()

    active_plan_after = _compact_plan_core(_plan_core(_active_plan()))
    return {
        "plan_id": plan_id,
        "source": source,
        "plan_name": normalized["name"],
        "set_active": bool(normalized.get("set_active")),
        "days_count": normalized["days_count"],
        "strength_days": normalized["strength_days"],
        "run_days": normalized["run_days"],
        "cardio_days": normalized["cardio_days"],
        "cardio_events": normalized["cardio_events"],
        "cardio_items": normalized["cardio_items"],
        "weeks_count": normalized["weeks_count"],
        "warnings": normalized.get("warnings") or [],
        "unresolved_items": normalized.get("unresolved_items") or [],
        "summary": {
            "days_count": normalized["days_count"],
            "strength_days": normalized["strength_days"],
            "run_days": normalized["run_days"],
            "cardio_days": normalized["cardio_days"],
            "cardio_events": normalized["cardio_events"],
            "cardio_items": normalized["cardio_items"],
            "weeks_count": normalized["weeks_count"],
        },
        "active_plan_after": active_plan_after,
        "_affected_resources": affected_resources,
    }


def _training_plan_summary_from_plan_json(plan_json: dict[str, Any]) -> dict[str, Any]:
    core = _plan_core({"id": None, "name": str(plan_json.get("name") or plan_json.get("title") or "Plan"), "is_active": False, "is_archived": False, "updated_at": None, "source": "gym_plans", "plan": plan_json})
    strength_days = 0
    run_days = 0
    cardio_days = 0
    cardio_events = 0
    cardio_items = 0
    concrete_days = [(day, info) for day, info in (core.get("days") or {}).items() if day != "rotation"]
    for _day, info in concrete_days:
        events = info.get("events") or []
        has_strength = False
        has_run = False
        has_cardio = False
        for event in events:
            if not isinstance(event, dict):
                continue
            kind = str(event.get("kind") or "").strip().lower()
            if kind == "gym":
                has_strength = True
            if kind == "cardio":
                has_cardio = True
                cardio_events += 1
                mode = str(event.get("mode") or "").strip().lower()
                if mode == "run":
                    has_run = True
                for item in event.get("items") or []:
                    if isinstance(item, dict) and str(item.get("kind") or "").strip().lower() == "cardio":
                        cardio_items += 1
        if has_strength:
            strength_days += 1
        if has_run:
            run_days += 1
        if has_cardio:
            cardio_days += 1
    rotation_info = ((core.get("days") or {}).get("rotation")) or {}
    rotation_events = rotation_info.get("events") or []
    if isinstance(rotation_events, list):
        rotation_strength_days = sum(
            1
            for event in rotation_events
            if isinstance(event, dict) and str(event.get("kind") or "").strip().lower() == "gym"
        )
        # In rolling mode weekday gym entries are mirrors/anchors, while the
        # sequence is the source of truth for strength exposure count.
        if rotation_strength_days:
            strength_days = rotation_strength_days
    return {
        "days_count": len(concrete_days),
        "strength_days": strength_days,
        "run_days": run_days,
        "cardio_days": cardio_days,
        "cardio_events": cardio_events,
        "cardio_items": cardio_items,
        "weeks_count": len(plan_json.get("weeks") or []) if isinstance(plan_json.get("weeks"), list) else 0,
    }


def _text_tokens(value: Any) -> set[str]:
    text = str(value or "").lower()
    return {token for token in re.split(r"[^a-z0-9]+", text) if token}


def _titleish_cardio_match(requested: str, available: str) -> bool:
    req_tokens = _text_tokens(requested)
    avail_tokens = _text_tokens(available)
    if not req_tokens or not avail_tokens:
        return False
    meaningful_req = {token for token in req_tokens if token not in {"ergo", "run", "cardio", "bike", "ergometer"}}
    meaningful_avail = {token for token in avail_tokens if token not in {"ergo", "run", "cardio", "bike", "ergometer"}}
    target_req = meaningful_req or req_tokens
    target_avail = meaningful_avail or avail_tokens
    return bool(target_req & target_avail) or target_req.issubset(avail_tokens) or target_avail.issubset(req_tokens)


def _parse_legacy_cardio_text(text: Any) -> dict[str, Any]:
    raw = str(text or "").strip()
    if not raw:
        return {}
    match = re.search(r"(\d+(?:[.,]\d+)?)\s*min", raw, flags=re.I)
    duration_min = None
    if match:
        try:
            duration_min = float(match.group(1).replace(",", "."))
        except Exception:
            duration_min = None
    remainder = raw
    if match:
        remainder = (raw[: match.start()] + raw[match.end() :]).strip()
    intensity = ""
    notes = ""
    if "@" in remainder:
        left, right = remainder.split("@", 1)
        intensity = left.strip(" -–—")
        notes = right.strip()
    else:
        tokens = remainder.split(None, 1)
        if tokens:
            intensity = tokens[0].strip(" -–—")
            notes = tokens[1].strip() if len(tokens) > 1 else ""
    out: dict[str, Any] = {}
    if duration_min is not None:
        out["duration_min"] = int(duration_min) if float(duration_min).is_integer() else round(duration_min, 1)
    if intensity:
        out["intensity"] = intensity
    if notes:
        out["notes"] = notes
    return out


def _event_cardio_hint_text(event: dict[str, Any]) -> str:
    bits = [str(event.get("title") or "").strip(), str(event.get("kind") or "").strip()]
    for item in event.get("items") or []:
        if not isinstance(item, dict):
            continue
        bits.extend(
            [
                str(item.get("kind") or "").strip(),
                str(item.get("text") or "").strip(),
                str(item.get("display") or item.get("display_text") or "").strip(),
                str(item.get("name") or "").strip(),
                str(item.get("notes") or item.get("note") or "").strip(),
            ]
        )
    return " ".join(bit for bit in bits if bit)


def _is_cardio_event_for_patch(event: dict[str, Any]) -> bool:
    kind = str(event.get("kind") or "").strip().lower()
    if _is_training_cardio_kind(kind) or kind == "cardio":
        return True
    items = event.get("items") if isinstance(event.get("items"), list) else []
    for item in items:
        if not isinstance(item, dict):
            continue
        item_kind = str(item.get("kind") or "").strip().lower()
        if item_kind in {"cardio", "run", "run_detail", "ergo"} or _is_training_cardio_kind(item_kind):
            return True
    hint = _event_cardio_hint_text(event).lower()
    return any(token in hint for token in ("z2", "ergo", "run", "cardio", "locker", "nasal"))


def _cardio_event_preview(event: dict[str, Any]) -> dict[str, Any]:
    previews = []
    for item in event.get("items") or []:
        if not isinstance(item, dict):
            continue
        text = str(item.get("display") or item.get("display_text") or item.get("text") or item.get("name") or "").strip()
        if text:
            previews.append(text)
    return {"title": event.get("title"), "kind": event.get("kind"), "time": event.get("time"), "items_preview": previews}


def _select_cardio_event_for_patch(events: list[dict[str, Any]], requested_title: str) -> tuple[int | None, dict[str, Any] | None, list[dict[str, Any]], str | None]:
    cardio_candidates = [(idx, event) for idx, event in enumerate(events) if isinstance(event, dict) and _is_cardio_event_for_patch(event)]
    previews = [_cardio_event_preview(event) for _, event in cardio_candidates]
    if not cardio_candidates:
        return None, None, previews, "cardio_not_found"
    if requested_title.strip():
        matched = []
        for idx, event in cardio_candidates:
            if _titleish_cardio_match(requested_title, str(event.get("title") or "")) or _titleish_cardio_match(requested_title, _event_cardio_hint_text(event)):
                matched.append((idx, event))
        if len(matched) == 1:
            return matched[0][0], matched[0][1], previews, None
        if len(matched) > 1:
            return None, None, previews, "ambiguous_cardio"
    if len(cardio_candidates) == 1:
        idx, event = cardio_candidates[0]
        return idx, event, previews, None
    return None, None, previews, "ambiguous_cardio"


def _normalize_patched_cardio_event(event: dict[str, Any], patch: dict[str, Any], requested_title: str) -> dict[str, Any]:
    existing = json.loads(json.dumps(event))
    existing_kind = str(existing.get("kind") or "").strip().lower()
    existing_mode_hint = existing.get("mode")
    if not existing_mode_hint and existing_kind in {"ergo", "run", "bike", "ergometer"}:
        existing_mode_hint = existing_kind
    existing_mode = _training_cardio_mode(existing_mode_hint or "cardio")
    parsed_legacy = {}
    first_item = ((existing.get("items") or [None])[0]) if isinstance(existing.get("items"), list) and existing.get("items") else None
    if isinstance(first_item, dict) and str(first_item.get("kind") or "").strip().lower() == "run_detail":
        parsed_legacy = _parse_legacy_cardio_text(first_item.get("text"))
    merged_item = {}
    if isinstance(first_item, dict):
        merged_item.update(first_item)
    merged_item.update(parsed_legacy)
    merged_item.update(patch)
    title = str(patch.get("title") or requested_title or existing.get("title") or "").strip()
    requested_mode_hint = "ergo" if "ergo" in str(requested_title or "").strip().lower() else None
    mode = _training_cardio_mode(patch.get("mode") or requested_mode_hint or merged_item.get("mode") or existing_mode)
    if not title:
        title = "Ergo – Z2" if mode == "ergo" else merged_item.get("name") or existing.get("title") or "Cardio"
    if mode == "ergo" and title.lower() == "z2":
        title = "Ergo – Z2"
    normalized = _normalize_create_training_plan_payload(
        {
            "name": "patched_cardio",
            "days": [
                {
                    "day": "Mo",
                    "events": [
                        {
                            **existing,
                            "kind": "cardio",
                            "mode": mode,
                            "title": title,
                            "time": patch.get("time", existing.get("time")),
                            "items": [
                                {
                                    "kind": "cardio",
                                    "name": str(merged_item.get("name") or title).strip() or title,
                                    "mode": mode,
                                    "duration_min": merged_item.get("duration_min"),
                                    "amount_value": merged_item.get("amount_value"),
                                    "amount_unit": merged_item.get("amount_unit") or merged_item.get("unit"),
                                    "intensity": merged_item.get("intensity"),
                                    "notes": merged_item.get("notes") or merged_item.get("note"),
                                }
                            ],
                        }
                    ],
                }
            ],
        }
    )
    out_event = normalized["base_week"]["Mo"][0]
    out_event["mode"] = mode
    for item in out_event.get("items") or []:
        if isinstance(item, dict):
            item["mode"] = mode
            if item.get("display") and not item.get("display_text"):
                item["display_text"] = item["display"]
    return out_event


def _load_gym_plan_row(conn: sqlite3.Connection, plan_id: int) -> sqlite3.Row | None:
    return conn.execute("SELECT id, title, focus, plan_json, is_active, is_archived, created_at, updated_at, rules_json, blocks_json FROM gym_plans WHERE id=?", (plan_id,)).fetchone()


def _compact_training_plan_row(row: sqlite3.Row | dict[str, Any]) -> dict[str, Any]:
    data = dict(row)
    plan_json = _json_loads(data.get("plan_json"), {}) or {}
    return {
        "id": data.get("id"),
        "title": data.get("title"),
        "is_active": bool(data.get("is_active")),
        "is_archived": bool(data.get("is_archived")),
        "updated_at": data.get("updated_at"),
        "summary": _training_plan_summary_from_plan_json(plan_json),
    }


def _list_training_plans_compact(include_archived: bool = True) -> list[dict[str, Any]]:
    conn = connections.get_plans_db()
    conn.row_factory = sqlite3.Row
    try:
        if not _table_exists(conn, "gym_plans"):
            return []
        sql = "SELECT id, title, focus, plan_json, is_active, is_archived, created_at, updated_at, rules_json, blocks_json FROM gym_plans"
        if not include_archived:
            sql += " WHERE COALESCE(is_archived, 0)=0"
        sql += " ORDER BY is_active DESC, updated_at DESC, id DESC"
        return [_compact_training_plan_row(row) for row in conn.execute(sql).fetchall()]
    finally:
        conn.close()


def _activate_training_plan(plan_id: int, *, dry_run: bool = False) -> dict[str, Any]:
    conn = connections.get_plans_db()
    conn.row_factory = sqlite3.Row
    try:
        if not _table_exists(conn, "gym_plans"):
            raise ValueError("schema_not_supported")
        target = _load_gym_plan_row(conn, plan_id)
        if not target:
            raise ValueError("plan_not_found")
        if int(target["is_archived"] or 0):
            raise ValueError("plan_archived")
        previous = conn.execute("SELECT id, title FROM gym_plans WHERE is_active=1 ORDER BY updated_at DESC, id DESC LIMIT 1").fetchone()
        if dry_run:
            return {
                "plan_id": plan_id,
                "current_active_plan": dict(previous) if previous else None,
                "target_plan": _compact_training_plan_row(target),
                "will_change": not bool(target["is_active"]),
            }
        now = datetime.utcnow().isoformat()
        cur = conn.cursor()
        cur.execute("BEGIN")
        cur.execute("UPDATE gym_plans SET is_active=0 WHERE is_active=1")
        if _table_exists(conn, "plans"):
            cur.execute("UPDATE plans SET is_active=0 WHERE is_active=1")
        cur.execute("UPDATE gym_plans SET is_active=1, updated_at=? WHERE id=?", (now, plan_id))
        conn.commit()
        return {
            "plan_id": plan_id,
            "activated": True,
            "previous_active_plan_id": int(previous["id"]) if previous else None,
            "active_plan_after": _compact_plan_core(_plan_core(_active_plan())),
            "_affected_resources": ["plans.gym_plans", "plans.actions_v2_command_log"],
        }
    finally:
        conn.close()


def _archive_training_plan(body: dict[str, Any], *, dry_run: bool = False) -> dict[str, Any]:
    plan_id = _int_or_none(body.get("plan_id") if body.get("plan_id") not in (None, "") else body.get("id"))
    if plan_id is None:
        raise ValueError("plan_id is required")
    allow_archive_active = _bool_value(body.get("allow_archive_active"), default=False)
    conn = connections.get_plans_db()
    conn.row_factory = sqlite3.Row
    try:
        if not _table_exists(conn, "gym_plans"):
            raise ValueError("schema_not_supported")
        if "is_archived" not in _columns(conn, "gym_plans"):
            raise ValueError("schema_not_supported")
        row = _load_gym_plan_row(conn, plan_id)
        if not row:
            raise ValueError("plan_not_found")
        if bool(row["is_active"]) and not allow_archive_active:
            raise ValueError("cannot_archive_active_plan")
        if dry_run:
            return {"plan_id": plan_id, "plan": _compact_training_plan_row(row), "archive_reason": body.get("archive_reason"), "will_change": not bool(row["is_archived"])}
        now = datetime.utcnow().isoformat()
        conn.execute("UPDATE gym_plans SET is_archived=1, is_active=0, updated_at=? WHERE id=?", (now, plan_id))
        conn.commit()
        return {"plan_id": plan_id, "archived": True, "_affected_resources": ["plans.gym_plans", "plans.actions_v2_command_log"]}
    finally:
        conn.close()


def _delete_training_plan(body: dict[str, Any], *, dry_run: bool = False) -> dict[str, Any]:
    plan_id = _int_or_none(body.get("plan_id") if body.get("plan_id") not in (None, "") else body.get("id"))
    if plan_id is None:
        raise ValueError("plan_id is required")
    if not _bool_value(body.get("hard_delete"), default=False):
        raise ValueError("hard_delete=true is required")
    allow_delete_active = _bool_value(body.get("allow_delete_active"), default=False)
    conn = connections.get_plans_db()
    conn.row_factory = sqlite3.Row
    try:
        if not _table_exists(conn, "gym_plans"):
            raise ValueError("schema_not_supported")
        row = _load_gym_plan_row(conn, plan_id)
        if not row:
            raise ValueError("plan_not_found")
        if bool(row["is_active"]) and not allow_delete_active:
            raise ValueError("cannot_delete_active_plan")
        if dry_run:
            return {"plan_id": plan_id, "plan": _compact_training_plan_row(row), "will_delete": True}
        deleted = conn.execute("DELETE FROM gym_plans WHERE id=?", (plan_id,))
        conn.commit()
        return {"plan_id": plan_id, "deleted": bool(deleted.rowcount), "_affected_resources": ["plans.gym_plans", "plans.actions_v2_command_log"]}
    finally:
        conn.close()


def _replace_training_plan(body: dict[str, Any], *, dry_run: bool = False) -> dict[str, Any]:
    plan_id = _int_or_none(body.get("plan_id") if body.get("plan_id") not in (None, "") else body.get("id"))
    if plan_id is None:
        raise ValueError("plan_id is required")
    replace_with = body.get("replace_with") if isinstance(body.get("replace_with"), dict) else {}
    if not replace_with:
        raise ValueError("replace_with is required")
    conn = connections.get_plans_db()
    conn.row_factory = sqlite3.Row
    try:
        row = _load_gym_plan_row(conn, plan_id) if _table_exists(conn, "gym_plans") else None
        if not row:
            raise ValueError("plan_not_found")
        expected_updated_at = str(body.get("expected_updated_at") or "").strip()
        if expected_updated_at and str(row["updated_at"] or "") != expected_updated_at:
            raise ValueError("stale_plan")
        normalized = _normalize_create_training_plan_payload(replace_with)
        old_summary = _training_plan_summary_from_plan_json(_json_loads(row["plan_json"], {}) or {})
        new_summary = {
            "days_count": normalized["days_count"],
            "strength_days": normalized["strength_days"],
            "run_days": normalized["run_days"],
            "cardio_days": normalized["cardio_days"],
            "weeks_count": normalized["weeks_count"],
        }
        if dry_run:
            return {"plan_id": plan_id, "normalized_replacement": normalized["plan_json"], "diff_summary": {"old_days_count": old_summary["days_count"], "new_days_count": new_summary["days_count"], "old_strength_days": old_summary["strength_days"], "new_strength_days": new_summary["strength_days"], "old_cardio_days": old_summary["cardio_days"], "new_cardio_days": new_summary["cardio_days"], "old_weeks_count": old_summary["weeks_count"], "new_weeks_count": new_summary["weeks_count"]}}
        now = datetime.utcnow().isoformat()
        set_active_override = body.get("set_active")
        if _bool_value(set_active_override, default=False):
            conn.execute("UPDATE gym_plans SET is_active=0 WHERE is_active=1")
        conn.execute(
            """
            UPDATE gym_plans
            SET title=?, focus=?, plan_json=?, rules_json=?, blocks_json=?, is_active=?, updated_at=?
            WHERE id=?
            """,
            (
                normalized["name"],
                normalized.get("focus") or "",
                json.dumps(normalized["plan_json"], ensure_ascii=False),
                json.dumps(normalized.get("rules") or {}, ensure_ascii=False),
                json.dumps(normalized.get("blocks") or {"weeks": normalized.get("weeks") or []}, ensure_ascii=False),
                int(row["is_active"]) if set_active_override is None else (1 if _bool_value(set_active_override, default=False) else 0),
                now,
                plan_id,
            ),
        )
        conn.commit()
        updated = _load_gym_plan_row(conn, plan_id)
        return {"plan_id": plan_id, "updated": True, "changed": True, "updated_plan_after": _compact_training_plan_row(updated or row), "_affected_resources": ["plans.gym_plans", "plans.actions_v2_command_log"]}
    finally:
        conn.close()


def _patch_training_plan(body: dict[str, Any], *, dry_run: bool = False) -> dict[str, Any]:
    normalized_body, error_response = _normalize_liva_training_patch_body(body, dry_run=dry_run, confirm=_bool_value(body.get("confirm"), default=False))
    if error_response is not None:
        payload, _status = error_response
        error = payload.get("error") if isinstance(payload.get("error"), dict) else {}
        raise ValueError(str(error.get("code") or "invalid_patch_request"))
    assert normalized_body is not None
    plan_id = int(normalized_body["plan_id"])
    operations = normalized_body["operations"]
    legacy_ops = [op for op in operations if isinstance(op, dict) and str(op.get("op") or "").strip() != "update_exercise_note"]
    note_ops = [op for op in operations if isinstance(op, dict) and str(op.get("op") or "").strip() == "update_exercise_note"]
    legacy_only_names = {
        "set_focus",
        "replace_day_events",
        "add_event_to_day",
        "remove_event_from_day",
        "replace_exercise_target",
        "replace_cardio",
        "update_week_rule",
        "set_plan_mode",
        "set_periodization_enabled",
        "replace_sequence",
        "move_sequence_event",
    }
    if legacy_ops and not note_ops and all(
        str(op.get("op") or "").strip() in legacy_only_names for op in legacy_ops
    ):
        return _patch_training_plan_legacy_only(plan_id, operations, dry_run=dry_run)

    detail_before = get_training_plan_detail(plan_id)
    transformed_operations: list[dict[str, Any]] = []
    verification_targets: list[dict[str, Any]] = []
    changed_notes_count = 0
    matched_count = 0
    unmatched_count = 0
    operations_failed: list[dict[str, Any]] = []

    for raw_op in operations:
        if not isinstance(raw_op, dict):
            operations_failed.append({"op": None, "reason": "invalid_operation"})
            unmatched_count += 1
            continue
        op = str(raw_op.get("op") or "").strip()
        transformed, verification_target, changed_note = _normalize_training_plan_patch_operation(raw_op, detail_before)
        if transformed is None:
            operations_failed.append({"op": op or None, "reason": "unsupported_operation"})
            unmatched_count += 1
            continue
        transformed_operations.append(transformed)
        if verification_target is not None:
            verification_targets.append(verification_target)
        if changed_note:
            changed_notes_count += 1
        matched_count += 1

    if operations_failed and len(operations_failed) == len(operations):
        return {
            "ok": False,
            "error": {
                "code": "operations_failed",
                "message": "No training-plan patch operations could be matched.",
                "failed_operations": operations_failed,
            },
            "plan_id": plan_id,
            "operations_count": len(operations),
            "matched_count": matched_count,
            "unmatched_count": unmatched_count,
            "changed_notes_count": changed_notes_count,
            "operations_applied": 0,
            "operations_failed": operations_failed,
            "warnings": [],
        }
    if operations_failed:
        return {
            "ok": False,
            "error": {
                "code": "operations_failed",
                "message": "Training-plan patch stopped before writing because at least one operation could not be matched.",
                "failed_operations": operations_failed,
            },
            "plan_id": plan_id,
            "operations_count": len(operations),
            "matched_count": matched_count,
            "unmatched_count": unmatched_count,
            "changed_notes_count": changed_notes_count,
            "operations_applied": 0,
            "operations_failed": operations_failed,
            "warnings": [],
        }

    preview = {
        "plan_id": plan_id,
        "operations_count": len(operations),
        "matched_count": matched_count,
        "unmatched_count": unmatched_count,
        "changed_notes_count": changed_notes_count,
        "operations_failed": operations_failed,
    }
    if dry_run:
        result = patch_training_plan_v2(plan_id, transformed_operations, dry_run=True)
        return {
            **preview,
            "changed": bool(result.get("diff", {}).get("changed")),
            "operations_applied": len(transformed_operations),
            "warnings": result.get("warnings") or [],
            "updated_plan_after": _training_plan_summary_from_plan_json((_load_training_plan_by_id(plan_id) or {}).get("plan") or {}) if False else result.get("after", {}).get("counts", {}),
        }
    if note_ops and not legacy_ops:
        return _patch_training_plan_notes_live(plan_id, operations, transformed_operations, verification_targets, preview)

    result = patch_training_plan_v2(plan_id, transformed_operations, dry_run=False)
    verification_failures = _verify_training_plan_targets_in_detail(get_training_plan_detail(plan_id), verification_targets)
    if verification_failures:
        return {
            "ok": False,
            "error": {
                "code": "patch_verification_failed",
                "message": "Training-plan patch wrote data, but canonical readback did not match the requested after-state.",
                "failed_operations": verification_failures,
            },
            **preview,
            "changed": bool(result.get("diff", {}).get("changed")),
            "operations_applied": len(transformed_operations),
            "warnings": result.get("warnings") or [],
        }

    return {
        **preview,
        "changed": bool(result.get("diff", {}).get("changed")),
        "operations_applied": len(transformed_operations),
        "warnings": result.get("warnings") or [],
        "updated_plan_after": _compact_plan_core(_plan_core(_load_training_plan_by_id(plan_id))),
        "_affected_resources": ["training_plan", "plans.gym_plans", "plans.actions_v2_command_log"],
    }


def _resolve_training_plan_exercise_match(detail_before: dict[str, Any], raw_op: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]] | tuple[None, None]:
    match = raw_op.get("match") if isinstance(raw_op.get("match"), dict) else {}
    requested_day = match.get("day") or raw_op.get("day")
    requested_exercise = match.get("exercise") or match.get("name") or raw_op.get("exercise") or raw_op.get("name")
    requested_variation = match.get("variation") or match.get("device") or raw_op.get("variation") or raw_op.get("device")
    requested_exercise_id = match.get("exercise_id") or raw_op.get("exercise_id")
    requested_canonical_id = match.get("canonical_id") or raw_op.get("canonical_id")
    requested_exercise_path = match.get("exercise_path") or raw_op.get("exercise_path")
    if requested_exercise_path not in (None, ""):
        parsed = _parse_training_exercise_path(str(requested_exercise_path))
        if parsed is not None:
            day_index, workout_index, exercise_index = parsed
            exercise = (((detail_before.get("days") or [])[day_index].get("workouts") or [])[workout_index].get("exercises") or [])[exercise_index]
            return (
                {
                    "day_index": day_index,
                    "workout_index": workout_index,
                    "exercise_index": exercise_index,
                    "exercise_path": requested_exercise_path,
                    "exercise_id": exercise.get("exercise_id"),
                    "canonical_id": exercise.get("canonical_id"),
                    "name": exercise.get("name"),
                },
                {
                    "day": (detail_before.get("days") or [])[day_index].get("day_id"),
                    "exercise": exercise.get("name"),
                    "variation": exercise.get("variation"),
                    "exercise_id": exercise.get("exercise_id"),
                    "canonical_id": exercise.get("canonical_id"),
                },
            )
    for day_index, day in enumerate(detail_before.get("days") or []):
        day_matches = requested_day in (None, "") or any(
            _norm_compact(value) == _norm_compact(requested_day)
            for value in (day.get("label"), day.get("title"), day.get("day_id"))
            if value not in (None, "")
        )
        for workout_index, workout in enumerate(day.get("workouts") or []):
            workout_matches = requested_day in (None, "") or any(
                _norm_compact(value) == _norm_compact(requested_day)
                for value in (workout.get("title"), workout.get("label"), workout.get("day"))
                if value not in (None, "")
            )
            if not day_matches and not workout_matches:
                continue
            for exercise_index, exercise in enumerate(workout.get("exercises") or []):
                exercise_name = exercise.get("name")
                exercise_variation = exercise.get("variation") or exercise.get("device")
                display_name = f"{exercise_name} ({exercise_variation})" if exercise_name and exercise_variation else exercise_name
                if requested_exercise_id not in (None, "") and str(exercise.get("exercise_id") or "") != str(requested_exercise_id):
                    continue
                if requested_canonical_id not in (None, "") and str(exercise.get("canonical_id") or "") != str(requested_canonical_id):
                    continue
                if requested_exercise not in (None, "") and _norm_compact(exercise_name) != _norm_compact(requested_exercise) and _norm_compact(display_name) != _norm_compact(requested_exercise):
                    continue
                if requested_variation not in (None, "") and _norm_compact(exercise_variation) != _norm_compact(requested_variation):
                    continue
                return (
                    {
                        "day_index": day_index,
                        "workout_index": workout_index,
                        "exercise_index": exercise_index,
                        "exercise_path": exercise.get("exercise_path"),
                        "exercise_id": exercise.get("exercise_id"),
                        "canonical_id": exercise.get("canonical_id"),
                        "name": exercise_name,
                    },
                    {
                        "day": day.get("day_id"),
                        "exercise": exercise_name,
                        "variation": exercise_variation,
                        "exercise_id": exercise.get("exercise_id"),
                        "canonical_id": exercise.get("canonical_id"),
                    },
                )
    return None, None


def _normalize_training_plan_patch_operation(raw_op: dict[str, Any], detail_before: dict[str, Any]) -> tuple[dict[str, Any] | None, dict[str, Any] | None, bool]:
    op = str(raw_op.get("op") or "").strip()
    if op in {"rename_plan", "rename_day", "rename_workout", "set_workout_note", "add_exercise", "delete_exercise", "move_exercise", "add_set", "delete_set", "update_periodization", "update_progression_rule", "update_caps", "create_exercise", "update_exercise", "overwrite_plan", "duplicate_plan", "set_active_plan", "archive_plan", "unarchive_plan", "soft_delete_plan"}:
        return raw_op, None, False
    match, identity = _resolve_training_plan_exercise_match(detail_before, raw_op)
    if op in {"update_exercise_note", "update_note"}:
        if not match or not identity:
            return None, None, False
        next_note = str(raw_op.get("note") or "").strip() or None
        verification = {**identity, "expected_note": next_note, "expected_rep_range": None, "expected_target_rpe": None, "expected_sets": None}
        exercise = (((detail_before.get("days") or [])[match["day_index"]].get("workouts") or [])[match["workout_index"]].get("exercises") or [])[match["exercise_index"]]
        previous_note = str(exercise.get("notes") or "").strip() or None
        return ({"op": "update_exercise_note", "match": match, "note": next_note}, verification, previous_note != next_note)
    if op in {"replace_exercise_target", "update_exercise_target", "change_sets", "change_rep_range", "change_rpe"}:
        if not match or not identity:
            return None, None, False
        patch = raw_op.get("patch") if isinstance(raw_op.get("patch"), dict) else raw_op
        normalized_patch: dict[str, Any] = {}
        if patch.get("sets") is not None:
            normalized_patch["target_sets"] = patch.get("sets")
        if isinstance(patch.get("rep_range"), dict):
            normalized_patch["rep_range"] = patch.get("rep_range")
        elif isinstance(patch.get("reps"), dict):
            normalized_patch["rep_range"] = patch.get("reps")
        if patch.get("target_rpe") is not None:
            normalized_patch["target_rpe"] = patch.get("target_rpe")
        elif isinstance(patch.get("rpe_list"), list):
            normalized_patch["rpe_list"] = list(patch.get("rpe_list") or [])
            normalized_patch["target_rpe"] = patch.get("rpe_list")[0] if patch.get("rpe_list") else None
        elif isinstance(patch.get("rpe"), list):
            normalized_patch["rpe_list"] = list(patch.get("rpe") or [])
            normalized_patch["target_rpe"] = patch.get("rpe")[0] if patch.get("rpe") else None
        if patch.get("notes") is not None or patch.get("note") is not None:
            normalized_patch["notes"] = patch.get("notes") if patch.get("notes") is not None else patch.get("note")
        transformed = {"op": "update_exercise_target", "match": match, "patch": normalized_patch}
        verification = {
            **identity,
            "expected_note": normalized_patch.get("notes"),
            "expected_rep_range": normalized_patch.get("rep_range"),
            "expected_target_rpe": normalized_patch.get("target_rpe"),
            "expected_sets": normalized_patch.get("target_sets"),
        }
        return transformed, verification, False
    if op in {"change_variation", "update_exercise_variation"}:
        if not match:
            return None, None, False
        variation = raw_op.get("new_variation")
        if variation in (None, ""):
            variation = raw_op.get("variation")
        return {"op": "update_exercise_variation", "match": match, "variation": variation}, None, False
    if op == "replace_exercise":
        if not match:
            return None, None, False
        replacement = raw_op.get("replacement") if isinstance(raw_op.get("replacement"), dict) else raw_op.get("new_exercise") if isinstance(raw_op.get("new_exercise"), dict) else {}
        return {"op": "replace_exercise", "match": match, "replacement": replacement}, None, False
    return raw_op if op else None, None, False


def _verify_training_plan_targets_in_detail(detail: dict[str, Any], targets: list[dict[str, Any]]) -> list[dict[str, Any]]:
    failures: list[dict[str, Any]] = []
    for target in targets:
        match, identity = _resolve_training_plan_exercise_match(detail, {"match": target})
        if not match or not identity:
            failures.append({"op": target.get("op"), "reason": "exercise_not_found_in_readback", "target": target})
            continue
        exercise = (((detail.get("days") or [])[match["day_index"]].get("workouts") or [])[match["workout_index"]].get("exercises") or [])[match["exercise_index"]]
        if target.get("expected_note") is not None and (str(exercise.get("notes") or "").strip() or None) != target.get("expected_note"):
            failures.append({"op": target.get("op"), "reason": "note_readback_mismatch", "target": target, "actual": exercise.get("notes")})
        if target.get("expected_rep_range") is not None and exercise.get("rep_range") != target.get("expected_rep_range"):
            failures.append({"op": target.get("op"), "reason": "rep_range_readback_mismatch", "target": target, "actual": exercise.get("rep_range")})
        if target.get("expected_target_rpe") is not None and exercise.get("target_rpe") != target.get("expected_target_rpe"):
            failures.append({"op": target.get("op"), "reason": "rpe_readback_mismatch", "target": target, "actual": exercise.get("target_rpe")})
        if target.get("expected_sets") is not None and len(exercise.get("sets") or []) != int(target.get("expected_sets")):
            failures.append({"op": target.get("op"), "reason": "sets_readback_mismatch", "target": target, "actual": len(exercise.get("sets") or [])})
    return failures


def _weekday_index(label: Any) -> int | None:
    normalized = _normalize_weekday_label(label)
    if normalized in _WEEKDAY_LABELS:
        return _WEEKDAY_LABELS.index(normalized)
    return None


def _exercise_identity_matches(item: dict[str, Any], target: dict[str, Any]) -> bool:
    name = item.get("name") or item.get("exercise_name")
    if _norm_compact(name) != _norm_compact(target.get("exercise")):
        return False
    variation = target.get("variation")
    if variation not in (None, "") and _norm_compact(item.get("variation") or item.get("device")) != _norm_compact(variation):
        return False
    return True


def _patch_note_in_exercise_dict(exercise: dict[str, Any], expected_note: str | None) -> bool:
    changed = False
    if (str(exercise.get("note") or "").strip() or None) != expected_note:
        exercise["note"] = expected_note
        changed = True
    if "notes" in exercise and (str(exercise.get("notes") or "").strip() or None) != expected_note:
        exercise["notes"] = expected_note
        changed = True
    return changed


def _day_entries(plan_json: dict[str, Any]) -> list[tuple[str, int, list[dict[str, Any]]]]:
    entries: list[tuple[str, int, list[dict[str, Any]]]] = []
    base_week = plan_json.get("base_week")
    if isinstance(base_week, dict):
        for index, day in enumerate(_WEEKDAY_LABELS):
            events = base_week.get(day)
            if isinstance(events, list):
                entries.append((day, index, events))
        for day, events in base_week.items():
            if day in _WEEKDAY_LABELS or not isinstance(events, list):
                continue
            entries.append((str(day), len(entries), events))
    days = plan_json.get("days")
    if isinstance(days, list):
        for index, item in enumerate(days):
            if not isinstance(item, dict):
                continue
            day = _normalize_weekday_label(item.get("day") or item.get("label") or item.get("title") or f"day_{index}")
            events = item.get("events") if isinstance(item.get("events"), list) else item.get("items") if isinstance(item.get("items"), list) else []
            entries.append((day, index, events))
    elif isinstance(days, dict):
        for index, (day, value) in enumerate(days.items()):
            if isinstance(value, dict):
                events = value.get("events") if isinstance(value.get("events"), list) else value.get("items") if isinstance(value.get("items"), list) else []
            elif isinstance(value, list):
                events = value
            else:
                events = []
            entries.append((str(day), index, events))
    return entries


def _apply_note_target_to_plan_json(plan_json: dict[str, Any], target: dict[str, Any]) -> dict[str, Any]:
    changed_paths: list[str] = []
    requested_day = target.get("day")
    expected_note = target.get("expected_note")
    day_index = _weekday_index(requested_day)
    target_workout_index = _int_or_none(target.get("workout_index"))
    target_exercise_index = _int_or_none(target.get("exercise_index"))

    def patch_event(event: dict[str, Any], prefix: str, *, restrict_exercise_index: int | None = None) -> None:
        items = event.get("items")
        if isinstance(items, list):
            for item_index, item in enumerate(items):
                if not isinstance(item, dict) or not _exercise_identity_matches(item, target):
                    continue
                if restrict_exercise_index is not None and item_index != restrict_exercise_index:
                    continue
                if _patch_note_in_exercise_dict(item, expected_note):
                    changed_paths.append(f"{prefix}.items[{item_index}]")
        exercises = event.get("exercises")
        if isinstance(exercises, list):
            for exercise_index, exercise in enumerate(exercises):
                if not isinstance(exercise, dict) or not _exercise_identity_matches(exercise, target):
                    continue
                if restrict_exercise_index is not None and exercise_index != restrict_exercise_index:
                    continue
                if _patch_note_in_exercise_dict(exercise, expected_note):
                    changed_paths.append(f"{prefix}.exercises[{exercise_index}]")

    for day_label, entry_index, events in _day_entries(plan_json):
        if day_index is not None and entry_index != day_index and _norm_compact(day_label) != _norm_compact(requested_day):
            continue
        for event_index, event in enumerate(events):
            if not isinstance(event, dict):
                continue
            if target_workout_index is not None and event_index != target_workout_index:
                continue
            patch_event(event, f"days[{entry_index}].events[{event_index}]", restrict_exercise_index=target_exercise_index)

    sequence = plan_json.get("sequence")
    if isinstance(sequence, list):
        sequence_change_start = len(changed_paths)
        if day_index is not None and day_index < len(sequence):
            event = sequence[day_index]
            if isinstance(event, dict):
                patch_event(event, f"sequence[{day_index}]", restrict_exercise_index=target_exercise_index)
        # Compact rolling plans do not necessarily keep empty weekdays in the
        # sequence, so weekday index and sequence index can differ.
        if len(changed_paths) == sequence_change_start:
            for event_index, event in enumerate(sequence):
                if not isinstance(event, dict):
                    continue
                patch_event(event, f"sequence[{event_index}]", restrict_exercise_index=target_exercise_index)
    return {"changed_paths": changed_paths}


def _verify_note_targets_in_plan_json(plan_json: dict[str, Any], targets: list[dict[str, Any]]) -> list[dict[str, Any]]:
    failures: list[dict[str, Any]] = []

    def collect_hits(node: Any, path: str, target: dict[str, Any], hits: list[dict[str, Any]]) -> None:
        if isinstance(node, dict):
            if _exercise_identity_matches(node, target):
                note_value = str(node.get("note") or node.get("notes") or "").strip() or None
                hits.append({"path": path, "note": note_value})
            for key, value in node.items():
                next_path = f"{path}.{key}" if path else str(key)
                collect_hits(value, next_path, target, hits)
        elif isinstance(node, list):
            for index, value in enumerate(node):
                collect_hits(value, f"{path}[{index}]", target, hits)

    for target in targets:
        hits: list[dict[str, Any]] = []
        collect_hits(plan_json, "", target, hits)
        day_index = _weekday_index(target.get("day"))
        relevant_hits = []
        for hit in hits:
            hit_path = str(hit.get("path") or "")
            if hit_path.startswith("base_week."):
                base_week_day = hit_path[len("base_week.") :].split("[", 1)[0].split(".", 1)[0]
                if _normalize_weekday_label(base_week_day) == _normalize_weekday_label(target.get("day")):
                    relevant_hits.append(hit)
            elif hit_path.startswith("days[") and day_index is not None and hit_path.startswith(f"days[{day_index}]"):
                relevant_hits.append(hit)
            elif hit_path.startswith("sequence[") and day_index is not None and hit_path.startswith(f"sequence[{day_index}]"):
                relevant_hits.append(hit)
        stale_paths = [hit for hit in relevant_hits if hit.get("note") != target.get("expected_note")]
        if stale_paths:
            failures.append(
                {
                    "op": "update_exercise_note",
                    "day": target.get("day"),
                    "exercise": target.get("exercise"),
                    "variation": target.get("variation"),
                    "expected_note": target.get("expected_note"),
                    "previous_note": target.get("previous_note"),
                    "stale_paths": stale_paths,
                }
            )
    return failures


def _verify_note_targets_in_plan_core(plan: dict[str, Any], targets: list[dict[str, Any]]) -> list[dict[str, Any]]:
    failures: list[dict[str, Any]] = []
    core = _plan_core(plan)
    for target in targets:
        requested_day = target.get("day")
        expected_note = target.get("expected_note")
        matched_day_key = next((key for key in (core.get("days") or {}) if _norm_compact(key) == _norm_compact(requested_day)), None)
        day_index = _weekday_index(requested_day)
        day_info = ((core.get("days") or {}).get(str(matched_day_key)) or {})
        day_hits = []
        for event in day_info.get("events") or []:
            for item in event.get("items") or []:
                if isinstance(item, dict) and _exercise_identity_matches(item, target):
                    day_hits.append({"scope": "day", "event_title": event.get("title"), "note": str(item.get("note") or "").strip() or None})
        rotation_hits = []
        rotation_info = ((core.get("days") or {}).get("rotation")) or {}
        rotation_events = rotation_info.get("events") or []
        scoped_rotation_events = []
        if day_index is not None and day_index < len(rotation_events):
            scoped_rotation_events = [rotation_events[day_index]]
        else:
            scoped_rotation_events = rotation_events
        for event in scoped_rotation_events:
            for item in event.get("items") or []:
                if isinstance(item, dict) and _exercise_identity_matches(item, target):
                    rotation_hits.append({"scope": "rotation", "event_title": event.get("title"), "note": str(item.get("note") or "").strip() or None})
        stale_hits = [hit for hit in day_hits + rotation_hits if hit.get("note") != expected_note]
        if stale_hits:
            failures.append(
                {
                    "op": "update_exercise_note",
                    "day": requested_day,
                    "exercise": target.get("exercise"),
                    "variation": target.get("variation"),
                    "expected_note": expected_note,
                    "actual_hits": stale_hits,
                }
            )
    return failures


def _patch_training_plan_notes_live(
    plan_id: int,
    operations: list[dict[str, Any]],
    transformed_operations: list[dict[str, Any]],
    verification_targets: list[dict[str, Any]],
    preview: dict[str, Any],
) -> dict[str, Any]:
    conn = connections.get_plans_db()
    conn.row_factory = sqlite3.Row
    try:
        row = _load_gym_plan_row(conn, plan_id) if _table_exists(conn, "gym_plans") else None
        if not row:
            raise ValueError("plan_not_found")
        plan_json = _json_loads(row["plan_json"], {}) or {}
        verification_targets = [
            {
                **target,
                "workout_index": transformed.get("match", {}).get("workout_index"),
                "exercise_index": transformed.get("match", {}).get("exercise_index"),
            }
            for target, transformed in zip(verification_targets, transformed_operations)
        ]
        changed_paths: list[str] = []
        conn.execute("BEGIN")
        for target in verification_targets:
            patched = _apply_note_target_to_plan_json(plan_json, target)
            changed_paths.extend(patched["changed_paths"])
        now = datetime.utcnow().isoformat()
        conn.execute("UPDATE gym_plans SET plan_json=?, updated_at=? WHERE id=?", (json.dumps(plan_json, ensure_ascii=False), now, plan_id))
        reloaded_row = conn.execute("SELECT id, title AS name, focus, plan_json, is_active, is_archived, updated_at, created_at, rules_json, blocks_json FROM gym_plans WHERE id=? LIMIT 1", (plan_id,)).fetchone()
        reloaded_plan = dict(reloaded_row) if reloaded_row else None
        if reloaded_plan is not None:
            reloaded_plan["source"] = "gym_plans"
            reloaded_plan["plan"] = _json_loads(reloaded_plan.get("plan_json"), {}) or {}
            reloaded_plan["rules"] = _json_loads(reloaded_plan.get("rules_json"), {}) or {}
            reloaded_plan["blocks"] = _json_loads(reloaded_plan.get("blocks_json"), {}) or {}
        raw_failures = _verify_note_targets_in_plan_json(reloaded_plan.get("plan") if reloaded_plan else {}, verification_targets)
        read_failures = _verify_note_targets_in_plan_core(reloaded_plan or {}, verification_targets)
        if raw_failures or read_failures:
            conn.rollback()
            return {
                "ok": False,
                "error": {
                    "code": "patch_verification_failed",
                    "message": "Patch verification found stale note mirrors in persistent plan_json or full readback.",
                    "failed_operations": raw_failures + read_failures,
                    "stale_paths": [hit for failure in raw_failures for hit in failure.get("stale_paths") or []],
                },
                **preview,
                "operations_applied": 0,
                "changed_paths": changed_paths,
                "warnings": [],
            }
        conn.commit()
        return {
            **preview,
            "changed": True,
            "operations_applied": len(operations),
            "warnings": [],
            "changed_paths": changed_paths,
            "updated_plan_after": _compact_plan_core(_plan_core(reloaded_plan)),
            "_affected_resources": ["training_plan", "plans.gym_plans", "plans.actions_v2_command_log"],
        }
    finally:
        conn.close()


def _patch_training_plan_legacy_only(plan_id: int, operations: list[dict[str, Any]], *, dry_run: bool = False) -> dict[str, Any]:
    allow_partial = False
    conn = connections.get_plans_db()
    conn.row_factory = sqlite3.Row
    try:
        row = _load_gym_plan_row(conn, plan_id) if _table_exists(conn, "gym_plans") else None
        if not row:
            raise ValueError("plan_not_found")
        plan_json = _json_loads(row["plan_json"], {}) or {}
        base_week = plan_json.get("base_week") if isinstance(plan_json.get("base_week"), dict) else {}
        sequence = plan_json.get("sequence") if isinstance(plan_json.get("sequence"), list) else []
        meta = plan_json.get("meta") if isinstance(plan_json.get("meta"), dict) else {}
        applied = 0
        failed: list[dict[str, Any]] = []
        warnings: list[dict[str, Any]] = []
        changed = False
        matched_count = 0
        unmatched_count = 0
        for raw_op in operations:
            if not isinstance(raw_op, dict):
                failed.append({"op": None, "reason": "invalid_operation"})
                unmatched_count += 1
                if not allow_partial:
                    break
                continue
            op = str(raw_op.get("op") or "").strip()
            day = _normalize_weekday_label(raw_op.get("day")) if raw_op.get("day") not in (None, "") else None
            try:
                if op == "rename_plan":
                    plan_json["name"] = str(raw_op.get("title") or raw_op.get("name") or plan_json.get("name") or "").strip() or plan_json.get("name")
                    changed = True
                elif op == "set_focus":
                    changed = True
                elif op == "replace_day_events":
                    if not day:
                        raise ValueError("day_required")
                    events = raw_op.get("events")
                    if not isinstance(events, list):
                        raise ValueError("events_required")
                    normalized = _normalize_create_training_plan_payload({"name": plan_json.get("name") or row["title"], "days": [{"day": day, "events": events}]})
                    base_week[day] = normalized["base_week"][day]
                    changed = True
                elif op == "add_event_to_day":
                    if not day:
                        raise ValueError("day_required")
                    event = raw_op.get("event")
                    if not isinstance(event, dict):
                        raise ValueError("event_required")
                    normalized = _normalize_create_training_plan_payload({"name": plan_json.get("name") or row["title"], "days": [{"day": day, "events": [event]}]})
                    base_week.setdefault(day, []).append(normalized["base_week"][day][0])
                    changed = True
                elif op == "remove_event_from_day":
                    if not day:
                        raise ValueError("day_required")
                    title = str(raw_op.get("title") or "").strip().lower()
                    before = len(base_week.get(day) or [])
                    base_week[day] = [event for event in (base_week.get(day) or []) if str(event.get("title") or "").strip().lower() != title]
                    if len(base_week[day]) == before:
                        raise ValueError("event_not_found")
                    changed = True
                elif op == "replace_exercise_target":
                    if not day:
                        raise ValueError("day_required")
                    exercise = str(raw_op.get("exercise") or "").strip().lower()
                    patch = raw_op.get("patch") if isinstance(raw_op.get("patch"), dict) else {}
                    reps_patch = patch.get("reps")
                    if reps_patch is None and isinstance(patch.get("rep_range"), dict):
                        reps_patch = patch.get("rep_range")

                    def apply_target_patch(events: list[dict[str, Any]]) -> bool:
                        patched = False
                        for event in events:
                            if not isinstance(event, dict):
                                continue
                            for item in event.get("items") or []:
                                if not isinstance(item, dict):
                                    continue
                                display_name = _exercise_display(item)
                                if str(display_name or item.get("name") or "").strip().lower() != exercise:
                                    continue
                                if "sets" in patch:
                                    item["sets"] = patch["sets"]
                                if isinstance(reps_patch, dict):
                                    item["reps"] = reps_patch
                                if "rpe_list" in patch:
                                    item["rpe_list"] = patch["rpe_list"]
                                if "note" in patch or "notes" in patch:
                                    next_note = patch.get("note") if "note" in patch else patch.get("notes")
                                    item["note"] = next_note
                                    if "notes" in item:
                                        item["notes"] = next_note
                                patched = True
                                break
                        return patched

                    matched = apply_target_patch(base_week.get(day) or [])
                    day_index = _weekday_index(day)
                    if day_index is not None and day_index < len(sequence):
                        apply_target_patch([sequence[day_index]])
                    elif sequence:
                        apply_target_patch(sequence)
                    if not matched:
                        raise ValueError("exercise_not_found")
                    changed = True
                elif op == "replace_cardio":
                    if not day:
                        raise ValueError("day_required")
                    title = str(raw_op.get("title") or "").strip()
                    patch = raw_op.get("patch") if isinstance(raw_op.get("patch"), dict) else {}
                    idx, event, previews, reason = _select_cardio_event_for_patch(base_week.get(day) or [], title)
                    if event is None or idx is None:
                        failed.append({"op": op, "reason": reason or "cardio_not_found", "requested_day": day, "requested_title": title or None, "available_cardio_events": previews})
                        if not allow_partial:
                            break
                        continue
                    base_week[day][idx] = _normalize_patched_cardio_event(event, patch, title)
                    changed = True
                elif op == "update_week_rule":
                    week = _int_or_none(raw_op.get("week"))
                    patch = raw_op.get("patch") if isinstance(raw_op.get("patch"), dict) else {}
                    weeks = plan_json.get("weeks") if isinstance(plan_json.get("weeks"), list) else []
                    target_week = next((item for item in weeks if isinstance(item, dict) and _int_or_none(item.get("week")) == week), None)
                    if not target_week:
                        raise ValueError("week_not_found")
                    target_week.update(patch)
                    changed = True
                elif op == "set_plan_mode":
                    mode = str(raw_op.get("mode") or "").strip().lower()
                    if mode not in {"fixed_week", "rolling_sequence"}:
                        raise ValueError("invalid_mode")
                    meta["mode"] = mode
                    changed = True
                elif op == "set_periodization_enabled":
                    meta["periodization_enabled"] = _bool_value(raw_op.get("enabled"), default=False)
                    changed = True
                elif op == "replace_sequence":
                    events = raw_op.get("events")
                    if not isinstance(events, list):
                        raise ValueError("events_required")
                    normalized = _normalize_create_training_plan_payload({"name": plan_json.get("name") or row["title"], "mode": "rolling_sequence", "sequence": events})
                    sequence = normalized["sequence"]
                    meta["mode"] = "rolling_sequence"
                    changed = True
                elif op == "move_sequence_event":
                    from_index = _int_or_none(raw_op.get("from_index"))
                    to_index = _int_or_none(raw_op.get("to_index"))
                    if from_index is None or to_index is None or from_index < 0 or to_index < 0 or from_index >= len(sequence) or to_index >= len(sequence):
                        raise ValueError("invalid_sequence_index")
                    event = sequence.pop(from_index)
                    sequence.insert(to_index, event)
                    meta["mode"] = "rolling_sequence"
                    changed = True
                else:
                    raise ValueError("unknown_operation")
                applied += 1
                matched_count += 1
            except ValueError as exc:
                failed.append({"op": op, "reason": str(exc)})
                unmatched_count += 1
                if not allow_partial:
                    break
        plan_json["base_week"] = base_week
        plan_json["sequence"] = sequence
        plan_json["meta"] = meta
        preview = {
            "plan_id": plan_id,
            "operations_count": len(operations),
            "matched_count": matched_count,
            "unmatched_count": unmatched_count,
            "changed_notes_count": 0,
        }
        if failed and not allow_partial:
            return {**preview, "changed": False, "operations_applied": applied, "operations_failed": failed, "warnings": warnings}
        if dry_run:
            return {**preview, "changed": changed, "operations_applied": applied, "operations_failed": failed, "warnings": warnings, "updated_plan_after": _training_plan_summary_from_plan_json(plan_json)}
        now = datetime.utcnow().isoformat()
        conn.execute("UPDATE gym_plans SET plan_json=?, updated_at=? WHERE id=?", (json.dumps(plan_json, ensure_ascii=False), now, plan_id))
        conn.commit()
        updated = _load_gym_plan_row(conn, plan_id)
        return {**preview, "changed": changed, "operations_applied": applied, "operations_failed": failed, "warnings": warnings, "updated_plan_after": _compact_training_plan_row(updated or row), "_affected_resources": ["training_plan", "plans.gym_plans", "plans.actions_v2_command_log"]}
    finally:
        conn.close()


def _sync_training_plan_sequence_notes(plan_id: int, verification_targets: list[dict[str, Any]]) -> None:
    conn = connections.get_plans_db()
    conn.row_factory = sqlite3.Row
    try:
        row = _load_gym_plan_row(conn, plan_id) if _table_exists(conn, "gym_plans") else None
        if not row:
            raise ValueError("plan_not_found")
        plan_json = _json_loads(row["plan_json"], {}) or {}
        sequence = plan_json.get("sequence")
        if not isinstance(sequence, list):
            return
        changed = False
        for event in sequence:
            if not isinstance(event, dict):
                continue
            items = event.get("items")
            if not isinstance(items, list):
                continue
            for item in items:
                if not isinstance(item, dict):
                    continue
                for target in verification_targets:
                    if _norm_compact(item.get("name")) != _norm_compact(target.get("exercise")):
                        continue
                    variation = target.get("variation")
                    if variation not in (None, "") and _norm_compact(item.get("variation")) != _norm_compact(variation):
                        continue
                    next_note = target.get("expected_note")
                    if (str(item.get("note") or "").strip() or None) != next_note:
                        item["note"] = next_note
                        if "notes" in item:
                            item["notes"] = next_note
                        changed = True
        if not changed:
            return
        conn.execute(
            "UPDATE gym_plans SET plan_json=?, updated_at=? WHERE id=?",
            (json.dumps(plan_json, ensure_ascii=False), datetime.utcnow().isoformat(), plan_id),
        )
        conn.commit()
    finally:
        conn.close()


def _training_plan_day_payload(core: dict[str, Any], requested_day: str) -> dict[str, Any]:
    days = core.get("days") if isinstance(core.get("days"), dict) else {}
    matched_day = next((key for key in days if str(key).strip().lower() == str(requested_day).strip().lower()), None)
    if not matched_day:
        raise ValueError("plan_day_not_found")
    info = days.get(matched_day) or {}
    return {
        "available": bool(core.get("available")),
        "id": core.get("id"),
        "plan_id": core.get("plan_id"),
        "title": core.get("title"),
        "name": core.get("name"),
        "is_active": bool(core.get("is_active")),
        "is_archived": bool(core.get("is_archived")),
        "active_version": core.get("active_version"),
        "updated_at": core.get("updated_at"),
        "source": core.get("source"),
        "detail": "day",
        "requested_day": requested_day,
        "matched_day": matched_day,
        "days": {
            matched_day: {
                "label": info.get("label"),
                "available": bool(info.get("available")),
                "events": [event for event in (info.get("events") or []) if isinstance(event, dict)],
                "exercises": [_compact_plan_exercise_target(exercise) for exercise in (info.get("exercises") or []) if isinstance(exercise, dict)],
            }
        },
    }


def _training_plan_exercise_payload(core: dict[str, Any], requested_day: str, requested_exercise: str) -> dict[str, Any]:
    day_payload = _training_plan_day_payload(core, requested_day)
    matched_day = str(day_payload.get("matched_day") or "")
    exercises = ((((day_payload.get("days") or {}).get(matched_day) or {}).get("exercises")) or [])
    target_norm = _norm_compact(requested_exercise)
    matched = next(
        (
            exercise
            for exercise in exercises
            if target_norm
            and target_norm in {
                _norm_compact(exercise.get("display_name")),
                _norm_compact(exercise.get("name")),
            }
        ),
        None,
    )
    if not matched:
        events = ((((day_payload.get("days") or {}).get(matched_day) or {}).get("events")) or [])
        for event in events:
            for item in (event.get("exercises") or []):
                if not isinstance(item, dict):
                    continue
                if target_norm and target_norm in {_norm_compact(item.get("display_name")), _norm_compact(item.get("name"))}:
                    matched = item
                    break
            if matched:
                break
    if not matched:
        raise ValueError("plan_exercise_not_found")
    return {
        "available": bool(core.get("available")),
        "id": core.get("id"),
        "plan_id": core.get("plan_id"),
        "title": core.get("title"),
        "name": core.get("name"),
        "is_active": bool(core.get("is_active")),
        "is_archived": bool(core.get("is_archived")),
        "active_version": core.get("active_version"),
        "updated_at": core.get("updated_at"),
        "source": core.get("source"),
        "detail": "exercise",
        "requested_day": requested_day,
        "matched_day": matched_day,
        "requested_exercise": requested_exercise,
        "matched_exercise": matched.get("display_name") or matched.get("name"),
        "target": _compact_plan_exercise_target(matched),
    }


def _norm_day_key(value: Any) -> str:
    return _norm_compact(str(value or ""))


def _find_plan_day(plan_json: dict[str, Any], requested_day: str) -> tuple[str | None, Any]:
    base_week = plan_json.get("base_week")
    if isinstance(base_week, dict):
        for day, events in base_week.items():
            if _norm_day_key(day) == _norm_day_key(requested_day):
                return str(day), events
    days = plan_json.get("days")
    if isinstance(days, dict):
        for day, value in days.items():
            if _norm_day_key(day) == _norm_day_key(requested_day):
                return str(day), value
    if isinstance(days, list):
        for item in days:
            if isinstance(item, dict) and _norm_day_key(item.get("day")) == _norm_day_key(requested_day):
                return str(item.get("day")), item
    sequence = plan_json.get("sequence")
    if isinstance(sequence, list):
        if _norm_day_key(requested_day) in {_norm_day_key("rotation"), _norm_day_key("sequence")}:
            return "rotation", sequence
        matching_indexes = [
            index
            for index, event in enumerate(sequence)
            if isinstance(event, dict)
            and any(
                _norm_day_key(value) == _norm_day_key(requested_day)
                for value in (event.get("id"), event.get("title"), event.get("name"), event.get("session_key"))
                if value not in (None, "")
            )
        ]
        if len(matching_indexes) == 1:
            index = matching_indexes[0]
            return f"rotation:{index}", [sequence[index]]
    return None, None


def _plan_day_events_ref(plan_json: dict[str, Any], matched_day: str) -> list[dict[str, Any]] | None:
    if matched_day == "rotation" and isinstance(plan_json.get("sequence"), list):
        return plan_json["sequence"]
    if matched_day.startswith("rotation:") and isinstance(plan_json.get("sequence"), list):
        index = _int_or_none(matched_day.split(":", 1)[1])
        if index is not None and 0 <= index < len(plan_json["sequence"]):
            event = plan_json["sequence"][index]
            return [event] if isinstance(event, dict) else None
    if isinstance(plan_json.get("base_week"), dict):
        events = plan_json["base_week"].get(matched_day)
        return events if isinstance(events, list) else None
    days = plan_json.get("days")
    if isinstance(days, dict):
        value = days.get(matched_day)
        if isinstance(value, dict):
            events = value.get("events") or value.get("items")
            return events if isinstance(events, list) else None
        return value if isinstance(value, list) else None
    if isinstance(days, list):
        for item in days:
            if isinstance(item, dict) and str(item.get("day")) == matched_day:
                events = item.get("events") or item.get("items")
                return events if isinstance(events, list) else None
    return None


def _find_plan_exercise(events: list[dict[str, Any]], requested_exercise: str) -> tuple[dict[str, Any] | None, str | None]:
    matches: list[tuple[dict[str, Any], str]] = []
    for event in events:
        if not isinstance(event, dict):
            continue
        items = event.get("items") if isinstance(event.get("items"), list) else event.get("strength_exercises") if isinstance(event.get("strength_exercises"), list) else []
        for item in items:
            if not isinstance(item, dict):
                continue
            name = str(item.get("name") or item.get("exercise_name") or "").strip()
            variation = str(item.get("variation") or item.get("device") or "").strip()
            candidates = [name, f"{name} ({variation})" if variation else ""]
            if any(_norm_compact(candidate) == _norm_compact(requested_exercise) for candidate in candidates if candidate):
                matches.append((item, name))
    if len(matches) > 1:
        raise ValueError("plan_exercise_ambiguous_use_session_label_or_key")
    if matches:
        return matches[0]
    return None, None


def _exercise_target_snapshot(item: dict[str, Any] | None) -> dict[str, Any] | None:
    if not item:
        return None
    return _serialize_plan_exercise(dict(item))


def _plan_exercise_matches_snapshot(item: dict[str, Any], snapshot: dict[str, Any] | None, selector: str) -> bool:
    if not isinstance(item, dict):
        return False
    name = str(item.get("name") or item.get("exercise_name") or "").strip()
    variation = str(item.get("variation") or item.get("device") or "").strip()
    candidates = {name, f"{name} ({variation})" if name and variation else ""}
    if selector and any(_norm_compact(candidate) == _norm_compact(selector) for candidate in candidates if candidate):
        return True
    if not snapshot:
        return False
    snap_name = str(snapshot.get("name") or "").strip()
    snap_variation = str(snapshot.get("variation") or snapshot.get("device") or "").strip()
    snap_display = str(snapshot.get("display_name") or "").strip()
    snapshot_candidates = {snap_name, snap_display, f"{snap_name} ({snap_variation})" if snap_name and snap_variation else ""}
    return any(_norm_compact(candidate) in {_norm_compact(item_candidate) for item_candidate in candidates if item_candidate} for candidate in snapshot_candidates if candidate)


def _sync_mutated_exercise_across_plan_structures(
    plan_json: dict[str, Any],
    matched_day: str,
    exercise_selector: str,
    old_target: dict[str, Any] | None,
    updated_item: dict[str, Any],
) -> None:
    replacement = copy.deepcopy(updated_item)

    def sync_events(events: Any) -> None:
        if not isinstance(events, list):
            return
        for event in events:
            if not isinstance(event, dict):
                continue
            items = event.get("items") if isinstance(event.get("items"), list) else event.get("strength_exercises") if isinstance(event.get("strength_exercises"), list) else []
            for idx, item in enumerate(items):
                if not isinstance(item, dict):
                    continue
                if _plan_exercise_matches_snapshot(item, old_target, exercise_selector):
                    items[idx] = copy.deepcopy(replacement)
                    return

    days = plan_json.get("days")
    if isinstance(days, dict):
        day_value = days.get(matched_day)
        if isinstance(day_value, dict):
            sync_events(day_value.get("events") or day_value.get("items"))
        elif isinstance(day_value, list):
            sync_events(day_value)
    elif isinstance(days, list):
        for day_item in days:
            if not isinstance(day_item, dict):
                continue
            if _norm_day_key(day_item.get("day")) != _norm_day_key(matched_day):
                continue
            sync_events(day_item.get("events") or day_item.get("items"))
            break

    sequence = plan_json.get("sequence")
    day_index = _weekday_index(matched_day)
    if isinstance(sequence, list) and day_index is not None and 0 <= day_index < len(sequence):
        event = sequence[day_index]
        if isinstance(event, dict):
            sync_events([event])
    if isinstance(sequence, list):
        # Compact rolling sequences are not weekday-indexed. Scan the sequence
        # as a fallback so its mirrored exercise cannot drift from base_week.
        sync_events(sequence)


def _normalize_reps_patch(value: Any) -> dict[str, Any] | None:
    if isinstance(value, dict):
        out = {}
        if _int_or_none(value.get("min")) is not None:
            out["min"] = int(value["min"])
        if _int_or_none(value.get("max")) is not None:
            out["max"] = int(value["max"])
        return out or None
    if isinstance(value, str):
        match = re.fullmatch(r"\s*(\d+)\s*[-–]\s*(\d+)\s*", value)
        if match:
            return {"min": int(match.group(1)), "max": int(match.group(2))}
    return None


def _update_active_plan_exercise(day: str, exercise_selector: str, patch: dict[str, Any], *, command: str, dry_run: bool = False) -> dict[str, Any]:
    conn = connections.get_plans_db()
    try:
        if not _table_exists(conn, "gym_plans"):
            raise ValueError("gym_plans table not found")
        row = conn.execute(
            """
            SELECT id, title, plan_json, updated_at
            FROM gym_plans
            WHERE is_active=1 AND COALESCE(is_archived, 0)=0
            ORDER BY updated_at DESC, id DESC
            LIMIT 1
            """
        ).fetchone()
        if not row:
            raise ValueError("no_active_gym_plan")
        plan_id = int(row["id"])
        plan_json = _json_loads(row["plan_json"], {}) or {}
        matched_day, _day_ref = _find_plan_day(plan_json, day)
        if not matched_day:
            raise ValueError("plan_day_not_found")
        events = _plan_day_events_ref(plan_json, matched_day)
        if not isinstance(events, list):
            raise ValueError("plan_day_not_found")
        exercise_item, matched_exercise = _find_plan_exercise(events, exercise_selector)
        if not exercise_item:
            raise ValueError("plan_exercise_not_found")
        old_target = _exercise_target_snapshot(exercise_item)
        if command == "replace_exercise":
            new_exercise = patch.get("new_exercise") if isinstance(patch.get("new_exercise"), dict) else {}
            if not str(new_exercise.get("name") or "").strip():
                raise ValueError("new_exercise.name is required")
            replacement = {"kind": "exercise", **new_exercise}
            exercise_item.clear()
            exercise_item.update(replacement)
        else:
            if patch.get("sets") is not None:
                exercise_item["sets"] = int(patch["sets"])
            reps_payload = patch.get("reps")
            if reps_payload is None and patch.get("rep_range") is not None:
                reps_payload = patch.get("rep_range")
            reps_patch = _normalize_reps_patch(reps_payload)
            if reps_patch is not None:
                exercise_item["reps"] = reps_patch
            rpe_patch = patch.get("rpe_list") if isinstance(patch.get("rpe_list"), list) else patch.get("rpe") if isinstance(patch.get("rpe"), list) else None
            if rpe_patch is None and _float_or_none(patch.get("rpe")) is not None:
                set_count = _int_or_none(patch.get("sets")) or _int_or_none(exercise_item.get("sets")) or 1
                rpe_patch = [float(patch["rpe"])] * max(1, set_count)
            if rpe_patch is not None:
                exercise_item["rpe_list"] = rpe_patch
            if "note" in patch:
                exercise_item["note"] = str(patch.get("note") or "").strip()
            if command == "change_variation":
                variation = patch.get("new_variation")
                if variation in (None, ""):
                    variation = patch.get("variation")
                if variation in (None, ""):
                    raise ValueError("variation or new_variation is required")
                exercise_item["variation"] = str(variation)
            else:
                variation = patch.get("variation")
                if variation not in (None, ""):
                    exercise_item["variation"] = str(variation)
        new_target = _exercise_target_snapshot(exercise_item)
        changed = old_target != new_target
        if not changed:
            return {
                "plan_id": plan_id,
                "requested_day": day,
                "matched_day": matched_day,
                "requested_exercise": exercise_selector,
                "matched_exercise": matched_exercise,
                "old_target": old_target,
                "new_target": new_target,
                "updated_at": row["updated_at"],
                "changed": False,
            }
        _sync_mutated_exercise_across_plan_structures(plan_json, matched_day, exercise_selector, old_target, exercise_item)
        updated_at = _utc_iso()
        if not dry_run:
            conn.execute("UPDATE gym_plans SET plan_json=?, updated_at=? WHERE id=?", (json.dumps(plan_json, ensure_ascii=False), updated_at, plan_id))
            conn.commit()
        return {
            "plan_id": plan_id,
            "requested_day": day,
            "matched_day": matched_day,
            "requested_exercise": exercise_selector,
            "matched_exercise": matched_exercise,
            "old_target": old_target,
            "new_target": new_target,
            "updated_at": row["updated_at"] if dry_run else updated_at,
            "changed": True,
            "dry_run": dry_run,
        }
    finally:
        conn.close()


def _serialize_plan_day(events: Any) -> dict[str, Any]:
    if isinstance(events, str):
        label = events.strip() or None
        return {"label": label, "events": [{"id": None, "kind": "gym", "title": label, "time": None}] if label else [], "exercises": [], "available": bool(label)}
    if isinstance(events, dict):
        events = events.get("events") or events.get("items") or []
    if not isinstance(events, list):
        events = []
    serialized_events = []
    exercises = []
    labels = []
    for index, event in enumerate(events):
        if not isinstance(event, dict):
            continue
        title = str(event.get("title") or event.get("session_name") or "").strip()
        kind = str(event.get("kind") or "gym").strip() or "gym"
        if title:
            labels.append(title)
        items = _event_exercise_items(event)
        event_payload = {"id": event.get("id") or _plan_event_stable_id(event, index=index), "kind": kind, "title": title or None, "time": event.get("time")}
        if event.get("mode"):
            event_payload["mode"] = event.get("mode")
        serialized_items = [_serialize_plan_event_item(item) for item in items if isinstance(item, dict)]
        event_exercises = [_serialize_plan_exercise(item) for item in items if isinstance(item, dict) and (item.get("kind") == "exercise" or item.get("exercise_name") or item.get("name"))]
        exercises.extend(event_exercises)
        if serialized_items:
            event_payload["items"] = serialized_items
        if event_exercises:
            event_payload["exercises"] = event_exercises
        serialized_events.append(event_payload)
    return {"label": " + ".join(labels) if labels else None, "events": serialized_events, "exercises": exercises, "available": bool(serialized_events)}


def _serialize_legacy_plan_day(day: dict[str, Any]) -> dict[str, Any]:
    title = str(day.get("session_name") or "").strip()
    exercises = [_serialize_plan_exercise(item) for item in day.get("strength_exercises") or [] if isinstance(item, dict)]
    event = {"id": None, "kind": "gym" if exercises else "run", "title": title or None, "time": None}
    if exercises:
        event["exercises"] = exercises
    return {"label": title or None, "events": [event] if title or exercises else [], "exercises": exercises, "available": bool(title or exercises)}


def _serialize_plan_exercise(item: dict[str, Any]) -> dict[str, Any]:
    name = str(item.get("name") or item.get("exercise_name") or "").strip()
    variation = str(item.get("variation") or item.get("device") or "").strip() or None
    reps = item.get("reps") if isinstance(item.get("reps"), dict) else item.get("rep_range") if isinstance(item.get("rep_range"), dict) else {"min": item.get("reps_min"), "max": item.get("reps_max")}
    sets = _int_or_none(item.get("sets"))
    raw_rpe_list = item.get("rpe_list") if isinstance(item.get("rpe_list"), list) else []
    rpe_list: list[Any] | None = None
    if sets is not None:
        normalized_rpe = list(raw_rpe_list[:sets])
        if len(normalized_rpe) < sets:
            fill_value = normalized_rpe[-1] if normalized_rpe else None
            normalized_rpe.extend([fill_value] * (sets - len(normalized_rpe)))
        rpe_list = normalized_rpe
    elif raw_rpe_list:
        rpe_list = list(raw_rpe_list)
    rep_range = {k: v for k, v in (reps or {}).items() if v is not None} if isinstance(reps, dict) else {}
    out = {
        "exercise_id": item.get("exercise_id") or item.get("id") or _plan_exercise_stable_id(item),
        "name": name,
        "display_name": f"{name} ({variation})" if variation else name,
        "sets": sets,
        "rep_range": rep_range,
    }
    if variation:
        out["variation"] = variation
        out["device"] = item.get("device") or variation
    elif item.get("device"):
        out["device"] = item.get("device")
    if rpe_list is not None:
        out["rpe_list"] = rpe_list
    if item.get("note"):
        out["note"] = item.get("note")
    if sets or rep_range or rpe_list is not None:
        out["volume"] = {
            **({"sets": sets} if sets is not None else {}),
            **({"reps": rep_range} if rep_range else {}),
            **({"rpe": rpe_list} if rpe_list is not None else {}),
        }
        out["set_targets"] = [
            {
                **({"set_number": idx + 1} if sets is not None else {}),
                **({"reps": rep_range} if rep_range else {}),
                **({"rpe": rpe_list[idx]} if rpe_list is not None and idx < len(rpe_list) else {}),
            }
            for idx in range(sets or len(rpe_list or []) or 0)
        ]
    return {key: value for key, value in out.items() if value not in (None, {}, [])}


def _plan_event_stable_id(event: dict[str, Any], *, index: int) -> str:
    title = str(event.get("title") or event.get("session_name") or "").strip()
    kind = str(event.get("kind") or "gym").strip().lower() or "gym"
    time_text = str(event.get("time") or "").strip()
    items = _event_exercise_items(event)
    item_names = [str(item.get("name") or item.get("exercise_name") or item.get("title") or "").strip() for item in items if isinstance(item, dict)]
    raw = "|".join([kind, title, time_text, str(index), ",".join(item_names)])
    return uuid.uuid5(uuid.NAMESPACE_URL, raw).hex[:10]


def _plan_exercise_stable_id(item: dict[str, Any]) -> str:
    name = str(item.get("name") or item.get("exercise_name") or "").strip()
    variation = str(item.get("variation") or item.get("device") or "").strip()
    canonical = str(item.get("canonical_id") or "").strip()
    raw = "|".join([canonical, name, variation])
    return uuid.uuid5(uuid.NAMESPACE_URL, raw).hex[:12]


def _event_exercise_items(event: dict[str, Any]) -> list[dict[str, Any]]:
    fallback_empty: list[dict[str, Any]] | None = None
    for key in ("items", "strength_exercises", "exercises"):
        value = event.get(key)
        if isinstance(value, list):
            if value:
                return value
            if fallback_empty is None:
                fallback_empty = value
    if fallback_empty is not None:
        return fallback_empty
    return []


def _serialize_plan_event_item(item: dict[str, Any]) -> dict[str, Any]:
    kind = str(item.get("kind") or "").strip().lower()
    if kind == "exercise":
        return {"kind": "exercise", **_serialize_plan_exercise(item)}
    if kind in {"cardio", "run", "ergo"} or _is_training_cardio_kind(item.get("mode")):
        out = {
            "kind": "cardio",
            "mode": _training_cardio_mode(item.get("mode") or kind),
            "name": str(item.get("name") or item.get("title") or "").strip() or None,
            "duration_min": _float_or_none(item.get("duration_min")),
            "amount_value": _float_or_none(item.get("amount_value")),
            "amount_unit": str(item.get("amount_unit") or "").strip() or None,
            "intensity": str(item.get("intensity") or "").strip() or None,
            "notes": str(item.get("notes") or item.get("note") or "").strip() or None,
            "display": str(item.get("display") or item.get("display_text") or _build_training_cardio_display(item) or "").strip() or None,
        }
        if out.get("display") and not out.get("display_text"):
            out["display_text"] = out["display"]
        return {key: value for key, value in out.items() if value not in (None, {}, [])}
    if kind == "run_detail":
        return {"kind": "run_detail", "text": str(item.get("text") or "").strip() or None}
    if kind == "note":
        return {"kind": "note", "text": str(item.get("text") or "").strip() or None}
    if kind == "ref_block":
        return {
            "kind": "ref_block",
            "display_name": str(item.get("display_name") or "").strip() or None,
            "variation": str(item.get("variation") or "").strip() or None,
            "block_name": str(item.get("block_name") or "").strip() or None,
            "block_day": str(item.get("block_day") or "").strip() or None,
        }
    return {key: value for key, value in item.items() if value not in (None, {}, [])}


def _format_sleep_window_label(start: Any, end: Any) -> str | None:
    start_text = str(start or "").strip()
    end_text = str(end or "").strip()
    if not start_text or not end_text:
        return None
    try:
        start_dt = datetime.fromisoformat(start_text.replace("Z", "+00:00"))
        end_dt = datetime.fromisoformat(end_text.replace("Z", "+00:00"))
    except Exception:
        return None
    return f"{start_dt.strftime('%H:%M')} – {end_dt.strftime('%H:%M')}"


def _polar_row_has_recovery_signal(row: dict[str, Any] | None) -> bool:
    if not row:
        return False
    keys = (
        "sleep_score",
        "sleep_start",
        "sleep_end",
        "sleep_minutes",
        "actual_sleep_minutes",
        "deep_sleep_minutes",
        "rem_sleep_minutes",
        "light_sleep_minutes",
        "awake_minutes",
        "interruption_minutes",
        "interruptions",
        "ans_status",
        "recovery_indicator",
        "recovery_indicator_sublevel",
        "ans_rate",
        "mean_recovery_rri",
        "mean_recovery_rmssd",
        "breathing_rate",
        "respiration_rate",
        "min_hr",
        "max_hr",
        "avg_hr",
        "resting_candidate_hr",
    )
    return any(row.get(key) not in (None, "") for key in keys)


def _latest_polar_recovery_rows() -> dict[str, dict[str, Any] | None]:
    conn = connections.get_polar_db()
    try:
        out: dict[str, dict[str, Any] | None] = {"sleep": None, "nightly": None, "continuous": None}
        if _table_exists(conn, "polar_sleep"):
            row = conn.execute("SELECT * FROM polar_sleep ORDER BY date DESC LIMIT 1").fetchone()
            out["sleep"] = dict(row) if row else None
        if _table_exists(conn, "polar_nightly_recharge"):
            row = conn.execute("SELECT * FROM polar_nightly_recharge ORDER BY date DESC LIMIT 1").fetchone()
            out["nightly"] = dict(row) if row else None
        if _table_exists(conn, "polar_continuous_samples"):
            row = conn.execute("SELECT * FROM polar_continuous_samples ORDER BY date DESC LIMIT 1").fetchone()
            out["continuous"] = dict(row) if row else None
        return out
    finally:
        conn.close()


def _boolish_flag(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    low = str(value or "").strip().lower()
    return low in {"1", "true", "yes", "y", "on", "sick", "alcohol", "ja"}


def _breathing_rate_from_polar_row(row: dict[str, Any] | None) -> float | None:
    if not row:
        return None
    direct = _float_or_none(row.get("breathing_rate") or row.get("respiration_rate"))
    if direct is not None:
        return direct
    raw = _json_loads(row.get("raw_json"), {})
    if isinstance(raw, dict):
        for key in ("breathingRate", "respirationRate"):
            value = _float_or_none(raw.get(key))
            if value is not None:
                return value
    return None


def _latest_hrv_rows(limit: int = 28) -> list[dict[str, Any]]:
    conn = connections.get_hrv_db()
    try:
        if not _table_exists(conn, "hrv_measurements"):
            return []
        cols = _columns(conn, "hrv_measurements")
        date_expr = "COALESCE(substr(date_utc,1,10), substr(ts_measurement,1,10))"
        select = [
            f"{date_expr} AS date",
            "rmssd" if "rmssd" in cols else "NULL AS rmssd",
            "hr" if "hr" in cols else "NULL AS hr",
            "sleep_quality" if "sleep_quality" in cols else "NULL AS sleep_quality",
            "COALESCE(alcohol_bool, alcohol) AS alcohol_flag" if {"alcohol_bool", "alcohol"}.issubset(cols) else "alcohol_bool AS alcohol_flag" if "alcohol_bool" in cols else "alcohol AS alcohol_flag" if "alcohol" in cols else "NULL AS alcohol_flag",
            "COALESCE(sickness_bool, sickness) AS sickness_flag" if {"sickness_bool", "sickness"}.issubset(cols) else "sickness_bool AS sickness_flag" if "sickness_bool" in cols else "sickness AS sickness_flag" if "sickness" in cols else "NULL AS sickness_flag",
        ]
        return _rows(conn, f"SELECT {', '.join(select)} FROM hrv_measurements ORDER BY ts_measurement DESC LIMIT ?", (limit,))
    finally:
        conn.close()


def _hrv_rw_conn() -> sqlite3.Connection:
    conn = sqlite3.connect(connections.HRV_DB, timeout=30, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA busy_timeout = 30000")
    return conn


def _ensure_recovery_annotations(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS recovery_day_annotations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            date_iso TEXT NOT NULL,
            annotation_type TEXT NOT NULL,
            value TEXT NULL,
            note TEXT NULL,
            source TEXT NOT NULL DEFAULT 'actions_v2',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            UNIQUE(date_iso, annotation_type)
        )
        """
    )


def _ensure_recovery_day_flags(conn: sqlite3.Connection) -> None:
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS recovery_day_flags (
            date_iso TEXT PRIMARY KEY,
            sickness_bool INTEGER NOT NULL DEFAULT 0,
            alcohol_bool INTEGER NOT NULL DEFAULT 0,
            note TEXT NULL,
            source TEXT NOT NULL DEFAULT 'actions_v2',
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        )
        """
    )


def _recovery_day_flags(date_from: str | None = None, date_to: str | None = None) -> dict[str, dict[str, Any]]:
    conn = _hrv_rw_conn()
    try:
        _ensure_recovery_day_flags(conn)
        where: list[str] = []
        params: list[Any] = []
        if date_from:
            where.append("date(date_iso) >= date(?)")
            params.append(date_from)
        if date_to:
            where.append("date(date_iso) <= date(?)")
            params.append(date_to)
        sql = "SELECT date_iso, sickness_bool, alcohol_bool, note, source, created_at, updated_at FROM recovery_day_flags"
        if where:
            sql += " WHERE " + " AND ".join(where)
        rows = conn.execute(sql, tuple(params)).fetchall()
        return {str(dict(row)["date_iso"]): dict(row) for row in rows}
    finally:
        conn.close()


def _latest_recovery_day_flag() -> dict[str, Any] | None:
    conn = _hrv_rw_conn()
    try:
        _ensure_recovery_day_flags(conn)
        row = conn.execute(
            """
            SELECT date_iso, sickness_bool, alcohol_bool, note, source, created_at, updated_at
            FROM recovery_day_flags
            WHERE COALESCE(sickness_bool, 0) = 1 OR COALESCE(alcohol_bool, 0) = 1
            ORDER BY date(date_iso) DESC
            LIMIT 1
            """
        ).fetchone()
        return dict(row) if row else None
    finally:
        conn.close()


def _resolve_recovery_day_flags(date_iso: str) -> dict[str, Any]:
    date_iso = _parse_date(date_iso, "date", required=True)
    result = {
        "date": date_iso,
        "sickness": False,
        "alcohol": False,
        "flag": None,
        "source": "none",
        "is_explicit": False,
    }
    conn = _hrv_rw_conn()
    try:
        _ensure_recovery_day_flags(conn)
        if _table_exists(conn, "hrv_day_flags"):
            cols = _columns(conn, "hrv_day_flags")
            date_col = "date_iso" if "date_iso" in cols else "date" if "date" in cols else None
            if date_col:
                row = conn.execute(
                    f"SELECT * FROM hrv_day_flags WHERE substr({date_col}, 1, 10) = ? ORDER BY ROWID DESC LIMIT 1",
                    (date_iso,),
                ).fetchone()
                if row:
                    payload = dict(row)
                    raw_flag = str(payload.get("flag") or payload.get("status") or "").strip().lower()
                    if raw_flag == "sick":
                        result.update({"sickness": True, "flag": "sick", "source": "hrv_day_flags.flag", "is_explicit": True})
                        return result
                    if raw_flag == "alcohol":
                        result.update({"alcohol": True, "flag": "alcohol", "source": "hrv_day_flags.flag", "is_explicit": True})
                        return result

        row = conn.execute(
            """
            SELECT date_iso, sickness_bool, alcohol_bool
            FROM recovery_day_flags
            WHERE substr(date_iso, 1, 10) = ?
            ORDER BY updated_at DESC, date_iso DESC
            LIMIT 1
            """,
            (date_iso,),
        ).fetchone()
        if row:
            payload = dict(row)
            sickness = _boolish_flag(payload.get("sickness_bool"))
            alcohol = _boolish_flag(payload.get("alcohol_bool"))
            if sickness or alcohol:
                result.update(
                    {
                        "sickness": sickness,
                        "alcohol": alcohol,
                        "flag": "sick" if sickness else "alcohol",
                        "source": "recovery_day_flags",
                        "is_explicit": True,
                    }
                )
                return result

        if _table_exists(conn, "hrv_measurements"):
            cols = _columns(conn, "hrv_measurements")
            date_expr = "COALESCE(substr(date_utc,1,10), substr(ts_measurement,1,10))"
            select_cols = [f"{date_expr} AS date_iso"]
            if "sickness_bool" in cols:
                select_cols.append("sickness_bool")
            elif "sickness" in cols:
                select_cols.append("sickness AS sickness_bool")
            else:
                select_cols.append("NULL AS sickness_bool")
            if "alcohol_bool" in cols:
                select_cols.append("alcohol_bool")
            elif "alcohol" in cols:
                select_cols.append("alcohol AS alcohol_bool")
            else:
                select_cols.append("NULL AS alcohol_bool")
            row = conn.execute(
                f"""
                SELECT {', '.join(select_cols)}
                FROM hrv_measurements
                WHERE {date_expr} = ?
                ORDER BY COALESCE(ts_measurement, date_utc) DESC
                LIMIT 1
                """,
                (date_iso,),
            ).fetchone()
            if row:
                payload = dict(row)
                sickness = _boolish_flag(payload.get("sickness_bool"))
                alcohol = _boolish_flag(payload.get("alcohol_bool"))
                if sickness or alcohol:
                    result.update(
                        {
                            "sickness": sickness,
                            "alcohol": alcohol,
                            "flag": "sick" if sickness else "alcohol",
                            "source": "hrv_measurements",
                            "is_explicit": True,
                        }
                    )
                    return result
    finally:
        conn.close()
    return result


def _recent_recovery_flags_context(date_iso: str, lookback_days: int = 14) -> dict[str, Any]:
    conn = _hrv_rw_conn()
    try:
        _ensure_recovery_day_flags(conn)
        sick_dates: list[str] = []
        alcohol_dates: list[str] = []
        if _table_exists(conn, "recovery_day_flags"):
            rows = conn.execute(
                """
                SELECT date_iso, sickness_bool, alcohol_bool
                FROM recovery_day_flags
                WHERE date(date_iso) BETWEEN date(?, ?) AND date(?)
                ORDER BY date(date_iso) DESC
                """,
                (date_iso, f"-{max(1, int(lookback_days))} day", date_iso),
            ).fetchall()
            for row in rows:
                payload = dict(row)
                if _boolish_flag(payload.get("sickness_bool")):
                    sick_dates.append(str(payload.get("date_iso")))
                if _boolish_flag(payload.get("alcohol_bool")):
                    alcohol_dates.append(str(payload.get("date_iso")))
        return {
            "recent_sickness_within_14d": bool(sick_dates),
            "last_sick_date": sick_dates[0] if sick_dates else None,
            "recent_alcohol_within_14d": bool(alcohol_dates),
            "last_alcohol_date": alcohol_dates[0] if alcohol_dates else None,
        }
    finally:
        conn.close()


def _recovery_annotations(date_from: str | None = None, date_to: str | None = None) -> dict[str, list[dict[str, Any]]]:
    conn = _hrv_rw_conn()
    try:
        _ensure_recovery_annotations(conn)
        where: list[str] = []
        params: list[Any] = []
        if date_from:
            where.append("date(date_iso) >= date(?)")
            params.append(date_from)
        if date_to:
            where.append("date(date_iso) <= date(?)")
            params.append(date_to)
        sql = "SELECT date_iso, annotation_type, value, note, source, updated_at FROM recovery_day_annotations"
        if where:
            sql += " WHERE " + " AND ".join(where)
        sql += " ORDER BY date_iso DESC, annotation_type ASC"
        out: dict[str, list[dict[str, Any]]] = {}
        for row in conn.execute(sql, tuple(params)).fetchall():
            item = dict(row)
            out.setdefault(str(item.pop("date_iso")), []).append(item)
        return out
    finally:
        conn.close()


def _apply_recovery_live_command(command: str, body: dict[str, Any]) -> dict[str, Any]:
    if command in {"set_sleep_flag", "set_sickness_flag", "set_alcohol_flag"}:
        value = body.get("value")
        if value is None or (isinstance(value, str) and not value.strip()):
            raise ValueError("missing_required_field: value")
    date_iso = _parse_date(body.get("date"), "date") or _today()
    conn = _hrv_rw_conn()
    try:
        _ensure_recovery_annotations(conn)
        _ensure_recovery_day_flags(conn)
        cols = _columns(conn, "hrv_measurements")
        date_expr = "COALESCE(substr(date_utc,1,10), substr(ts_measurement,1,10))"
        now = _utc_iso()

        if command in {"set_alcohol_flag", "set_sickness_flag"}:
            value = _bool_value(body.get("value"), default=False)
            bool_col = "alcohol_bool" if command == "set_alcohol_flag" else "sickness_bool"
            text_col = "alcohol" if command == "set_alcohol_flag" else "sickness"
            assignments: list[str] = []
            params: list[Any] = []
            if _table_exists(conn, "hrv_measurements") and bool_col in cols:
                assignments.append(f"{bool_col} = ?")
                params.append(1 if value else 0)
            if _table_exists(conn, "hrv_measurements") and text_col in cols:
                assignments.append(f"{text_col} = ?")
                params.append("yes" if value else "no")
            updated_rows = 0
            if assignments:
                params.append(date_iso)
                cur = conn.execute(f"UPDATE hrv_measurements SET {', '.join(assignments)} WHERE {date_expr} = ?", tuple(params))
                updated_rows = int(cur.rowcount or 0)
            if updated_rows < 1:
                existing_flag_row = conn.execute("SELECT date_iso FROM recovery_day_flags WHERE date_iso = ?", (date_iso,)).fetchone()
                conn.execute(
                    """
                    INSERT INTO recovery_day_flags (date_iso, sickness_bool, alcohol_bool, note, source, created_at, updated_at)
                    VALUES (?, ?, ?, ?, 'actions_v2', ?, ?)
                    ON CONFLICT(date_iso) DO UPDATE SET
                        sickness_bool = CASE WHEN ? = 'sickness' THEN excluded.sickness_bool ELSE recovery_day_flags.sickness_bool END,
                        alcohol_bool = CASE WHEN ? = 'alcohol' THEN excluded.alcohol_bool ELSE recovery_day_flags.alcohol_bool END,
                        note = COALESCE(excluded.note, recovery_day_flags.note),
                        source = excluded.source,
                        updated_at = excluded.updated_at
                    """,
                    (
                        date_iso,
                        1 if (command == "set_sickness_flag" and value) else 0,
                        1 if (command == "set_alcohol_flag" and value) else 0,
                        str(body.get("reason") or body.get("note") or "").strip() or None,
                        now,
                        now,
                        text_col,
                        text_col,
                    ),
                )
                flag_rows = 1 if existing_flag_row or value else 0
            else:
                flag_rows = 0
            conn.commit()
            return {"date": date_iso, "flag": text_col, "value": value, "updated_rows": updated_rows, "day_flag_rows": flag_rows}

        annotation_type = "sleep_flag" if command == "set_sleep_flag" else "annotation"
        value = body.get("value")
        note = str(body.get("note") or body.get("reason") or "").strip() or None
        conn.execute(
            """
            INSERT INTO recovery_day_annotations (date_iso, annotation_type, value, note, source, created_at, updated_at)
            VALUES (?, ?, ?, ?, 'actions_v2', ?, ?)
            ON CONFLICT(date_iso, annotation_type) DO UPDATE SET
                value=excluded.value,
                note=excluded.note,
                source=excluded.source,
                updated_at=excluded.updated_at
            """,
            (date_iso, annotation_type, None if value is None else str(value), note, now, now),
        )
        conn.commit()
        return {"date": date_iso, "annotation_type": annotation_type, "value": value, "note": note}
    finally:
        conn.close()


def _recovery_summary(date_iso: str | None = None) -> dict[str, Any]:
    target_date = _parse_date(date_iso, "date") if date_iso else None
    rows = _latest_hrv_rows(28)
    if target_date:
        filtered_rows = [row for row in rows if str(row.get("date") or "") <= target_date]
    else:
        filtered_rows = rows
    latest = filtered_rows[0] if filtered_rows else {}
    baseline_rows = filtered_rows[1:]
    rmssd_vals = [_float_or_none(row.get("rmssd")) for row in baseline_rows if _float_or_none(row.get("rmssd")) is not None]
    hr_vals = [_float_or_none(row.get("hr")) for row in baseline_rows if _float_or_none(row.get("hr")) is not None]
    baseline_rmssd = round(sum(rmssd_vals) / len(rmssd_vals), 1) if rmssd_vals else None
    baseline_hr = round(sum(hr_vals) / len(hr_vals), 1) if hr_vals else None
    latest_rmssd = _float_or_none(latest.get("rmssd"))
    latest_hr = _float_or_none(latest.get("hr"))
    status = "missing"
    reasons: list[str] = []
    if latest.get("sickness_flag"):
        status = "low"
        reasons.append("sickness_flag")
    elif latest.get("alcohol_flag"):
        status = "caution"
        reasons.append("alcohol_flag")
    elif latest_rmssd is not None and latest_hr is not None and baseline_rmssd and baseline_hr and len(baseline_rows) >= 7:
        ratio = latest_rmssd / baseline_rmssd
        hr_delta = latest_hr - baseline_hr
        if ratio >= 1.05 and hr_delta <= 3:
            status = "good"
        elif ratio < 0.9 or hr_delta >= 7:
            status = "low"
        else:
            status = "okay"
        reasons.extend([f"rmssd_ratio={ratio:.2f}", f"hr_delta={hr_delta:.1f}"])
    elif latest:
        status = "partial"
        reasons.append("insufficient_baseline")
    polar = polar_state_summary()
    polar_rows = _latest_polar_recovery_rows()
    latest_sleep = polar_rows.get("sleep") or {}
    latest_nightly = polar_rows.get("nightly") or {}
    latest_continuous = polar_rows.get("continuous") or {}
    if target_date:
        if str(latest_sleep.get("date") or "") != target_date:
            latest_sleep = {}
        if str(latest_nightly.get("date") or "") != target_date:
            latest_nightly = {}
        if str(latest_continuous.get("date") or "") != target_date:
            latest_continuous = {}
    polar_date_candidates = [latest_sleep.get("date"), latest_nightly.get("date"), latest_continuous.get("date")]
    polar_date = next((str(item) for item in polar_date_candidates if item), None)
    use_polar = any(
        _polar_row_has_recovery_signal(item)
        for item in (latest_sleep, latest_nightly, latest_continuous)
    )
    latest_date = target_date or polar_date or _today()
    exact_flags = _resolve_recovery_day_flags(str(latest_date))
    recent_flags = _recent_recovery_flags_context(str(latest_date))
    sickness = bool(exact_flags.get("sickness"))
    alcohol = bool(exact_flags.get("alcohol"))
    latest_state = {
        "date": latest_date,
        "source": "polar" if use_polar else "unavailable",
        "rmssd": _float_or_none(latest_nightly.get("mean_recovery_rmssd")) if use_polar else None,
        "night_pulse": _float_or_none(latest_continuous.get("resting_candidate_hr")) if use_polar else None,
        "sleep_heart_rate": _float_or_none(latest_hr) if use_polar else None,
        "sleep_score": _float_or_none(latest_sleep.get("sleep_score")),
        "sleep_start": latest_sleep.get("sleep_start"),
        "sleep_end": latest_sleep.get("sleep_end"),
        "sleep_window_label": _format_sleep_window_label(latest_sleep.get("sleep_start"), latest_sleep.get("sleep_end")),
        "actual_sleep_minutes": _int_or_none(latest_sleep.get("actual_sleep_minutes")),
        "awake_minutes": _int_or_none(latest_sleep.get("awake_minutes")),
        "interruption_minutes": _int_or_none(latest_sleep.get("interruption_minutes")),
        "interruptions": _int_or_none(latest_sleep.get("interruptions")),
        "ans_status": latest_nightly.get("ans_status"),
        "recovery_indicator": latest_nightly.get("recovery_indicator"),
        "recovery_indicator_sublevel": latest_nightly.get("recovery_indicator_sublevel"),
        "ans_rate": _float_or_none(latest_nightly.get("ans_rate")),
        "breathing_rate": _breathing_rate_from_polar_row(latest_nightly) or _breathing_rate_from_polar_row(latest_sleep),
        "flag": exact_flags.get("flag"),
        "status": "sick" if sickness else "flagged" if alcohol else status,
    }
    reported_rmssd = _float_or_none(latest_state.get("rmssd")) if use_polar else None
    return {
        "latest_rmssd": reported_rmssd,
        "latest_hr": latest_hr if use_polar else None,
        "baseline_rmssd_28d": baseline_rmssd if use_polar else None,
        "baseline_hr_28d": baseline_hr if use_polar else None,
        "readiness_summary": status,
        "readiness_reasons": reasons,
        "baseline_count": len(baseline_rows),
        "last_flags": {
            "alcohol": alcohol,
            "sickness": sickness,
        },
        "latest": {k: v for k, v in latest_state.items() if v is not None},
        "flags": {
            "sickness": sickness,
            "alcohol": alcohol,
            "sleep": latest.get("sleep_quality") if latest else None,
        },
        "exact_day_flags": exact_flags,
        "recent_flags": recent_flags,
        "polar": {
            "connected": bool(polar.get("connected")),
            "latest_sleep": polar.get("today", {}).get("sleep") or polar.get("latest_sleep"),
            "latest_nightly_recharge": polar.get("today", {}).get("nightly_recharge") or polar.get("latest_nightly_recharge"),
            "latest_continuous": polar.get("today", {}).get("heart_rate") or polar.get("latest_continuous_samples"),
        },
        "data_status": {
            "polar_connected": bool(polar.get("connected")),
            "polar_data_quality": polar.get("data_quality"),
            "readiness_summary": status,
        },
    }


def _build_gpt_heart_rate_payload(
    source: Any,
    *,
    latest_hr: Any = None,
    latest_continuous: dict[str, Any] | None = None,
    latest_nightly: dict[str, Any] | None = None,
    latest_recovery: dict[str, Any] | None = None,
) -> dict[str, Any]:
    source_text = str(source or "").strip().lower()
    latest_continuous = latest_continuous if isinstance(latest_continuous, dict) else {}
    latest_nightly = latest_nightly if isinstance(latest_nightly, dict) else {}
    latest_recovery = latest_recovery if isinstance(latest_recovery, dict) else {}

    resting_heart_rate_bpm = None
    resting_heart_rate_available = False
    resting_heart_rate_source = None
    night_pulse_bpm = _float_or_none(latest_continuous.get("resting_candidate_hr"))
    if night_pulse_bpm is None:
        night_pulse_bpm = _float_or_none(latest_recovery.get("night_pulse"))
    night_pulse_source = "polar_continuous.resting_candidate_hr" if night_pulse_bpm is not None else None

    sleep_heart_rate_bpm = _float_or_none(latest_hr) if source_text == "polar" else _float_or_none(latest_recovery.get("sleep_heart_rate")) if source_text == "polar" else None
    sleep_heart_rate_source = "polar/recovery_night" if sleep_heart_rate_bpm is not None else None

    return {
        "resting_heart_rate_bpm": resting_heart_rate_bpm,
        "resting_heart_rate_available": resting_heart_rate_available,
        "resting_heart_rate_source": resting_heart_rate_source,
        "night_pulse_bpm": night_pulse_bpm,
        "night_pulse_source": night_pulse_source,
        "sleep_heart_rate_bpm": sleep_heart_rate_bpm,
        "sleep_heart_rate_source": sleep_heart_rate_source,
        "semantic_note": "night_pulse_bpm and sleep_heart_rate_bpm are nocturnal/sleep pulse values, not confirmed resting heart rate",
    }


def _compact_recovery_summary_payload(recovery: dict[str, Any]) -> dict[str, Any]:
    latest = recovery.get("latest") if isinstance(recovery.get("latest"), dict) else {}
    flags = recovery.get("flags") if isinstance(recovery.get("flags"), dict) else {}
    status = str(recovery.get("readiness_summary") or "missing")
    if flags.get("sickness"):
        status = "sick"
    elif flags.get("alcohol") and status == "okay":
        status = "flagged"
    heart_rate = _build_gpt_heart_rate_payload(
        latest.get("source"),
        latest_hr=recovery.get("latest_hr"),
        latest_continuous=((recovery.get("polar") or {}).get("latest_continuous") if isinstance(recovery.get("polar"), dict) else {}) or {},
        latest_nightly=((recovery.get("polar") or {}).get("latest_nightly_recharge") if isinstance(recovery.get("polar"), dict) else {}) or {},
        latest_recovery=latest,
    )
    return {
        "source": latest.get("source"),
        "date": latest.get("date"),
        "status": status,
        "rmssd": latest.get("rmssd", recovery.get("latest_rmssd")),
        "heart_rate": heart_rate,
        "flag": latest.get("flag"),
        "sleep_score": latest.get("sleep_score"),
        "sleep_start": latest.get("sleep_start"),
        "sleep_end": latest.get("sleep_end"),
        "sleep_window_label": latest.get("sleep_window_label"),
        "actual_sleep_minutes": latest.get("actual_sleep_minutes"),
        "awake_minutes": latest.get("awake_minutes"),
        "interruption_minutes": latest.get("interruption_minutes"),
        "ans_status": latest.get("ans_status"),
        "recovery_indicator": latest.get("recovery_indicator"),
        "recovery_indicator_sublevel": latest.get("recovery_indicator_sublevel"),
        "ans_rate": latest.get("ans_rate"),
        "flag": latest.get("flag"),
        "flags": {
            "sickness": flags.get("sickness"),
            "alcohol": flags.get("alcohol"),
            "sleep": flags.get("sleep"),
        },
        "recent_flags": recovery.get("recent_flags") if isinstance(recovery.get("recent_flags"), dict) else {
            "recent_sickness_within_14d": False,
            "last_sick_date": None,
            "recent_alcohol_within_14d": False,
            "last_alcohol_date": None,
        },
    }


def _gpt_recovery_state_payload(summary: dict[str, Any]) -> dict[str, Any]:
    payload = dict(summary or {})
    latest = dict(payload.get("latest") or {}) if isinstance(payload.get("latest"), dict) else {}
    heart_rate = _build_gpt_heart_rate_payload(
        latest.get("source"),
        latest_hr=payload.get("latest_hr"),
        latest_continuous=((payload.get("polar") or {}).get("latest_continuous") if isinstance(payload.get("polar"), dict) else {}) or {},
        latest_nightly=((payload.get("polar") or {}).get("latest_nightly_recharge") if isinstance(payload.get("polar"), dict) else {}) or {},
        latest_recovery=latest,
    )
    payload.pop("latest_hr", None)
    latest.pop("night_pulse", None)
    latest.pop("sleep_heart_rate", None)
    latest["flag"] = latest.get("flag")
    latest["heart_rate"] = heart_rate
    payload["latest"] = latest
    payload["heart_rate"] = heart_rate
    return payload


def _nutrition_targets() -> dict[str, Any]:
    return _nutrition_target_state()["active_targets"]


def _nutrition_target_state() -> dict[str, Any]:
    # The active nutrition template is the canonical source for the current
    # plan. A historical sidecar override must not make nutrition_state drift
    # away from planned_meals and the active plan detail.
    try:
        live = get_live_macro_targets()
    except Exception:
        live = None
    if isinstance(live, dict) and str(live.get("source") or "").strip() not in {"", "settings"}:
        return {
            "active_targets": {
                "kcal": _float_or_none(live.get("kcal")),
                "protein": _float_or_none(live.get("p")),
                "carbs": _float_or_none(live.get("c")),
                "fat": _float_or_none(live.get("f")),
            },
            "targets_source": "live_plan",
            "targets_source_detail": {
                "source": live.get("source"),
                "template_id": live.get("template_id"),
                "template_title": live.get("template_title"),
                "mode": live.get("mode"),
                "effective_date": live.get("effective_date"),
                "updated_at": live.get("updated_at"),
                "live_plan_changed": True,
            },
        }
    override = _get_state(connections.get_nutrition_db, "active_targets_override")
    if override:
        targets = {
            "kcal": _float_or_none(override.get("kcal")),
            "protein": _float_or_none(override.get("protein")),
            "carbs": _float_or_none(override.get("carbs")),
            "fat": _float_or_none(override.get("fat")),
        }
        if any(value is not None for value in targets.values()):
            return {
                "active_targets": targets,
                "targets_source": str(override.get("source") or "command_log"),
                "targets_source_detail": {
                    "mode": str(override.get("source_detail") or "v2_sidecar_override"),
                    "updated_at": override.get("updated_at"),
                    "live_plan_changed": bool(override.get("live_plan_changed")),
                },
            }
    try:
        live = live or get_live_macro_targets()
        source = "live_plan" if str(live.get("source") or "").strip() not in {"", "settings"} else "fallback"
    except Exception:
        live = _nutrition_targets_from_settings()
        source = "fallback"
    return {
        "active_targets": {
            "kcal": _float_or_none(live.get("kcal")),
            "protein": _float_or_none(live.get("p")),
            "carbs": _float_or_none(live.get("c")),
            "fat": _float_or_none(live.get("f")),
        },
        "targets_source": source,
        "targets_source_detail": {
            "source": live.get("source"),
            "mode": live.get("mode"),
            "effective_date": live.get("effective_date"),
            "updated_at": live.get("updated_at"),
            "live_plan_changed": True,
        },
    }


def _set_nutrition_setting(conn: sqlite3.Connection, key: str, value: Any) -> None:
    conn.execute(
        """
        INSERT INTO nutrition_settings (key, value)
        VALUES (?, ?)
        ON CONFLICT(key) DO UPDATE SET value=excluded.value
        """,
        (key, str(value)),
    )


def _apply_nutrition_targets_live(body: dict[str, Any]) -> dict[str, Any]:
    targets = {
        "kcal": _float_or_none(body.get("kcal")),
        "protein": _float_or_none(body.get("protein")),
        "carbs": _float_or_none(body.get("carbs")),
        "fat": _float_or_none(body.get("fat")),
    }
    for key, value in targets.items():
        if value is None or value < 0 or (key == "kcal" and value <= 0):
            raise ValueError(f"{key} is required and must be numeric")

    import nutrition.nutrition_planning_db as nutrition_db

    if hasattr(nutrition_db, "_SCHEMA_READY"):
        nutrition_db._SCHEMA_READY = False
    nutrition_db.ensure_nutrition_planning_schema()
    conn = connections.get_nutrition_db()
    now = _utc_iso()
    try:
        conn.execute("CREATE TABLE IF NOT EXISTS nutrition_settings (key TEXT PRIMARY KEY, value TEXT)")
        rows = {row["key"]: row["value"] for row in conn.execute("SELECT key, value FROM nutrition_settings").fetchall()}
        mode = str(body.get("mode") or rows.get("active_mode") or rows.get("selected_mode") or "maintenance").strip() or "maintenance"
        _set_nutrition_setting(conn, "active_mode", mode)
        _set_nutrition_setting(conn, "selected_mode", mode)
        _set_nutrition_setting(conn, f"mode_{mode}_target", targets["kcal"])
        _set_nutrition_setting(conn, f"mode_{mode}_protein_target", targets["protein"])
        _set_nutrition_setting(conn, f"mode_{mode}_carbs_target", targets["carbs"])
        _set_nutrition_setting(conn, f"mode_{mode}_fat_target", targets["fat"])
        bounds = {
            "green_low": _float_or_none(body.get("green_low")),
            "green_high": _float_or_none(body.get("green_high")),
            "yellow_low": _float_or_none(body.get("yellow_low")),
            "yellow_high": _float_or_none(body.get("yellow_high")),
        }
        if any(value is not None for value in bounds.values()):
            if any(value is None for value in bounds.values()):
                raise ValueError("green_low, green_high, yellow_low and yellow_high must be provided together")
            if not (bounds["yellow_low"] <= bounds["green_low"] <= targets["kcal"] <= bounds["green_high"] <= bounds["yellow_high"]):
                raise ValueError("target bands must satisfy yellow_low <= green_low <= kcal <= green_high <= yellow_high")
            for key, value in bounds.items():
                _set_nutrition_setting(conn, f"mode_{mode}_{key}", value)

        active_template = None
        active_days_updated = 0
        if _table_exists(conn, "nutrition_week_templates"):
            active_template = conn.execute(
                "SELECT id FROM nutrition_week_templates WHERE is_active=1 ORDER BY updated_at DESC, id DESC LIMIT 1"
            ).fetchone()
            if active_template and _table_exists(conn, "nutrition_week_template_days"):
                cur = conn.execute(
                    """
                    UPDATE nutrition_week_template_days
                    SET target_kcal=?, target_p=?, target_c=?, target_f=?, updated_at=?
                    WHERE week_template_id=?
                    """,
                    (targets["kcal"], targets["protein"], targets["carbs"], targets["fat"], now, active_template["id"]),
                )
                active_days_updated = int(cur.rowcount or 0)
        conn.commit()
        template_macro_settings = None
        if active_template:
            current_macro_settings, current_macro_error = get_week_template_macro_settings(int(active_template["id"]))
            if current_macro_error:
                raise ValueError(f"active nutrition plan targets could not be read: {current_macro_error}")
            mode_values = dict((((current_macro_settings or {}).get("modes") or {}).get(mode) or {}))
            mode_values.update({
                "kcal_target": targets["kcal"],
                "protein_target": targets["protein"],
                "carbs_target": targets["carbs"],
                "fat_target": targets["fat"],
            })
            mode_values.update({key: value for key, value in bounds.items() if value is not None})
            template_macro_settings, template_error = update_week_template_macro_settings(
                int(active_template["id"]),
                {"active_mode": mode, "modes": {mode: mode_values}},
            )
            if template_error:
                raise ValueError(f"active nutrition plan targets could not be updated: {template_error}")
        live = nutrition_db.get_live_macro_targets()
        result = {
            "active_targets": targets,
            "mode": mode,
            "settings_updated": True,
            "active_week_template_id": int(active_template["id"]) if active_template else None,
            "active_week_template_days_updated": active_days_updated,
            "target_bands": bounds if all(value is not None for value in bounds.values()) else None,
            "template_macro_settings": template_macro_settings,
            "live_targets_after": {
                "kcal": _float_or_none(live.get("kcal")),
                "protein": _float_or_none(live.get("p")),
                "carbs": _float_or_none(live.get("c")),
                "fat": _float_or_none(live.get("f")),
                "source": live.get("source"),
                "mode": live.get("mode"),
            },
        }
        _set_state(
            connections.get_nutrition_db,
            "active_targets_override",
            {**targets, "mode": mode, "source": "live_plan", "source_detail": "canonical_nutrition_settings", "live_plan_changed": True},
        )
        return result
    finally:
        conn.close()


def _create_nutrition_food(body: dict[str, Any], *, dry_run: bool) -> dict[str, Any]:
    name = str(body.get("name") or "").strip()
    if not name:
        raise ValueError("name is required")
    unit = str(body.get("unit_default") or body.get("unit") or "g").strip().lower()
    unit_aliases = {"piece": "pcs", "pieces": "pcs", "stück": "pcs", "stueck": "pcs", "gram": "g"}
    unit = unit_aliases.get(unit, unit)
    if unit not in {"g", "ml", "pcs"}:
        raise ValueError("unit must be g, ml or pcs")

    canonical_keys = ("kcal_per_100", "p_per_100", "c_per_100", "f_per_100")
    has_canonical = any(body.get(key) not in (None, "") for key in canonical_keys)
    if has_canonical:
        macros = {key: _float_or_none(body.get(key)) for key in canonical_keys}
        if any(value is None or value < 0 for value in macros.values()):
            raise ValueError("kcal_per_100, p_per_100, c_per_100 and f_per_100 are required together")
        portion_g = _float_or_none(body.get("portion_g"))
        common_portion = _float_or_none(body.get("common_portion_size"))
    else:
        serving = {
            "kcal": _float_or_none(body.get("kcal")),
            "protein": _float_or_none(body.get("protein")),
            "carbs": _float_or_none(body.get("carbs")),
            "fat": _float_or_none(body.get("fat")),
        }
        if any(value is None or value < 0 for value in serving.values()):
            raise ValueError("kcal, protein, carbs and fat are required for the declared portion")
        serving_size = _float_or_none(body.get("serving_size") or body.get("portion_size"))
        if unit in {"g", "ml"}:
            serving_size = serving_size or 100.0
            if serving_size <= 0:
                raise ValueError("serving_size must be greater than zero")
            factor = 100.0 / serving_size
            portion_g = serving_size
            common_portion = serving_size
        else:
            serving_weight_g = _float_or_none(body.get("serving_weight_g") or body.get("portion_g"))
            factor = (100.0 / serving_weight_g) if serving_weight_g and serving_weight_g > 0 else 1.0
            portion_g = serving_weight_g
            common_portion = serving_weight_g
        macros = {
            "kcal_per_100": round(serving["kcal"] * factor, 4),
            "p_per_100": round(serving["protein"] * factor, 4),
            "c_per_100": round(serving["carbs"] * factor, 4),
            "f_per_100": round(serving["fat"] * factor, 4),
        }

    food_payload = {
        "name": name,
        "brand": body.get("brand"),
        "unit_default": unit,
        "portion_g": portion_g,
        "common_portion_size": common_portion,
        "category": body.get("category"),
        "tags": body.get("tags"),
        "is_favorite": body.get("is_favorite", False),
        "sugar_per_100": _float_or_none(body.get("sugar_per_100")),
        "salt_per_100": _float_or_none(body.get("salt_per_100")),
        **macros,
    }
    if dry_run:
        return {"dry_run": True, "created": False, "normalized_food": food_payload}
    food, error = create_food(food_payload)
    if error:
        raise ValueError(error)
    return {"created": True, "food": food}


def _nutrition_targets_from_settings() -> dict[str, Any]:
    conn = connections.get_nutrition_db()
    try:
        if not _table_exists(conn, "nutrition_settings"):
            return {}
        rows = {row["key"]: row["value"] for row in conn.execute("SELECT key, value FROM nutrition_settings").fetchall()}
        mode = rows.get("active_mode") or "maintenance"
        prefix = f"mode_{mode}_"
        return {
            "kcal": _float_or_none(rows.get(prefix + "target")),
            "p": _float_or_none(rows.get(prefix + "protein_target")),
            "c": _float_or_none(rows.get(prefix + "carbs_target")),
            "f": _float_or_none(rows.get(prefix + "fat_target")),
            "source": "settings",
            "mode": mode,
        }
    finally:
        conn.close()


def _nutrition_daily(date_from: str | None, date_to: str | None, limit: int) -> list[dict[str, Any]]:
    conn = connections.get_nutrition_db()
    try:
        by_date: dict[str, dict[str, Any]] = {}
        where: list[str] = []
        params: list[Any] = []
        if date_from:
            where.append("date(day) >= date(?)")
            params.append(date_from)
        if date_to:
            where.append("date(day) <= date(?)")
            params.append(date_to)
        if _table_exists(conn, "nutrition_day_actuals"):
            sql = """
                SELECT day AS date, kcal, p AS protein, c AS carbs, f AS fat, source,
                       CASE WHEN kcal IS NOT NULL OR p IS NOT NULL OR c IS NOT NULL OR f IS NOT NULL THEN 1 ELSE 0 END AS logged
                FROM nutrition_day_actuals
            """
            if where:
                sql += " WHERE " + " AND ".join(where)
            for row in _rows(conn, sql, tuple(params)):
                by_date[str(row.get("date"))] = row

        if _table_exists(conn, "weight_logs"):
            weight_where: list[str] = []
            weight_params: list[Any] = []
            if date_from:
                weight_where.append("date(date_iso) >= date(?)")
                weight_params.append(date_from)
            if date_to:
                weight_where.append("date(date_iso) <= date(?)")
                weight_params.append(date_to)
            sql = """
                SELECT date_iso AS date, kcal, protein, carbs, fat, raw_json,
                       CASE WHEN kcal IS NOT NULL OR protein IS NOT NULL OR carbs IS NOT NULL OR fat IS NOT NULL THEN 1 ELSE 0 END AS logged
                FROM weight_logs
            """
            if weight_where:
                sql += " WHERE " + " AND ".join(weight_where)
            for row in _rows(conn, sql, tuple(weight_params)):
                if not row.get("date"):
                    continue
                raw = _json_loads(row.get("raw_json"), {}) if row.get("raw_json") else {}
                source_detail = raw.get("source") if isinstance(raw, dict) else None
                has_macros = any(row.get(key) is not None for key in ("kcal", "protein", "carbs", "fat"))
                if has_macros:
                    by_date[str(row["date"])] = {
                        "date": row["date"],
                        "kcal": row.get("kcal"),
                        "protein": row.get("protein"),
                        "carbs": row.get("carbs"),
                        "fat": row.get("fat"),
                        "source": f"weight_logs:{source_detail}" if source_detail else "weight_logs",
                        "logged": row.get("logged"),
                    }
        return sorted(by_date.values(), key=lambda row: str(row.get("date") or ""), reverse=True)[:limit]
    finally:
        conn.close()


def _nutrition_state() -> dict[str, Any]:
    today = _today()
    daily = _nutrition_daily((date.today() - timedelta(days=6)).isoformat(), today, 7)
    today_row = next((row for row in daily if row.get("date") == today), None)
    logged_days = sum(1 for row in daily if row.get("logged"))
    domain = _nutrition_domain_status()
    target_state = _nutrition_target_state()
    return {
        "active_targets": target_state["active_targets"],
        "targets_source": target_state["targets_source"],
        "targets_source_detail": target_state["targets_source_detail"],
        "today_actuals": (
            {
                "kcal": _float_or_none(today_row.get("kcal")),
                "protein": _float_or_none(today_row.get("protein")),
                "carbs": _float_or_none(today_row.get("carbs")),
                "fat": _float_or_none(today_row.get("fat")),
            }
            if today_row and bool(today_row.get("logged"))
            else None
        ),
        "today_actuals_status": "available" if today_row and bool(today_row.get("logged")) else "missing",
        "adherence_summary": {"last_7d": round(logged_days / 7, 2), "logged_days_7d": logged_days},
        "logging_streak": _nutrition_logging_streak(),
        "domain_status": domain,
    }


def _nutrition_domain_status() -> dict[str, Any]:
    targets = _nutrition_targets()
    targets_present = any(value is not None and value > 0 for value in targets.values())
    conn = connections.get_nutrition_db()
    try:
        foods_count = conn.execute("SELECT COUNT(*) AS c FROM nutrition_foods").fetchone()["c"] if _table_exists(conn, "nutrition_foods") else 0
        daily_count = conn.execute("SELECT COUNT(*) AS c FROM nutrition_day_actuals").fetchone()["c"] if _table_exists(conn, "nutrition_day_actuals") else 0
        meal_count = conn.execute("SELECT COUNT(*) AS c FROM nutrition_logged_meals").fetchone()["c"] if _table_exists(conn, "nutrition_logged_meals") else 0
        latest_daily = None
        if _table_exists(conn, "nutrition_day_actuals"):
            row = conn.execute("SELECT MAX(day) AS d FROM nutrition_day_actuals").fetchone()
            latest_daily = row["d"] if row else None
        latest_meal = None
        logged_meal_days_7d = 0
        if _table_exists(conn, "nutrition_logged_meals"):
            cols = _columns(conn, "nutrition_logged_meals")
            date_expr = None
            if "log_date" in cols and "logged_at" in cols:
                date_expr = "COALESCE(date(log_date), date(logged_at))"
            elif "log_date" in cols:
                date_expr = "date(log_date)"
            elif "logged_at" in cols:
                date_expr = "date(logged_at)"
            elif "created_at" in cols:
                date_expr = "date(created_at)"
            if date_expr:
                row = conn.execute(f"SELECT MAX({date_expr}) AS d FROM nutrition_logged_meals").fetchone()
                latest_meal = row["d"] if row else None
                row = conn.execute(f"SELECT COUNT(DISTINCT {date_expr}) AS c FROM nutrition_logged_meals WHERE {date_expr} >= date(?, '-6 day')", (_today(),)).fetchone()
                logged_meal_days_7d = int(row["c"] or 0) if row else 0
        logged_daily_days_7d = 0
        if _table_exists(conn, "nutrition_day_actuals"):
            row = conn.execute("SELECT COUNT(DISTINCT day) AS c FROM nutrition_day_actuals WHERE date(day) >= date(?, '-6 day')", (_today(),)).fetchone()
            logged_daily_days_7d = int(row["c"] or 0) if row else 0
    finally:
        conn.close()
    latest_log = max([d for d in (latest_daily, latest_meal) if d], default=None)
    if not targets_present and foods_count == 0 and daily_count == 0 and meal_count == 0:
        status = "missing"
        reason = "no_targets_or_logs"
    elif not latest_log:
        status = "partial" if targets_present or foods_count else "missing"
        reason = "targets_or_foods_without_logs"
    else:
        try:
            age_days = (date.today() - date.fromisoformat(str(latest_log)[:10])).days
        except Exception:
            age_days = 999
        if age_days > 10:
            status = "stale"
            reason = f"latest_log_age_days={age_days}"
        elif logged_daily_days_7d > 0:
            status = "fresh" if age_days <= 2 else "partial"
            reason = f"daily_totals_recent_age_days={age_days}"
        elif logged_meal_days_7d >= 3:
            status = "fresh" if age_days <= 1 else "partial"
            reason = f"meal_logs_recent_days_7d={logged_meal_days_7d}"
        else:
            status = "partial"
            reason = "structure_available_but_current_logs_incomplete"
    return {
        "status": status,
        "reason": reason,
        "targets_present": targets_present,
        "foods_count": int(foods_count or 0),
        "daily_totals_count": int(daily_count or 0),
        "logged_meals_count": int(meal_count or 0),
        "logged_daily_days_7d": logged_daily_days_7d,
        "logged_meal_days_7d": logged_meal_days_7d,
        "last_sync": latest_log,
    }


def _nutrition_logging_streak() -> int:
    rows = _nutrition_daily(None, _today(), 60)
    logged = {row["date"] for row in rows if row.get("logged")}
    streak = 0
    cursor = date.today()
    while cursor.isoformat() in logged:
        streak += 1
        cursor -= timedelta(days=1)
    return streak


def _weight_rows(date_from: str | None, date_to: str | None, limit: int = 200) -> list[dict[str, Any]]:
    conn = connections.get_nutrition_db()
    try:
        if not _table_exists(conn, "weight_logs"):
            return []
        cols = _columns(conn, "weight_logs")
        weight_col = "weight_kg" if "weight_kg" in cols else "weight" if "weight" in cols else None
        date_col = "date_iso" if "date_iso" in cols else "date" if "date" in cols else None
        if not weight_col or not date_col:
            return []
        where: list[str] = []
        params: list[Any] = []
        if date_from:
            where.append(f"date({date_col}) >= date(?)")
            params.append(date_from)
        if date_to:
            where.append(f"date({date_col}) <= date(?)")
            params.append(date_to)
        sql = f"SELECT {date_col} AS date, {weight_col} AS weight FROM weight_logs"
        if where:
            sql += " WHERE " + " AND ".join(where)
        sql += f" ORDER BY date({date_col}) DESC LIMIT ?"
        return _rows(conn, sql, tuple(params + [limit]))
    finally:
        conn.close()


def _weight_trend_rows(as_of: str) -> list[dict[str, Any]]:
    """Read raw canonical-source rows; calculation lives in weight_trend."""
    conn = connections.get_nutrition_db()
    try:
        if not _table_exists(conn, "weight_logs"):
            return []
        cols = _columns(conn, "weight_logs")
        weight_col = "weight_kg" if "weight_kg" in cols else "weight" if "weight" in cols else None
        date_col = "date_iso" if "date_iso" in cols else "date" if "date" in cols else None
        if not weight_col or not date_col:
            return []
        fields = [f"{date_col} AS date", f"{weight_col} AS weight", "id" if "id" in cols else "rowid AS id"]
        if "created_at" in cols:
            fields.append("created_at")
        if "updated_at" in cols:
            fields.append("updated_at")
        return _rows(
            conn,
            f"SELECT {', '.join(fields)} FROM weight_logs WHERE date({date_col}) <= date(?) ORDER BY date({date_col}) DESC, id DESC LIMIT 1000",
            (as_of,),
        )
    finally:
        conn.close()


def _weight_state(as_of: str | None = None) -> dict[str, Any]:
    as_of = _parse_date(as_of, "as_of") or _today()
    trend_payload = build_weight_trend(_weight_trend_rows(as_of), as_of)
    calendar_week = trend_payload["calendar_week"]
    current = calendar_week["current"]
    trend_delta = calendar_week["delta_kg"]
    trend = "insufficient_data" if trend_delta is None else "up" if trend_delta > 0.35 else "down" if trend_delta < -0.35 else "flat"
    latest = trend_payload.get("latest_measurement") or {}
    latest_date = latest.get("date")
    stale = True
    age_days = None
    if latest_date:
        try:
            age_days = (date.fromisoformat(as_of) - date.fromisoformat(str(latest_date))).days
            stale = age_days > 3
        except Exception:
            stale = True
    return {
        "latest_weight": _float_or_none(latest.get("weight_kg")),
        "trend_direction": trend,
        "calendar_week_average_kg": current["mean_kg"],
        "calendar_week_delta_kg": trend_delta,
        "calendar_week_status": calendar_week["status"],
        "calendar_week_measurements": current["sample_count"],
        "calorie_adjustment_eligible": calendar_week["calorie_adjustment_eligible"],
        "checkin_status": "weight_fresh" if not stale else "weight_stale",
        "latest_weight_age_days": age_days,
        "weight_trend": trend_payload,
    }


def _weight_date_pretty(date_iso: str) -> str:
    try:
        parsed = date.fromisoformat(date_iso)
        return parsed.strftime("%d.%m.%y")
    except Exception:
        return date_iso


def _weight_raw_json(command: str, body: dict[str, Any]) -> str:
    return json.dumps(
        {
            "source": "actions_v2",
            "command": command,
            "payload": {k: v for k, v in body.items() if k != "command"},
            "created_at": _utc_iso(),
        },
        ensure_ascii=False,
    )


