def _liva_coach_capabilities() -> dict[str, Any]:
    commands: dict[str, dict[str, Any]] = {}
    for domain in ("core", "training", "nutrition", "weight", "cardio", "recovery", "endurance"):
        commands[domain] = {}
        for command in sorted(LIVA_ACT_COMMANDS[domain]):
            commands[domain][command] = {
                **dict(LIVA_COACH_PAYLOAD_HINTS.get(domain, {}).get(command) or {}),
                "dry_run_supported": (domain, command) in LIVA_DRY_RUN_SUPPORTED,
                "confirm_required_for_live": (domain, command) in LIVA_CONFIRM_REQUIRED or (domain == "training" and command == "log_gym_session"),
                "live_by_default": True,
            }
    contract_revision = os.getenv("LIVA_CAPABILITY_REVISION") or hashlib.sha256(
        json.dumps({"read_modes": sorted(LIVA_READ_MODES), "commands": commands}, sort_keys=True).encode("utf-8")
    ).hexdigest()[:16]
    return {
        "contract_version": "2026-09-10.1",
        "contract_revision": contract_revision,
        "forward_compatible_facade": True,
        "read_modes": sorted(mode for mode in LIVA_READ_MODES if mode != "memory"),
        "read_hints": {
            "nutrition_data": {
                "payload": {"nutrition_mode": "meals", "date_from": "YYYY-MM-DD", "date_to": "YYYY-MM-DD", "limit": 500},
                "accepted_modes": ["daily_totals", "meals", "planned_meals"],
                "mode_aliases": ["payload.nutrition_mode", "payload.mode", "payload.data_mode"],
                "returns": ["real_logged_meals", "food_ids_and_names", "quantities_and_units", "meal_macros", "daily_groups"],
            },
            "training_exercises": {"payload": {"query": "RDL", "limit": 25}, "returns": ["movement_library_entries", "historical_exercises", "exercise_id"]},
            "training_exercise_detail": {"payload": {"exercise_id": "from training_exercises; name is also accepted when unique"}},
            "nutrition_plan": {"payload": {"template_id": "optional; omit for active plan"}, "returns": ["revision", "day_groups", "grouping_contract", "days", "meals", "slot_path", "food_ids", "quantities", "targets"]},
            "training_plan": {"payload": {"detail": "compact"}, "returns": ["mode", "weekly_training_status", "blocked_rest_days", "gym_days", "scheduled_gym_days_per_week", "scheduled_rest_days_per_week", "rolling_week_pattern"]},
            "endurance_plan": {"payload": {"plan_id": "ep_... from endurance_plans"}, "identifier_type": "string"},
            "endurance_session": {"payload": {"plan_id": "ep_...", "session_id": "string returned by endurance_week/endurance_calendar"}, "identifier_type": "string", "date_fallback": "YYYY-MM-DD"},
        },
        "workflows": {
            "rebuild_nutrition_plan_from_actuals": [
                "read nutrition_data for a multi-day meals range",
                "read the active nutrition_plan detail",
                "read training_plan and obey weekly_training_status; rolling does not erase blocked rest days",
                "reuse real logged food IDs/names; adjust quantities as needed",
                "place gym-only meals only on weekdays whose training status is gym; omit them on rest days",
                "dry-run patch_nutrition_plan with the exact template_id",
                "execute live with confirm=true after the structural preview is authorized",
                "read nutrition_plan again and verify names, foods, quantities and targets",
            ]
        },
        "commands": commands,
        "memory": {
            "canonical_backend": "liva_memory_v2",
            "recall_tool": "liva_memory_recall",
            "write_flow": {"begin": "liva_memory_begin", "finish": "liva_memory_finish"},
            "import_tool": "liva_memory_import_file",
            "source_tool": "liva_memory_source",
            "legacy_memos": {"status": "read_only_archive"},
        },
        "indexing": "Logged workout exercise_index/set_index values are zero-based and must come from training_workout_coach_view.",
    }

