def _liva_supported_commands(domain: str) -> list[str]:
    return sorted(LIVA_ACT_COMMANDS.get(domain, set()))


def _liva_act_error(code: str, message: str, *, domain: str | None = None, command: str | None = None, status: int = 400, supported: bool | None = None):
    error: dict[str, Any] = {"code": code, "message": message}
    if domain:
        error["domain"] = domain
    if command:
        error["command"] = command
    if supported is not None:
        error["supported"] = supported
    if domain in LIVA_ACT_COMMANDS:
        error["supported_commands"] = _liva_supported_commands(domain)
    return {"ok": False, "error": error}, status


def _normalize_liva_act_payload(body: dict[str, Any]) -> dict[str, Any]:
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    value = body.get("value") if isinstance(body.get("value"), dict) else {}
    merged = dict(payload)
    for key, value_item in value.items():
        merged.setdefault(key, value_item)
    for key, value in body.items():
        if key in {"domain", "command", "payload", "dry_run", "confirm"}:
            continue
        if value is None or (value == "" and key not in {"note", "notes", "new_notes"}):
            continue
        if key in LIVA_TOP_LEVEL_FORWARD_FIELDS or key not in merged:
            merged[key] = value
    return merged


def _capability_required_error(domain: str, command: str, payload: dict[str, Any]) -> tuple[dict[str, Any], int] | None:
    """Make the published action contract executable before any handler runs."""
    contract = (LIVA_COACH_PAYLOAD_HINTS.get(domain, {}) or {}).get(command, {}) or {}
    for field in contract.get("required", []):
        value = payload.get(field)
        if value is None or (isinstance(value, str) and not value.strip()):
            return _liva_act_error("invalid_arguments", f"missing_required_field: {field}", domain=domain, command=command, status=400, supported=True)
    empty_string_is_value = {"note", "notes", "new_notes"}

    def has_value(field: str) -> bool:
        if field not in payload or payload[field] is None:
            return False
        value = payload[field]
        return not isinstance(value, str) or bool(value.strip()) or field in empty_string_is_value

    for key in ("required_any", "required_any_value", "required_any_duration"):
        groups = contract.get(key, [])
        if groups and not any(all(has_value(field) for field in group) for group in groups):
            alternatives = " OR ".join("+".join(group) for group in groups)
            return _liva_act_error("invalid_arguments", "missing_required_any: " + alternatives, domain=domain, command=command, status=400, supported=True)
    return None


def _extract_liva_patch_target_id(body: dict[str, Any], *, aliases: tuple[str, ...]) -> int | None:
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    value = body.get("value") if isinstance(body.get("value"), dict) else {}
    for key in aliases:
        candidate = body.get(key) if body.get(key) not in (None, "") else value.get(key) if value.get(key) not in (None, "") else payload.get(key)
        parsed = _int_or_none(candidate)
        if parsed is not None:
            return parsed
    return None


def _extract_liva_patch_operations(body: dict[str, Any]) -> list[dict[str, Any]] | None:
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    value = body.get("value") if isinstance(body.get("value"), dict) else {}
    patch = payload.get("patch") if isinstance(payload.get("patch"), dict) else {}
    for candidate in (
        body.get("operations"),
        value.get("operations"),
        payload.get("operations"),
        patch.get("operations"),
    ):
        if isinstance(candidate, list):
            return candidate
    return None


def _patch_received_keys(body: dict[str, Any]) -> list[str]:
    value = body.get("value") if isinstance(body.get("value"), dict) else {}
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    return sorted({str(key) for source in (body, value, payload) for key in source.keys()})


def _liva_patch_contract_error(
    code: str,
    message: str,
    *,
    domain: str,
    command: str,
    target_id: int | None = None,
    accepted_shapes: list[str] | None = None,
    received_keys: list[str] | None = None,
    status: int = 400,
) -> tuple[dict[str, Any], int]:
    error = {
        "code": code,
        "message": message,
        "domain": domain,
        "command": command,
        "target_id": target_id,
    }
    if accepted_shapes:
        error["accepted_shapes"] = accepted_shapes
    return (
        {
            "ok": False,
            "error": error,
            "execution": _execution("no_change", False, [], f"{domain}.{command} stopped before any write."),
            **({"received_keys": received_keys} if received_keys else {}),
            "result": {
                "domain": domain,
                "command": command,
                "target_id": target_id,
                "live_state_changed": False,
            },
        },
        status,
    )


def _normalize_liva_training_patch_body(body: dict[str, Any], *, dry_run: bool, confirm: bool) -> tuple[dict[str, Any] | None, tuple[dict[str, Any], int] | None]:
    received_keys = _patch_received_keys(body)
    plan_id = _extract_liva_patch_target_id(body, aliases=("plan_id", "id"))
    if plan_id is None:
        return None, _liva_patch_contract_error("target_plan_required", "plan_id or id is required for patch_training_plan.", domain="training", command="patch_training_plan", received_keys=received_keys)
    operations = _extract_liva_patch_operations(body)
    if not operations:
        return None, _liva_patch_contract_error(
            "operations_required",
            "patch_training_plan requires operations as top-level operations, value.operations, or payload.operations",
            domain="training",
            command="patch_training_plan",
            target_id=plan_id,
            accepted_shapes=["operations", "value.operations", "payload.operations"],
            received_keys=received_keys,
        )
    forwarded = _normalize_liva_act_payload(body)
    forwarded["command"] = "patch_training_plan"
    forwarded["plan_id"] = plan_id
    forwarded["operations"] = operations
    forwarded["dry_run"] = dry_run
    forwarded["confirm"] = confirm
    if body.get("source_message") not in (None, ""):
        forwarded["source_message"] = body.get("source_message")
    if body.get("reason") not in (None, ""):
        forwarded["reason"] = body.get("reason")
    return forwarded, None


def _normalize_liva_nutrition_patch_body(body: dict[str, Any], *, dry_run: bool, confirm: bool) -> tuple[dict[str, Any] | None, tuple[dict[str, Any], int] | None]:
    template_id = _extract_liva_patch_target_id(body, aliases=("template_id", "plan_id", "id"))
    if template_id is None:
        return None, _liva_patch_contract_error("target_plan_required", "template_id, plan_id or id is required for patch_nutrition_plan.", domain="nutrition", command="patch_nutrition_plan")
    operations = _extract_liva_patch_operations(body)
    if not operations:
        return None, _liva_patch_contract_error("operations_required", "operations are required for patch_nutrition_plan.", domain="nutrition", command="patch_nutrition_plan", target_id=template_id)
    forwarded = _normalize_liva_act_payload(body)
    forwarded["command"] = "patch_nutrition_plan"
    forwarded["template_id"] = template_id
    forwarded["operations"] = operations
    forwarded["dry_run"] = dry_run
    forwarded["confirm"] = confirm
    return forwarded, None


def _liva_confirm_required(domain: str, command: str, *, dry_run: bool, payload: dict[str, Any]) -> bool:
    if dry_run:
        return False
    if (domain, command) in LIVA_CONFIRM_REQUIRED:
        return True
    if domain == "training" and command == "log_gym_session":
        return True
    if domain == "remote" and command == "pc_action":
        return str(payload.get("action") or "").strip().lower() in {"wake", "shutdown"}
    return False


def _apply_weight_live_command(command: str, body: dict[str, Any]) -> dict[str, Any]:
    conn = connections.get_nutrition_db()
    try:
        if not _table_exists(conn, "weight_logs"):
            raise ValueError("weight_logs table is missing")
        cols = set(_columns(conn, "weight_logs"))
        row_id = _int_or_none(body.get("id"))
        date_required = command in {"edit_weight", "delete_weight"} and row_id is None
        date_iso = _parse_date(body.get("date"), "date", required=date_required) or _today()
        now_db = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        if command == "log_weight":
            weight = _float_or_none(
                body.get("weight")
                if body.get("weight") not in (None, "")
                else body.get("weight_kg")
                if body.get("weight_kg") not in (None, "")
                else body.get("value")
            )
            if weight is None:
                raise ValueError("weight is required and must be numeric")
            if weight < 40 or weight > 120:
                raise ValueError("weight must be between 40 and 120 kg")
            existing = conn.execute("SELECT id FROM weight_logs WHERE date_iso = ? ORDER BY id DESC LIMIT 1", (date_iso,)).fetchone()
            raw_json = _weight_raw_json(command, body) if "raw_json" in cols else None
            if existing:
                assignments = ["weight_kg = ?"] if "weight_kg" in cols else ["weight = ?"]
                params: list[Any] = [weight]
                if "raw_json" in cols:
                    assignments.append("raw_json = ?")
                    params.append(raw_json)
                params.append(date_iso)
                conn.execute(f"UPDATE weight_logs SET {', '.join(assignments)} WHERE date_iso = ?", tuple(params))
                conn.commit()
                return {"date": date_iso, "weight": weight, "updated": True, "inserted": False, "row_id": int(existing["id"])}

            insert_values: dict[str, Any] = {}
            if "date" in cols:
                insert_values["date"] = _weight_date_pretty(date_iso)
            if "date_iso" in cols:
                insert_values["date_iso"] = date_iso
            insert_values["weight_kg" if "weight_kg" in cols else "weight"] = weight
            if "created_at" in cols:
                insert_values["created_at"] = now_db
            if "raw_json" in cols:
                insert_values["raw_json"] = raw_json
            keys = list(insert_values)
            placeholders = ", ".join("?" for _ in keys)
            cur = conn.execute(f"INSERT INTO weight_logs ({', '.join(keys)}) VALUES ({placeholders})", tuple(insert_values[k] for k in keys))
            conn.commit()
            return {"date": date_iso, "weight": weight, "updated": False, "inserted": True, "row_id": int(cur.lastrowid)}

        if command == "edit_weight":
            weight = _float_or_none(
                body.get("weight")
                if body.get("weight") not in (None, "")
                else body.get("weight_kg")
                if body.get("weight_kg") not in (None, "")
                else body.get("value")
            )
            if weight is None:
                raise ValueError("weight is required and must be numeric")
            if weight < 40 or weight > 120:
                raise ValueError("weight must be between 40 and 120 kg")
            weight_col = "weight_kg" if "weight_kg" in cols else "weight" if "weight" in cols else None
            if not weight_col:
                raise ValueError("weight column is missing")
            if row_id is not None:
                cur = conn.execute(f"UPDATE weight_logs SET {weight_col} = ? WHERE id = ?", (weight, row_id))
            else:
                cur = conn.execute(f"UPDATE weight_logs SET {weight_col} = ? WHERE date_iso = ?", (weight, date_iso))
            if cur.rowcount < 1:
                raise ValueError("weight_entry_not_found")
            conn.commit()
            return {"date": date_iso, "weight": weight, "updated": True, "row_id": row_id}

        if command == "delete_weight":
            if row_id is not None:
                cur = conn.execute("DELETE FROM weight_logs WHERE id = ?", (row_id,))
            else:
                cur = conn.execute("DELETE FROM weight_logs WHERE date_iso = ?", (date_iso,))
            if cur.rowcount < 1:
                raise ValueError("weight_entry_not_found")
            conn.commit()
            return {"date": date_iso, "deleted": True, "deleted_rows": int(cur.rowcount), "row_id": row_id}

        raise ValueError("unsupported_live_weight_command")
    finally:
        conn.close()


def _runs_rows(date_from: str | None, date_to: str | None, limit: int = 200) -> list[dict[str, Any]]:
    conn = connections.get_runs_db()
    try:
        if not _table_exists(conn, "runs"):
            return []
        where: list[str] = []
        params: list[Any] = []
        if date_from:
            where.append("date(date) >= date(?)")
            params.append(date_from)
        if date_to:
            where.append("date(date) <= date(?)")
            params.append(date_to)
        cols = _columns(conn, "runs")
        sport_sql = "sport_type" if "sport_type" in cols else "'run'"
        run_type_sql = "run_type" if "run_type" in cols else "NULL"
        note_sql = "note" if "note" in cols else "NULL"
        sql = f"""
            SELECT id, date, distance AS distance_m, pace, avg_hr,
                   moving_time AS duration_s,
                   ROUND(COALESCE(moving_time,0) / 60.0, 1) AS duration_min,
                   {sport_sql} AS sport_type,
                   {run_type_sql} AS run_type,
                   {note_sql} AS note
            FROM runs
        """
        if where:
            sql += " WHERE " + " AND ".join(where)
        sql += " ORDER BY date(date) DESC LIMIT ?"
        rows = _rows(conn, sql, tuple(params + [limit]))
        for row in rows:
            raw_sport = str(row.get("sport_type") or "").strip().lower()
            if raw_sport in {"running", "lauf", "laufen", "joggen"}:
                raw_sport = "run"
            elif raw_sport in {"bike", "indoor_bike", "indoor bike", "ergometer"}:
                raw_sport = "ergo"
            text = " ".join(str(row.get(key) or "").lower() for key in ("note", "run_type"))
            row["sport_type"] = (
                raw_sport
                if raw_sport in {"run", "ergo", "stair"}
                else "stair"
                if any(token in text for token in ("stair", "stairs", "stairmaster", "stepmill", "etagen"))
                else "ergo"
                if any(token in text for token in ("ergo", "ergometer", "watt", "rpm", "kadenz"))
                else "run"
            )
        return rows
    finally:
        conn.close()


def _create_run_live(body: dict[str, Any]) -> dict[str, Any]:
    date_iso = _parse_datetime(body.get("date") or body.get("started_at") or body.get("start_time"), "date", required=True)
    distance_m = _float_or_none(body.get("distance_m"))
    if distance_m is None:
        distance_km = _float_or_none(body.get("distance_km") or body.get("distance"))
        distance_m = distance_km * 1000.0 if distance_km is not None else None
    if distance_m is None or distance_m <= 0:
        raise ValueError("distance_m or distance_km is required and must be > 0")

    duration_s = _int_or_none(body.get("duration_s") or body.get("moving_time"))
    if duration_s is None:
        duration_min = _float_or_none(body.get("duration_min"))
        duration_s = int(round(duration_min * 60)) if duration_min is not None else None
    if duration_s is None or duration_s <= 0:
        raise ValueError("duration_s or duration_min is required and must be > 0")

    avg_speed = _float_or_none(body.get("avg_speed")) or round(distance_m / duration_s, 3)
    pace = _float_or_none(body.get("pace"))
    if pace is None:
        pace = round(duration_s / max(distance_m / 1000.0, 0.001), 3)
    raw_type = str(body.get("sport_type") or body.get("activity_type") or body.get("run_type") or "").strip().lower()
    sport_type = raw_type if raw_type in {"run", "ergo", "bike", "walk", "row", "swim", "other"} else "run"
    run_type = str(body.get("run_type") or "").strip() or None
    note = str(body.get("note") or body.get("notes") or "").strip() or None
    avg_power = _float_or_none(body.get("avg_power") or body.get("power") or body.get("watts"))
    if avg_power is None and note:
        match = re.search(r"\b(\d+(?:[.,]\d+)?)\s*w(?:att)?\b", note, flags=re.IGNORECASE)
        if match:
            avg_power = _float_or_none(match.group(1).replace(",", "."))

    conn = connections.get_runs_db()
    try:
        if not _table_exists(conn, "runs"):
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS runs (
                    id INTEGER PRIMARY KEY,
                    date TEXT,
                    distance REAL,
                    moving_time INTEGER,
                    avg_speed REAL,
                    avg_hr REAL,
                    max_hr REAL,
                    elevation_gain REAL,
                    pace REAL,
                    sport_type TEXT,
                    run_type TEXT,
                    note TEXT,
                    avg_power REAL
                )
                """
            )
        for col, col_type in (
            ("sport_type", "TEXT"),
            ("run_type", "TEXT"),
            ("note", "TEXT"),
            ("avg_power", "REAL"),
        ):
            if col not in _columns(conn, "runs"):
                conn.execute(f"ALTER TABLE runs ADD COLUMN {col} {col_type}")
        cols = _columns(conn, "runs")
        values: dict[str, Any] = {}
        if "date" in cols:
            values["date"] = date_iso
        if "distance" in cols:
            values["distance"] = distance_m
        if "moving_time" in cols:
            values["moving_time"] = duration_s
        if "avg_speed" in cols:
            values["avg_speed"] = avg_speed
        if "avg_hr" in cols:
            values["avg_hr"] = _float_or_none(body.get("avg_hr"))
        if "max_hr" in cols:
            values["max_hr"] = _float_or_none(body.get("max_hr"))
        if "elevation_gain" in cols:
            values["elevation_gain"] = _float_or_none(body.get("elevation_gain"))
        if "pace" in cols:
            values["pace"] = pace
        if "sport_type" in cols:
            values["sport_type"] = sport_type
        if "run_type" in cols:
            values["run_type"] = run_type
        if "note" in cols:
            values["note"] = note
        if "avg_power" in cols:
            values["avg_power"] = avg_power
        if not values:
            raise ValueError("runs table has no supported columns")
        keys = list(values)
        cur = conn.execute(f"INSERT INTO runs ({', '.join(keys)}) VALUES ({', '.join('?' for _ in keys)})", tuple(values[k] for k in keys))
        conn.commit()
        return {
            "run_id": int(cur.lastrowid),
            "date": date_iso,
            "distance_m": round(distance_m, 1),
            "distance_km": round(distance_m / 1000.0, 3),
            "duration_s": duration_s,
            "duration_min": round(duration_s / 60.0, 1),
            "pace": pace,
            "avg_speed": avg_speed,
            "avg_hr": values.get("avg_hr"),
            "sport_type": sport_type,
            "run_type": run_type,
            "note": note,
            "avg_power": avg_power,
        }
    finally:
        conn.close()


def _create_cardio_session_live(body: dict[str, Any]) -> dict[str, Any]:
    raw_sport = str(
        body.get("sport_type")
        or body.get("sport")
        or body.get("activity_type")
        or body.get("mode")
        or ""
    ).strip().lower()
    sport_aliases = {
        "run": "run",
        "running": "run",
        "lauf": "run",
        "laufen": "run",
        "joggen": "run",
        "ergo": "ergo",
        "ergometer": "ergo",
        "bike": "ergo",
        "indoor_bike": "ergo",
        "indoor bike": "ergo",
        "rad": "ergo",
        "stair": "stair",
        "stairs": "stair",
        "stairmaster": "stair",
        "stair master": "stair",
        "stepmill": "stair",
    }
    sport = sport_aliases.get(raw_sport)
    if not sport:
        text = " ".join(
            str(body.get(k) or "").lower()
            for k in ("raw_text", "ocr_text", "content", "note", "notes", "title", "session_name")
        )
        sport = "stair" if any(token in text for token in ("stair", "stairs", "stairmaster", "stepmill", "etagen")) else "ergo" if any(token in text for token in ("ergo", "ergometer", "watt", "rpm", "kadenz")) else "run"

    duration = (
        body.get("duration")
        or body.get("duration_text")
        or body.get("duration_min")
        or body.get("moving_time")
        or body.get("duration_s")
    )
    if body.get("duration_s") is not None and body.get("duration") is None and body.get("duration_text") is None:
        seconds = _int_or_none(body.get("duration_s"))
        duration = (seconds / 60.0) if seconds is not None else duration

    payload = {
        "sport_type": sport,
        "date": body.get("date") or body.get("date_iso") or body.get("started_at") or body.get("start_time"),
        "duration": duration,
        "distance_km": body.get("distance_km") or body.get("distance"),
        "stair_floors": body.get("stair_floors") or body.get("floors") or body.get("etagen"),
        "pace": body.get("pace") or body.get("avg_pace_sec_per_km"),
        "avg_hr": body.get("avg_hr") or body.get("avg_hr_bpm"),
        "avg_power": body.get("avg_power_w") or body.get("avg_power") or body.get("watts") or body.get("power"),
        "note": body.get("note") or body.get("notes") or body.get("raw_text") or body.get("ocr_text") or body.get("content") or "",
    }
    result = save_cardio_session(payload)
    result.update(
        {
            "sport_type": sport,
            "date": payload["date"],
            "duration": payload["duration"],
            "distance_km": payload["distance_km"],
            "stair_floors": payload["stair_floors"],
            "avg_hr": payload["avg_hr"],
            "avg_power": payload["avg_power"],
            "pace": payload["pace"],
        }
    )
    return result


def _liva_read_query(body: dict[str, Any], *names: str) -> dict[str, Any]:
    query: dict[str, Any] = {}
    for name in names:
        value = body.get(name)
        if value not in (None, ""):
            query[name] = value
    return query


def _read_training_today_card(date_value: Any) -> tuple[dict[str, Any], int]:
    """Canonical, transport-free read path for the current training card."""
    try:
        day_iso = _parse_date(date_value or _today(), "date", required=True)
        return {"ok": True, **_training_today_card_payload(day_iso)}, 200
    except ValueError as exc:
        return {
            "ok": False,
            "error": {"code": "invalid_request", "message": str(exc)},
        }, 400


def _read_training_today_decision_context(date_value: Any) -> tuple[dict[str, Any], int]:
    """Canonical, transport-free read path for today's training decision context."""
    try:
        day_iso = _parse_date(date_value or _today(), "date", required=True)
        payload = _training_decision_context_payload(day_iso)
        payload["context_hash"] = _training_decision_context_hash(payload)
        derived_state = _training_ai_decision_state(day_iso, context=payload)
        payload["existing_decision"] = {
            "status": derived_state.get("status"),
            "decision_id": derived_state.get("decision_id"),
            "saved_context_hash": derived_state.get("saved_context_hash"),
            "current_context_hash": derived_state.get("current_context_hash"),
            "stale_reason": derived_state.get("stale_reason"),
            "stale_reasons": derived_state.get("stale_reasons") or [],
        }
        payload.pop("_latest_session_date", None)
        return {"ok": True, **payload}, 200
    except ValueError as exc:
        return {
            "ok": False,
            "error": {"code": "invalid_request", "message": str(exc)},
        }, 400


def _read_core_training_card(date_value: Any) -> tuple[dict[str, Any], int]:
    """Canonical, transport-free read path for the deprecated CORE card alias."""
    try:
        day_iso = _parse_date(date_value or _today(), "date", required=True)
        card = _training_today_card_payload(day_iso)
        return {
            "ok": True,
            "date": day_iso,
            "available": str(card.get("status") or "") not in {"missing", "not_applicable"},
            "source": "gpt_training_decision",
            "deprecated_alias": True,
            "training_card": card,
        }, 200
    except ValueError as exc:
        return {
            "ok": False,
            "error": {"code": "invalid_date", "message": str(exc)},
        }, 400


def _liva_read_response(mode: str, payload: dict[str, Any], status_code: int):
    if status_code >= 400:
        error = payload.get("error") if isinstance(payload, dict) else None
        if isinstance(error, dict):
            return jsonify(payload), status_code
        code = ((error or {}).get("code") if isinstance(error, dict) else None) or "invalid_request"
        message = ((error or {}).get("message") if isinstance(error, dict) else None) or f"{mode} failed"
        return _error(code, str(message), status_code)
    result = payload.get("result") if "result" in payload else {k: v for k, v in payload.items() if k not in {"data_status", "resolution", "warnings"}}
    response: dict[str, Any] = {"mode": mode, "data_status": payload.get("data_status"), "result": result}
    if payload.get("resolution") is not None:
        response["resolution"] = payload.get("resolution")
    warnings = payload.get("warnings")
    if isinstance(warnings, list) and warnings:
        response["warnings"] = [
            dict(item) if isinstance(item, dict) else str(item)
            for item in warnings
            if isinstance(item, dict) or str(item).strip()
        ]
    return _ok(**response)


def _liva_act_response(domain: str, command: str, payload: dict[str, Any], status_code: int):
    if status_code >= 400:
        error = payload.get("error") if isinstance(payload, dict) else None
        if isinstance(error, dict):
            response: dict[str, Any] = {"ok": False, "error": error}
            if isinstance(payload.get("execution"), dict):
                response["execution"] = payload.get("execution")
            for key in ("accepted_shapes", "received_keys", "command"):
                if key in payload:
                    response[key] = payload.get(key)
            return jsonify(response), status_code
        if isinstance(error, str) and error.strip():
            response = {
                "ok": False,
                "error": {
                    "code": error.strip(),
                    "message": str(payload.get("message") or f"{domain}.{command} failed"),
                },
            }
            if isinstance(payload.get("execution"), dict):
                response["execution"] = payload.get("execution")
            for key in ("workout_id", "exercise_index", "mismatches", "canonical_readback", "accepted_shapes", "received_keys"):
                if key in payload:
                    response[key] = payload.get(key)
            return jsonify(response), status_code
        code = "invalid_request"
        message = f"{domain}.{command} failed"
        return _error(code, str(message), status_code)
    raw_execution = payload.get("execution") if isinstance(payload.get("execution"), dict) else {}
    is_dry_run = bool(payload.get("dry_run")) or str(raw_execution.get("mode") or "") == "dry_run"
    mode = "dry_run" if is_dry_run else (str(raw_execution.get("mode") or "").strip() or "no_change")
    live_state_changed = False if is_dry_run else bool(raw_execution.get("live_state_changed"))
    affected_resources = raw_execution.get("affected_resources") if isinstance(raw_execution.get("affected_resources"), list) else []
    detail = str(raw_execution.get("detail") or "").strip()
    if mode == "dry_run":
        detail = "Preview only. No data changed."
    elif mode == "applied_live" and not detail:
        detail = f"{domain}.{command} executed through the LIVA act facade."
    execution = _execution(mode, live_state_changed, affected_resources, detail or None)
    response: dict[str, Any] = {
        "domain": domain,
        "command": command,
        "execution": execution,
        "result": payload.get("result") if "result" in payload else {k: v for k, v in payload.items() if k not in {"ok", "execution", "command", "warnings"}},
    }
    if domain == "training" and command == "log_gym_session":
        for key in (
            "dry_run",
            "dry_run_supported",
            "parsed_payload",
            "matched_exercises",
            "parsed_exercises",
            "comparison_to_last",
            "will_change",
            "will_not_change",
        ):
            if key in payload:
                response[key] = payload.get(key)
    for key in ("will_change", "will_not_change", "normalized_plan", "received_keys"):
        if key in payload:
            response[key] = payload.get(key)
    for passthrough in ("guest_key", "expires_at"):
        if payload.get(passthrough) not in (None, ""):
            response[passthrough] = payload.get(passthrough)
    for passthrough in ("affected_ids", "visible_in_frontend"):
        if passthrough in payload:
            response[passthrough] = payload.get(passthrough)
    warnings = payload.get("warnings")
    if not warnings:
        preview = payload.get("preview") if isinstance(payload.get("preview"), dict) else {}
        plan = payload.get("plan") if isinstance(payload.get("plan"), dict) else {}
        warnings = preview.get("warnings") or plan.get("warnings")
    if isinstance(warnings, list) and warnings:
        response["warnings"] = [
            dict(item) if isinstance(item, dict) else str(item)
            for item in warnings
            if isinstance(item, dict) or str(item).strip()
        ]
    return _ok(**response)


def _analysis_phase_window(payload: dict[str, Any]) -> tuple[str, str, int]:
    date_to = _parse_date(payload.get("date_to") or payload.get("end") or _today(), "date_to", required=True) or _today()
    date_from = _parse_date(payload.get("date_from") or payload.get("start"), "date_from")
    if not date_from:
        days = _limit(payload.get("days"), 28, 730)
        date_from = _date_plus_days(date_to, -(days - 1))
    start_day = date.fromisoformat(date_from)
    end_day = date.fromisoformat(date_to)
    if end_day < start_day:
        raise ValueError("date_to must be on or after date_from")
    days = (end_day - start_day).days + 1
    if days > 730:
        raise ValueError("analysis phase is limited to 730 days")
    return date_from, date_to, days


def _analysis_phase_source_rows(date_from: str, date_to: str) -> dict[str, Any]:
    # Import lazily: app owns the historical target resolver and the joined
    # recovery snapshot. This keeps the UI and MCP on exactly the same context.
    import app as app_module

    nutrition_rows = app_module._load_nutrition_series(days="all", start_iso=date_from, end_iso=date_to)
    nutrition_conn = connections.get_nutrition_db()
    try:
        settings = app_module._load_nutrition_settings()
        mode_timeline = app_module._load_nutrition_mode_timeline(nutrition_conn, settings)
        plan_timeline = app_module._load_week_template_target_timeline(nutrition_conn)
        for row in nutrition_rows:
            row.update(
                app_module._target_context_for_date(
                    row.get("date_iso"), settings, mode_timeline, plan_timeline, conn=nutrition_conn
                )
            )
    finally:
        nutrition_conn.close()

    sessions = _training_sessions(date_from, date_to, 300, True, True, [])
    recovery_payload = app_module._recovery_payload("all", 28)
    recovery_rows = [
        row for row in (recovery_payload.get("rows") or [])
        if date_from <= str(row.get("date") or "")[:10] <= date_to
    ]
    return {
        "nutrition": sorted(nutrition_rows, key=lambda row: str(row.get("date_iso") or "")),
        "training": sorted(sessions, key=lambda row: str(row.get("date") or "")),
        "recovery": sorted(recovery_rows, key=lambda row: str(row.get("date") or "")),
        "training_truncated": len(sessions) >= 300,
    }


def _analysis_avg(values: list[Any], digits: int = 1) -> float | None:
    parsed = [_float_or_none(value) for value in values]
    clean = [value for value in parsed if value is not None]
    return round(sum(clean) / len(clean), digits) if clean else None


def _analysis_phase_weeks(date_from: str, date_to: str, rows: dict[str, Any]) -> list[dict[str, Any]]:
    buckets: dict[str, dict[str, Any]] = {}

    def bucket(day_iso: str) -> dict[str, Any]:
        day_value = date.fromisoformat(day_iso)
        week_start = (day_value - timedelta(days=day_value.weekday())).isoformat()
        return buckets.setdefault(week_start, {"nutrition": [], "training": [], "recovery": []})

    for row in rows["nutrition"]:
        day_iso = str(row.get("date_iso") or "")[:10]
        if day_iso:
            bucket(day_iso)["nutrition"].append(row)
    for row in rows["training"]:
        day_iso = str(row.get("date") or "")[:10]
        if day_iso:
            bucket(day_iso)["training"].append(row)
    for row in rows["recovery"]:
        day_iso = str(row.get("date") or "")[:10]
        if day_iso:
            bucket(day_iso)["recovery"].append(row)

    weeks = []
    cursor = date.fromisoformat(date_from) - timedelta(days=date.fromisoformat(date_from).weekday())
    final_day = date.fromisoformat(date_to)
    while cursor <= final_day:
        week_start = cursor.isoformat()
        values = buckets.get(week_start, {"nutrition": [], "training": [], "recovery": []})
        nutrition = values["nutrition"]
        training = values["training"]
        recovery = values["recovery"]
        weights = [_float_or_none(row.get("bodyweight_kg")) for row in nutrition]
        weights = [value for value in weights if value is not None]
        exercises = [exercise for session in training for exercise in (session.get("exercises") or [])]
        sets = [item for exercise in exercises for item in (exercise.get("sets") or [])]
        weeks.append(
            {
                "week_start": week_start,
                "week_end": min(cursor + timedelta(days=6), final_day).isoformat(),
                "weight_start": round(weights[0], 2) if weights else None,
                "weight_end": round(weights[-1], 2) if weights else None,
                "weight_change": round(weights[-1] - weights[0], 2) if len(weights) >= 2 else None,
                "nutrition_logged_days": sum(1 for row in nutrition if row.get("calories") is not None),
                "avg_kcal": _analysis_avg([row.get("calories") for row in nutrition], 0),
                "avg_protein_g": _analysis_avg([row.get("protein_g") for row in nutrition], 1),
                "training_sessions": len(training),
                "training_sets": len(sets),
                "unique_exercises": len({str(exercise.get("display_name") or exercise.get("name") or "") for exercise in exercises if exercise.get("name")}),
                "avg_hrv_ms": _analysis_avg([row.get("rmssd") for row in recovery], 1),
                "avg_night_pulse": _analysis_avg([row.get("nightPulse") or row.get("night_pulse") for row in recovery], 1),
                "avg_sleep_h": _analysis_avg([(_float_or_none(row.get("actualSleepMinutes") or row.get("actual_sleep_minutes")) or 0) / 60 if (row.get("actualSleepMinutes") or row.get("actual_sleep_minutes")) is not None else None for row in recovery], 1),
                "sick_days": sum(1 for row in recovery if row.get("flag") == "sick" or row.get("manual_flag") == "sick"),
                "alcohol_days": sum(1 for row in recovery if row.get("flag") == "alcohol" or row.get("manual_flag") == "alcohol"),
            }
        )
        cursor += timedelta(days=7)
    return weeks


def _analysis_phase_changes(weeks: list[dict[str, Any]]) -> list[dict[str, Any]]:
    metrics = ("weight_end", "avg_kcal", "avg_protein_g", "training_sessions", "training_sets", "avg_hrv_ms", "avg_night_pulse", "avg_sleep_h")
    changes = []
    for metric in metrics:
        candidates = []
        for previous, current in zip(weeks, weeks[1:]):
            before = _float_or_none(previous.get(metric)); after = _float_or_none(current.get(metric))
            if before is None or after is None:
                continue
            candidates.append({"metric": metric, "from_week": previous["week_start"], "to_week": current["week_start"], "from": before, "to": after, "delta": round(after - before, 2)})
        changes.extend(sorted(candidates, key=lambda item: abs(item["delta"]), reverse=True)[:2])
    return changes


def _analysis_phase_overview_payload(payload: dict[str, Any]) -> dict[str, Any]:
    import app as app_module

    date_from, date_to, days = _analysis_phase_window(payload)
    rows = _analysis_phase_source_rows(date_from, date_to)
    weeks = _analysis_phase_weeks(date_from, date_to, rows)
    phase_context = app_module._analysis_phase_payload(date.fromisoformat(date_from), date.fromisoformat(date_to), history_days=3650)["selected"]
    result = {
        "range": {"date_from": date_from, "date_to": date_to, "days": days},
        "phase_context": phase_context,
        "coverage": {
            "nutrition_days": len(rows["nutrition"]),
            "weight_days": sum(1 for row in rows["nutrition"] if row.get("bodyweight_kg") is not None),
            "training_sessions": len(rows["training"]),
            "recovery_days": len(rows["recovery"]),
            "training_truncated": rows["training_truncated"],
        },
        "weeks": weeks,
        "notable_week_changes": _analysis_phase_changes(weeks),
        "zoom": {
            "mode": "analysis_phase_detail",
            "focuses": ["days", "training", "exercises", "nutrition", "recovery"],
            "payload_base": {"date_from": date_from, "date_to": date_to},
        },
        "memory_workflow": {
            "recall_before_interpretation": True,
            "recall_tool": "liva_memory_recall",
            "recall_queries": [
                f"Trainings- und Ernaehrungsmuster {date_from} bis {date_to}",
                "persoenliche Reaktion auf Trainingsvolumen Recovery Schlaf Alkohol Krankheit",
            ],
            "save_requires_explicit_user_confirmation": True,
            "save_flow": ["liva_memory_begin", "liva_memory_finish"],
            "route": "living_wiki",
            "source_fields": ["date_range", "metrics", "statement", "exceptions"],
            "single_observation_is_not_durable": True,
        },
        "analysis_rules": [
            "Read training, nutrition, weight and recovery together.",
            "Historical targets are context, not an automatic good-or-bad verdict.",
            "State clear hypotheses when patterns repeat; use detail zoom for concrete confirming and contradicting days.",
        ],
    }
    result["payload_bytes"] = len(json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    return result


def _analysis_page(items: list[Any], *, offset: int, limit: int) -> tuple[list[Any], dict[str, Any]]:
    page = items[offset : offset + limit]
    return page, {"offset": offset, "limit": limit, "returned": len(page), "total": len(items), "has_more": offset + len(page) < len(items), "next_offset": offset + len(page) if offset + len(page) < len(items) else None}


def _analysis_phase_detail_payload(payload: dict[str, Any]) -> dict[str, Any]:
    date_from, date_to, days = _analysis_phase_window(payload)
    focus = str(payload.get("focus") or "days").strip().lower()
    if focus not in {"days", "training", "exercises", "nutrition", "recovery"}:
        raise ValueError("focus must be days, training, exercises, nutrition or recovery")
    offset = max(0, _int_or_none(payload.get("offset")) or 0)
    default_limit = 40 if focus in {"training", "exercises"} else 90
    maximum = 40 if focus == "training" else 20 if focus == "exercises" else 120
    limit = max(1, min(_int_or_none(payload.get("limit")) or default_limit, maximum))
    rows = _analysis_phase_source_rows(date_from, date_to)
    result: dict[str, Any] = {"range": {"date_from": date_from, "date_to": date_to, "days": days}, "focus": focus}

    if focus == "training":
        items, page = _analysis_page(list(reversed(rows["training"])), offset=offset, limit=limit)
        result.update({"sessions": items, "page": page})
    elif focus == "exercises":
        requested = {_norm_compact(name) for name in (payload.get("exercise_names") or []) if str(name).strip()}
        grouped: dict[str, dict[str, Any]] = {}
        for session in rows["training"]:
            for exercise in session.get("exercises") or []:
                label = str(exercise.get("display_name") or exercise.get("name") or "").strip()
                key = _norm_compact(label)
                if not key or (requested and key not in requested and _norm_compact(exercise.get("name")) not in requested):
                    continue
                entry = grouped.setdefault(key, {"name": exercise.get("name"), "display_name": label, "sessions": 0, "set_points": []})
                entry["sessions"] += 1
                for set_row in exercise.get("sets") or []:
                    entry["set_points"].append({"date": session.get("date"), "weight": set_row.get("weight"), "reps": set_row.get("reps"), "rpe": set_row.get("rpe"), "set_number": set_row.get("set_number")})
        exercises = []
        for entry in sorted(grouped.values(), key=lambda item: (-item["sessions"], str(item["display_name"]))):
            points = entry["set_points"]
            exercises.append({**entry, "set_points": points[-120:], "points_truncated": len(points) > 120})
        items, page = _analysis_page(exercises, offset=offset, limit=limit)
        result.update({"exercises": items, "page": page})
    elif focus == "nutrition":
        items, page = _analysis_page(list(reversed(rows["nutrition"])), offset=offset, limit=limit)
        result.update({"days": items, "page": page})
    elif focus == "recovery":
        items, page = _analysis_page(list(reversed(rows["recovery"])), offset=offset, limit=limit)
        result.update({"days": items, "page": page})
    else:
        nutrition_by_day = {str(row.get("date_iso") or "")[:10]: row for row in rows["nutrition"]}
        recovery_by_day = {str(row.get("date") or "")[:10]: row for row in rows["recovery"]}
        training_by_day: dict[str, list[dict[str, Any]]] = {}
        for session in rows["training"]:
            training_by_day.setdefault(str(session.get("date") or "")[:10], []).append(session)
        daily = []
        cursor = date.fromisoformat(date_to)
        first_day = date.fromisoformat(date_from)
        while cursor >= first_day:
            day_iso = cursor.isoformat(); sessions = training_by_day.get(day_iso, [])
            daily.append({"date": day_iso, "nutrition": nutrition_by_day.get(day_iso), "recovery": recovery_by_day.get(day_iso), "training": [{"id": item.get("id"), "day_type": item.get("day_type"), "exercise_count": len(item.get("exercises") or []), "set_count": sum(len(exercise.get("sets") or []) for exercise in item.get("exercises") or [])} for item in sessions]})
            cursor -= timedelta(days=1)
        items, page = _analysis_page(daily, offset=offset, limit=limit)
        result.update({"days": items, "page": page})
    result["payload_bytes"] = len(json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    return result


def _completed_week_range(payload: dict[str, Any]) -> tuple[date, date]:
    if payload.get("week_start") not in (None, ""):
        start_day = date.fromisoformat(_parse_date(payload.get("week_start"), "week_start", required=True) or "")
        if start_day.weekday() != 0:
            raise ValueError("week_start must be a Monday")
        end_day = start_day + timedelta(days=6)
    elif payload.get("week_end") not in (None, ""):
        end_day = date.fromisoformat(_parse_date(payload.get("week_end"), "week_end", required=True) or "")
        if end_day.weekday() != 6:
            raise ValueError("week_end must be a Sunday")
        start_day = end_day - timedelta(days=6)
    else:
        anchor = date.fromisoformat(_parse_date(payload.get("date") or _today(), "date", required=True) or _today())
        start_of_anchor_week = anchor - timedelta(days=anchor.weekday())
        end_day = start_of_anchor_week - timedelta(days=1)
        start_day = end_day - timedelta(days=6)
    today = date.fromisoformat(_today())
    last_completed_sunday = today - timedelta(days=today.weekday() + 1)
    if end_day > last_completed_sunday:
        raise ValueError("weekly feedback requires a fully completed Monday-to-Sunday week")
    return start_day, end_day


def _weekly_exercise_scores(sessions: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    scores: dict[str, dict[str, Any]] = {}
    for session in sessions:
        for exercise in session.get("exercises") or []:
            label = str(exercise.get("display_name") or exercise.get("name") or "").strip()
            key = _norm_compact(label)
            if not key:
                continue
            for set_row in exercise.get("sets") or []:
                weight = _float_or_none(set_row.get("weight"))
                reps = _float_or_none(set_row.get("reps"))
                if reps is None:
                    continue
                score = reps if weight in (None, 0) else float(weight) * (1.0 + float(reps) / 30.0)
                if key not in scores or score > scores[key]["score"]:
                    scores[key] = {"label": label, "score": score}
    return scores


def _weekly_progression(current: list[dict[str, Any]], previous: list[dict[str, Any]]) -> dict[str, Any]:
    current_scores = _weekly_exercise_scores(current)
    previous_scores = _weekly_exercise_scores(previous)
    comparable = sorted(set(current_scores) & set(previous_scores))
    improved = []; stable = []; regressed = []
    for key in comparable:
        before = previous_scores[key]["score"]; after = current_scores[key]["score"]
        delta_pct = ((after - before) / before * 100.0) if before else None
        item = {"exercise": current_scores[key]["label"], "previous": round(before, 2), "current": round(after, 2), "delta_pct": round(delta_pct, 1) if delta_pct is not None else None}
        if delta_pct is not None and delta_pct > 2:
            improved.append(item)
        elif delta_pct is not None and delta_pct < -2:
            regressed.append(item)
        else:
            stable.append(item)
    return {
        "rate_pct": round(len(improved) / len(comparable) * 100.0, 1) if comparable else None,
        "definition": "Anteil vergleichbarer Übungen mit >2 % höherem bestem Wochen-Set-Score als in der Vorwoche",
        "comparable_exercises": len(comparable),
        "improved": improved,
        "stable": stable,
        "regressed": regressed,
        "uncompared_current_exercises": sorted(current_scores[key]["label"] for key in set(current_scores) - set(previous_scores)),
    }


def _weekly_plan_adherence(start_iso: str, end_iso: str, sessions: list[dict[str, Any]]) -> dict[str, Any]:
    planned_days: set[str] = set()
    conn = connections.get_core_db()
    try:
        if _table_exists(conn, "training_ai_decisions"):
            rows = conn.execute(
                """
                SELECT day_iso, session_type, session_name
                FROM training_ai_decisions
                WHERE day_iso BETWEEN ? AND ? AND status IN ('fresh', 'active', 'completed')
                ORDER BY day_iso ASC, id DESC
                """,
                (start_iso, end_iso),
            ).fetchall()
            seen = set()
            for row in rows:
                day_iso = str(row["day_iso"] or "")[:10]
                if not day_iso or day_iso in seen:
                    continue
                seen.add(day_iso)
                session_type = str(row["session_type"] or "").lower()
                session_name = str(row["session_name"] or "").lower()
                if session_type not in {"rest", "none", "off"} and session_name not in {"rest", "pause"}:
                    planned_days.add(day_iso)
    except Exception:
        planned_days = set()
    finally:
        conn.close()
    actual_days = {str(session.get("date") or "")[:10] for session in sessions if session.get("date")}
    completed = sorted(planned_days & actual_days)
    missed = sorted(planned_days - actual_days)
    return {
        "adherence_pct": round(len(completed) / len(planned_days) * 100.0, 1) if planned_days else None,
        "planned_days_recorded": len(planned_days),
        "completed_planned_days": completed,
        "missed_planned_days": missed,
        "actual_training_days": sorted(actual_days),
        "coverage": "historical_saved_decisions" if planned_days else "no_historical_plan_days",
    }


def _weekly_outliers(nutrition: list[dict[str, Any]]) -> list[dict[str, Any]]:
    outliers = []
    for metric, field in (("calories", "calories"), ("protein_g", "protein_g"), ("carbs_g", "carbs_g"), ("fat_g", "fat_g")):
        values = [(str(row.get("date_iso") or "")[:10], _float_or_none(row.get(field))) for row in nutrition]
        values = [(day, value) for day, value in values if day and value is not None]
        if len(values) < 3:
            continue
        mean = sum(value for _, value in values) / len(values)
        variance = sum((value - mean) ** 2 for _, value in values) / len(values)
        std = math.sqrt(variance)
        if std <= 0:
            continue
        for day, value in values:
            deviation = (value - mean) / std
            if abs(deviation) >= 1.5:
                outliers.append({"date": day, "metric": metric, "value": round(value, 1), "weekly_avg": round(mean, 1), "standard_deviations": round(deviation, 1)})
    return sorted(outliers, key=lambda item: abs(item["standard_deviations"]), reverse=True)[:8]


def _weekly_feedback_payload(payload: dict[str, Any]) -> dict[str, Any]:
    import app as app_module

    start_day, end_day = _completed_week_range(payload)
    previous_start = start_day - timedelta(days=7)
    combined = _analysis_phase_source_rows(previous_start.isoformat(), end_day.isoformat())
    current_training = [row for row in combined["training"] if start_day.isoformat() <= str(row.get("date") or "")[:10] <= end_day.isoformat()]
    previous_training = [row for row in combined["training"] if previous_start.isoformat() <= str(row.get("date") or "")[:10] < start_day.isoformat()]
    nutrition = [row for row in combined["nutrition"] if start_day.isoformat() <= str(row.get("date_iso") or "")[:10] <= end_day.isoformat()]
    recovery = [row for row in combined["recovery"] if start_day.isoformat() <= str(row.get("date") or "")[:10] <= end_day.isoformat()]
    logged = [row for row in nutrition if row.get("calories") is not None]
    weights = [(str(row.get("date_iso") or "")[:10], _float_or_none(row.get("bodyweight_kg"))) for row in nutrition]
    weights = [(day, value) for day, value in weights if day and value is not None]
    previous_weights = [_float_or_none(row.get("bodyweight_kg")) for row in combined["nutrition"] if previous_start.isoformat() <= str(row.get("date_iso") or "")[:10] < start_day.isoformat()]
    previous_weights = [value for value in previous_weights if value is not None]
    phase = app_module._analysis_phase_payload(start_day, end_day, history_days=3650)["selected"]
    result = {
        "week": {"start": start_day.isoformat(), "end": end_day.isoformat(), "calendar_week": start_day.isocalendar().week, "complete": True, "includes_sunday": True},
        "progression": _weekly_progression(current_training, previous_training),
        "plan_adherence": _weekly_plan_adherence(start_day.isoformat(), end_day.isoformat(), current_training),
        "nutrition": {
            "logged_days": len(logged),
            "coverage_pct": round(len(logged) / 7 * 100.0, 1),
            "missing_days": [(start_day + timedelta(days=index)).isoformat() for index in range(7) if (start_day + timedelta(days=index)).isoformat() not in {str(row.get("date_iso") or "")[:10] for row in logged}],
            "averages": {"kcal": _analysis_avg([row.get("calories") for row in logged], 0), "protein_g": _analysis_avg([row.get("protein_g") for row in logged], 1), "carbs_g": _analysis_avg([row.get("carbs_g") for row in logged], 1), "fat_g": _analysis_avg([row.get("fat_g") for row in logged], 1)},
            "outliers": _weekly_outliers(logged),
        },
        "weight": {"logged_days": len(weights), "start_kg": round(weights[0][1], 2) if weights else None, "end_kg": round(weights[-1][1], 2) if weights else None, "change_kg": round(weights[-1][1] - weights[0][1], 2) if len(weights) >= 2 else None, "average_kg": _analysis_avg([value for _, value in weights], 2), "previous_week_average_kg": _analysis_avg(previous_weights, 2)},
        "recovery": {"days": len(recovery), "avg_hrv_ms": _analysis_avg([row.get("rmssd") for row in recovery], 1), "avg_night_pulse": _analysis_avg([row.get("nightPulse") or row.get("night_pulse") for row in recovery], 1), "avg_sleep_h": _analysis_avg([(_float_or_none(row.get("actualSleepMinutes") or row.get("actual_sleep_minutes")) or 0) / 60 if (row.get("actualSleepMinutes") or row.get("actual_sleep_minutes")) is not None else None for row in recovery], 1), "flags": [{"date": str(row.get("date") or "")[:10], "flag": row.get("flag") or row.get("manual_flag")} for row in recovery if row.get("flag") or row.get("manual_flag")]},
        "historical_target_context": {key: phase.get(key) for key in ("label", "modes", "sources", "target_min", "target_max", "context_ambiguous")},
        "data_note": "Missing days remain missing; no value is filled with zero.",
    }
    result["payload_bytes"] = len(json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    return result


def _weekly_feedback_for_checkin(date_iso: str) -> dict[str, Any] | None:
    if date.fromisoformat(date_iso).weekday() != 0:
        return None
    return _weekly_feedback_payload({"date": date_iso})


def _dispatch_liva_read(body: dict[str, Any]) -> tuple[dict[str, Any], int]:
    mode = str(body.get("mode") or "").strip()
    payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
    if mode == "capabilities":
        return {"ok": True, "data_status": "current", "result": _liva_coach_capabilities()}, 200
    if mode == "analysis_phase_overview":
        try:
            return {"ok": True, "data_status": "ok", "result": _analysis_phase_overview_payload({**payload, **{key: body[key] for key in ("date_from", "date_to", "start", "end", "days") if body.get(key) not in (None, "")}})}, 200
        except ValueError as exc:
            return {"ok": False, "error": {"code": "invalid_request", "message": str(exc)}}, 400
    if mode == "analysis_phase_detail":
        try:
            return {"ok": True, "data_status": "ok", "result": _analysis_phase_detail_payload({**payload, **{key: body[key] for key in ("date_from", "date_to", "start", "end", "days", "focus", "limit", "offset", "exercise_names") if body.get(key) not in (None, "")}})}, 200
        except ValueError as exc:
            return {"ok": False, "error": {"code": "invalid_request", "message": str(exc)}}, 400
    if mode == "weekly_feedback":
        try:
            forwarded = {**payload, **{key: body[key] for key in ("date", "week_start", "week_end") if body.get(key) not in (None, "")}}
            return {"ok": True, "data_status": "ok", "result": _weekly_feedback_payload(forwarded)}, 200
        except ValueError as exc:
            return {"ok": False, "error": {"code": "invalid_request", "message": str(exc)}}, 400
    if mode == "daily_snapshot":
        return _call_actions_view(liva_today, method="GET")
    if mode == "daily_context":
        return _call_actions_view(daily_context, method="GET", query=_liva_read_query(body, "date", "calendar_id"))
    if mode == "state":
        return _call_actions_view(liva_state, method="GET")
    if mode == "context":
        return _call_actions_view(liva_context, method="GET")
    if mode == "core_state":
        return _call_actions_view(core_state, method="GET")
    if mode == "core_board":
        day_iso = _parse_date(body.get("date") or payload.get("date") or _today(), "date", required=True)
        board = get_persisted_core_daily_board(day_iso, create_if_missing=False)
        if isinstance(board, dict) and board:
            return {"ok": True, "date": day_iso, "available": True, "board": board}, 200
        return {"ok": True, "date": day_iso, "available": False, "status": "missing", "board": None, "message": "Noch kein CORE Board für diesen Tag."}, 200
    if mode == "core_morning_context":
        return _call_actions_view(core_morning_context, method="GET", query=_liva_read_query(body, "date"))
    if mode == "core_training_card":
        return _read_core_training_card(body.get("date") or payload.get("date"))
    if mode == "training_state":
        return _call_actions_view(training_state, method="GET")
    if mode == "training_deep_dive":
        workout_id = body.get("workout_id") if body.get("workout_id") not in (None, "") else payload.get("workout_id")
        if workout_id not in (None, ""):
            return {
                "ok": False,
                "error": {
                    "code": "unsupported_scope",
                    "message": "training_deep_dive is range-scoped; use training_workout_coach_view for workout_id",
                },
                "workout_id": workout_id,
                "use_mode": "training_workout_coach_view",
            }, 400
        query = _liva_read_query(body, "days", "date_from", "date_to", "focus", "muscle_group", "canonical_id")
        for key in ("days", "date_from", "date_to", "focus", "muscle_group", "canonical_id"):
            if payload.get(key) not in (None, "") and key not in query:
                query[key] = payload.get(key)
        return _call_actions_view(training_deep_dive, method="GET", query=query)
    if mode == "training_workout_coach_view":
        workout_id = _int_or_none(body.get("workout_id") if body.get("workout_id") not in (None, "") else payload.get("workout_id"))
        if workout_id is None:
            return {
                "ok": False,
                "error": {
                    "code": "invalid_detail",
                    "message": "workout_id is required for training_workout_coach_view",
                },
                "expected": ["workout_id"],
                "received": body.get("workout_id") if body.get("workout_id") not in (None, "") else payload.get("workout_id"),
            }, 400
        try:
            return _workout_coach_view(workout_id), 200
        except ValueError:
            return {"ok": False, "error": {"code": "not_found", "message": "Workout not found."}}, 404
    if mode == "training_exercises":
        query = str(body.get("query") or payload.get("query") or payload.get("q") or "").strip()
