        if mode == "endurance_session":
            session_id = str(body.get("session_id") or payload.get("session_id") or "")
            requested_date = str(body.get("date") or payload.get("date") or "")
            session = next((item for item in plan["sessions"] if item["id"] == session_id), None) if session_id else next((item for item in plan["sessions"] if item["scheduled_date"] == requested_date), None)
            if session:
                return {"ok": True, "data_status": "fresh", "session": {**session, "provenance": "liva_endurance_plan"}, "available": True}, 200
            if not requested_date and session_id.startswith("intervals-date:"):
                requested_date = session_id.removeprefix("intervals-date:")
            elif not requested_date and session_id.startswith("intervals:"):
                candidate_date = session_id.split(":", 2)[1]
                if re.fullmatch(r"\d{4}-\d{2}-\d{2}", candidate_date):
                    requested_date = candidate_date
            if requested_date:
                external = build_endurance_core_context(requested_date, refresh=False)
                if external.get("has_workout"):
                    original = external.get("original") or {}
                    external_id = original.get("id") or original.get("event_id") or external.get("intervals_event_id")
                    readable_id = session_id or (f"intervals:{requested_date}:{external_id}" if external_id not in (None, "") else f"intervals-date:{requested_date}")
                    return {"ok": True, "data_status": "external", "available": True, "session": {"id": readable_id, "planned_session_id": None, "external_event_id": external_id, "date": requested_date, "title": original.get("label") or external.get("original_label"), "provenance": "external_intervals", "provider": "intervals.icu", "detail": external}}, 200
            return {"ok": True, "data_status": "missing", "session": None, "available": False}, 404
