@actions_v2_api.get("/core/morning-context")
@require_ai_read
def core_morning_context():
    try:
        day_iso = _parse_date(request.args.get("date") or _today(), "date", required=True)
        payload = build_core_morning_context(day_iso)
        morning_context = payload.get("morning_context") or {}
        resolved_session = _plan_session_for_date(day_iso)
        # The CORE helper still carries a fixed-week projection internally.
        # Expose the authoritative rolling resolution at this API boundary.
        if resolved_session.get("available"):
            resolved_name = resolved_session.get("name")
            morning_context["planned_session_label"] = resolved_name
            morning_context["recommended_session_label"] = resolved_name
            morning_context["must_use_session_label"] = resolved_name
            morning_context["planned_session_source"] = "rolling_resolver"
            training_context = morning_context.get("training_context") if isinstance(morning_context.get("training_context"), dict) else {}
            training_context["today_plan"] = resolved_name
            morning_context["training_context"] = training_context
            morning_context["resolved_planned_session"] = _compact_planned_session_for_gpt(resolved_session)
        recovery = _recovery_summary()
        compact_recovery = _compact_recovery_summary_payload(recovery)
        morning_context["recovery_summary"] = compact_recovery
        flags = compact_recovery.get("flags") if isinstance(compact_recovery.get("flags"), dict) else {}
        if flags.get("sickness"):
            snapshot = morning_context.get("recovery_snapshot")
            if isinstance(snapshot, dict):
                snapshot["status"] = "sick"
            suggested = morning_context.get("suggested_payload_skeleton")
            if isinstance(suggested, dict):
                suggested["decision_intent"] = "recovery_only"
                suggested["human_headline"] = "Krankheitsflag aktiv: Training nur sehr leicht oder verschieben."
        elif flags.get("alcohol"):
            snapshot = morning_context.get("recovery_snapshot")
            if isinstance(snapshot, dict) and str(snapshot.get("status") or "").strip().lower() == "usable":
                snapshot["status"] = "flagged"
            suggested = morning_context.get("suggested_payload_skeleton")
            if isinstance(suggested, dict) and str(suggested.get("decision_intent") or "").strip().lower() == "train_controlled":
                suggested["decision_intent"] = "reduce_volume"
                suggested["human_headline"] = "Alkohol-Flag aktiv: Training konservativ halten oder verschieben."
        return _ok(date=day_iso, morning_context=morning_context)
    except ValueError as exc:
        return _error("invalid_date", str(exc))


