def core_control():
    body = _body()
    try:
        command = _command_guard(body, CORE_COMMANDS, "/core/control")
        result = _apply_core_override_live(command, body)
        _record_command(connections.get_core_db, "core", command, body, result)
        live_changed = command == "set_override" or int(result.get("deleted_rows") or 0) > 0
        return _ok(
            command=command,
            execution=_execution(
                "applied_live",
                live_changed,
                ["training.core_override_choices", "core.actions_v2_state", "core.actions_v2_command_log"],
                "CORE override is written to the canonical training core_override_choices table and mirrored into V2 state.",
            ),
            result=result,
        )
    except ValueError as exc:
        return _error("invalid_command", str(exc))


