@actions_v2_api.post("/training/data")
@require_ai_read
def training_data():
    body = _body()
    try:
        scope = str(body.get("scope") or "").strip()
        if scope not in READ_SCOPES:
            return _error("invalid_scope", "scope must be sessions, plan_days or recent_summary")
        if scope == "sessions":
            exercise_names = _list(body.get("exercise_names"), "exercise_names")
            sessions = _training_sessions(
                _parse_date(body.get("date_from"), "date_from"),
                _parse_date(body.get("date_to"), "date_to"),
                _limit(body.get("limit") or body.get("max_results"), 100, 300),
                bool(body.get("include_exercises", True)),
                bool(body.get("include_sets", False)),
                exercise_names,
            )
            resolution = []
            if exercise_names:
                conn = connections.get_training_db()
                try:
                    resolution = _resolve_exercises(exercise_names, conn)
                finally:
                    conn.close()
            return _ok(scope=scope, resolution=resolution, data_status="ok" if sessions else "no_rows_in_range", sessions=sessions)
        if scope == "plan_days":
            core = _plan_core(_active_plan())
            return _ok(scope=scope, data_status="ok" if core["available"] else core["reason"], plan_days=core["days"])
        return _ok(scope=scope, recent_summary=_training_state_payload()["recent_sessions_summary"])
    except ValueError as exc:
        return _error("invalid_request", str(exc))


