@actions_v2_api.post("/training/adjust")
@require_ai_write
def training_adjust():
    body = _body()
    try:
        command = _command_guard(body, TRAINING_ADJUST_COMMANDS, "/training/adjust")
        result = {k: v for k, v in body.items() if k != "command"}
        if command == "log_gym_session":
            result = _log_gym_session_live(body)
            dry_run = bool(result.get("dry_run"))
            _record_command(connections.get_training_db, "training", command, body, result)
            payload = action_success(
                "log_training_session",
                dry_run=dry_run,
                parsed_payload={k: result.get(k) for k in ("date_iso", "session_name", "exercise_count", "set_count", "parse_warnings")},
                after={k: result.get(k) for k in ("workout_id", "date_iso", "session_name")},
                warnings=list(result.get("parse_warnings") or []),
                will_change=["training_log"],
                will_not_change=["training_plan"],
                command=command,
                execution=_execution(
                    "dry_run" if dry_run else "applied_live",
                    not dry_run,
                    ["training_log"],
                    "Parsed and wrote a canonical gym workout." if not dry_run else "Parsed only; no workout was written.",
                ),
                result=result,
                ids={"workout_id": result.get("workout_id")} if result.get("workout_id") is not None else {},
                session={"workout_id": result.get("workout_id"), "session_name": result.get("session_name"), "date": result.get("date_iso")},
                parsed_exercises=[
                    {
                        "exercise_index": idx,
                        "name": ex.get("name"),
                        "variation": ex.get("variation"),
                        "canonical_id": ex.get("exercise_key"),
                        "sets": ex.get("sets") or [],
                    }
                    for idx, ex in enumerate(result.get("exercises") or [])
                ],
                matched_exercises=[
                    {
                        "raw": ex.get("source_name") or ex.get("name"),
                        "canonical_id": ex.get("exercise_key"),
                        "name": ex.get("name"),
                        "variation": ex.get("variation"),
                        "confidence": (ex.get("resolution") or {}).get("confidence", 0.98 if ex.get("exercise_key") else 0.6),
                        "exercise_index": idx,
                        "resolution_basis": (ex.get("resolution") or {}).get("resolution_basis"),
                        "plan_match": bool((ex.get("resolution") or {}).get("plan_match")),
                        "planned_variation": (ex.get("resolution") or {}).get("planned_variation"),
                        "chosen_variation": (ex.get("resolution") or {}).get("chosen_variation") or ex.get("variation"),
                        "alternatives": (ex.get("resolution") or {}).get("alternatives") or [],
                    }
                    for idx, ex in enumerate(result.get("exercises") or [])
                ],
                comparison_to_last=result.get("progress") if result.get("workout_id") and not dry_run else {"available": False, "reason": "dry_run_no_previous_lookup"},
            )
            return jsonify(payload)
        if command in {"add_exercise", "remove_exercise", "reorder_exercise"}:
            dry_run = _bool_value(body.get("dry_run"), default=False)
            detail = get_active_training_plan_detail()
            plan_id = _int_or_none(detail.get("plan_id"))
            if plan_id is None:
                return _error("no_active_gym_plan", "No active gym plan is available.")
            day = str(body.get("day") or body.get("weekday") or "").strip()
            if not day:
                return _error("invalid_request", "day is required")
            day_index = next(
                (
                    index
                    for index, item in enumerate(detail.get("days") or [])
                    if any(_norm_compact(value) == _norm_compact(day) for value in (item.get("day_id"), item.get("label"), item.get("title")) if value not in (None, ""))
                ),
                None,
            )
            if day_index is None:
                return _error("plan_day_not_found", "plan_day_not_found")
            workout_index = _int_or_none(body.get("workout_index")) or 0
            workouts = (detail.get("days") or [])[day_index].get("workouts") or []
            if workout_index < 0 or workout_index >= len(workouts):
                return _error("plan_workout_not_found", "workout_index does not exist for the requested day")
            if command == "add_exercise":
                new_exercise = body.get("new_exercise") if isinstance(body.get("new_exercise"), dict) else {}
                if not new_exercise and str(body.get("new_exercise") or body.get("exercise") or "").strip():
                    new_exercise = {"name": str(body.get("new_exercise") or body.get("exercise")).strip()}
                if not str(new_exercise.get("name") or "").strip():
                    return _error("invalid_request", "new_exercise.name is required")
                operation = {"op": "add_exercise", "target": {"day_index": day_index, "workout_index": workout_index, "position": body.get("position")}, **new_exercise}
            else:
                exercise = str(body.get("exercise") or body.get("old_exercise") or "").strip()
                if not exercise:
                    return _error("invalid_request", "exercise is required")
                match, _identity = _resolve_training_plan_exercise_match(detail, {"match": {"day": day, "exercise": exercise, "variation": body.get("variation")}})
                if not match:
                    return _error("plan_exercise_not_found", "plan_exercise_not_found")
                if command == "remove_exercise":
                    operation = {"op": "delete_exercise", "match": {"exercise_path": match["exercise_path"]}}
                else:
                    position = _int_or_none(body.get("position") if body.get("position") is not None else body.get("index"))
                    if position is None or position < 0:
                        return _error("invalid_request", "position is required and must be zero or greater")
                    operation = {"op": "move_exercise", "match": {"exercise_path": match["exercise_path"]}, "target": {"day_index": day_index, "workout_index": workout_index, "exercise_index": position}}
            result = _patch_training_plan({"plan_id": plan_id, "operations": [operation]}, dry_run=dry_run)
            if result.get("ok") is False:
                return jsonify({"ok": False, "command": command, "execution": _execution("dry_run" if dry_run else "no_change", False, [], "Active-plan mutation failed validation."), **result}), 400
            affected_resources = result.pop("_affected_resources", ["training_plan"])
            _record_command(connections.get_plans_db, "training_plan", command, body, result)
            return _ok(command=command, execution=_execution("dry_run" if dry_run else "applied_live", not dry_run and bool(result.get("changed")), affected_resources, "Validated active-plan mutation without writing." if dry_run else "Applied active-plan mutation live."), result=result)
        if command in {"change_sets", "change_rep_range", "change_rpe", "change_variation", "replace_exercise", "update_exercise_target"}:
            dry_run = _bool_value(body.get("dry_run"), default=False)
            day = str(body.get("day") or "").strip()
            exercise = str(body.get("exercise") or body.get("old_exercise") or "").strip()
            if not day:
                return _error("invalid_request", "day is required")
            if not exercise:
                return _error("invalid_request", "exercise is required")
            try:
                result = _update_active_plan_exercise(day, exercise, body, command=command, dry_run=dry_run)
            except ValueError as exc:
                msg = str(exc)
                if msg in {"plan_day_not_found", "plan_exercise_not_found", "plan_exercise_ambiguous_use_session_label_or_key"}:
                    return _error(msg, msg, 400)
                if msg == "variation or new_variation is required":
                    return _error("invalid_request", msg, 400)
                raise
            if not dry_run:
                _record_command(connections.get_training_db, "training", command, body, result)
            changed = bool(result.get("changed", True))
            return _ok(
                command=command,
                execution=_execution(
                    "dry_run" if dry_run else "applied_live" if changed else "no_change",
                    changed and not dry_run,
                    [] if dry_run else ["plans.gym_plans", "training.actions_v2_command_log"] if changed else ["training.actions_v2_command_log"],
                    "Validated active gym plan mutation without writing." if dry_run else "Active gym plan was updated live." if changed else "Requested plan mutation did not change the active gym plan.",
                ),
                result=result,
            )
        _record_command(connections.get_training_db, "training", command, body, result)
        return _ok(command=command, execution=_execution("logged_only", False, ["training.actions_v2_command_log"], "Command was recorded, but this adjust variant is not live yet."), result=result)
    except ValueError as exc:
        return _error("invalid_command", str(exc))


