@actions_v2_api.get("/training/deep-dive")
@require_ai_read
def training_deep_dive():
    requested_days = request.args.get("days")
    days = _limit(requested_days, 545, 730)
    date_to = _parse_date(request.args.get("date_to") or _today(), "date_to", required=True) or _today()
    date_from = _parse_date(request.args.get("date_from"), "date_from") if request.args.get("date_from") not in (None, "") else None
    if not date_from:
        date_from = _date_plus_days(date_to, -(days - 1))
    elif requested_days in (None, ""):
        # Explicit date bounds are authoritative. Do not retain the 545-day
        # default in the response or in weekly averages.
        days = (date.fromisoformat(date_to) - date.fromisoformat(date_from)).days + 1
    focus = str(request.args.get("focus") or "overview").strip().lower()
    if focus not in {"overview", "muscle_volume", "exercise_progression", "stagnation", "best_phases", "weak_points", "all"}:
        return validation_error("focus", "Invalid training deep-dive focus.", expected=["overview", "muscle_volume", "exercise_progression", "stagnation", "best_phases", "weak_points", "all"], received=focus, example_valid_call={"days": 180, "focus": "overview"})
    muscle_group = _text_or_none(request.args.get("muscle_group"))
    canonical_id = _text_or_none(request.args.get("canonical_id"))
    payload = _training_deep_dive(date_from, date_to, days=days, focus=focus, muscle_group=muscle_group, canonical_id=canonical_id)
    return jsonify(payload)


@actions_v2_api.post("/training/edit-logged-workout-exercise")
@require_ai_write
def edit_logged_workout_exercise():
    body = _body()
    workout_id = _int_or_none(body.get("workout_id"))
    exercise_index = _int_or_none(body.get("exercise_index"))
    dry_run = _bool_value(body.get("dry_run"), default=False)
    if workout_id is None or exercise_index is None:
        return action_error("invalid_detail", "workout_id and exercise_index are required.", expected=["workout_id", "exercise_index"], received={"workout_id": body.get("workout_id"), "exercise_index": body.get("exercise_index")}, example_valid_call={"workout_id": 284, "exercise_index": 2, "new_variation": "KH"})
    detail = _load_workout_detail(workout_id)
    if not detail or exercise_index < 0 or exercise_index >= len(detail.get("exercises") or []):
        return action_error("not_found", "Workout or exercise_index not found.", status=404)
    exercise = detail["exercises"][exercise_index]
    notes_supplied, authored_notes = _requested_logged_exercise_notes(body)
    identity_supplied = any(body.get(key) not in (None, "") for key in ("new_name", "new_variation", "canonical_id"))
    if not identity_supplied and not notes_supplied:
        return action_error(
            "invalid_detail",
            "At least one editable exercise field is required.",
            expected=["new_name", "new_variation", "canonical_id", "notes"],
            received=sorted(body.keys()),
            example_valid_call={"workout_id": workout_id, "exercise_index": exercise_index, "notes": "Ellbogen höher führen"},
        )
    conn = connections.get_training_db()
    before = {key: exercise.get(key) for key in ("name", "variation", "canonical_id", "notes")}
    if identity_supplied:
        after, resolution, warnings = _resolve_edit_logged_exercise_target(str(exercise.get("name") or ""), str(exercise.get("variation") or ""), body, conn)
    else:
        after = {key: exercise.get(key) for key in ("name", "variation", "canonical_id")}
        resolution = {
            "requested_name": exercise.get("name"),
            "requested_variation": exercise.get("variation"),
            "resolved_canonical_id": exercise.get("canonical_id"),
            "confidence": 1.0,
            "status": "unchanged",
        }
        warnings = []
    expected_canonical_notes = merge_exercise_notes(authored_notes, exercise.get("sets") or []) if notes_supplied else str(exercise.get("notes") or "").strip()
    after["notes"] = expected_canonical_notes
    if not dry_run and not after.get("canonical_id"):
        conn.close()
        return action_error(
            "invalid_detail",
            "canonical_id could not be resolved for the requested name/variation.",
            expected=["resolvable name/variation pair", "explicit canonical_id"],
            received={"new_name": body.get("new_name"), "new_variation": body.get("new_variation"), "canonical_id": body.get("canonical_id")},
            example_valid_call={"workout_id": workout_id, "exercise_index": exercise_index, "new_name": before.get("name"), "new_variation": before.get("variation"), "canonical_id": before.get("canonical_id")},
            resolution=resolution,
            warnings=warnings,
        )
    if not dry_run:
        try:
            if notes_supplied:
                if "notes" not in _columns(conn, "exercises"):
                    conn.execute("ALTER TABLE exercises ADD COLUMN notes TEXT NOT NULL DEFAULT ''")
                conn.execute(
                    "UPDATE exercises SET name=?, variation=?, device=COALESCE(device, ?), notes=? WHERE id=?",
                    (after["name"], after["variation"], after["variation"], authored_notes, exercise.get("exercise_log_id")),
                )
            else:
                conn.execute("UPDATE exercises SET name=?, variation=?, device=COALESCE(device, ?) WHERE id=?", (after["name"], after["variation"], after["variation"], exercise.get("exercise_log_id")))
            conn.commit()
        finally:
            conn.close()
        refresh = _refresh_training_after_live_write(workout_id)
        readback_detail = _load_workout_detail(workout_id)
        readback_exercise = ((readback_detail or {}).get("exercises") or [None] * (exercise_index + 1))[exercise_index]
        canonical_readback = (
            {key: readback_exercise.get(key) for key in ("name", "variation", "canonical_id", "notes")}
            if isinstance(readback_exercise, dict)
            else None
        )
        mismatches: list[dict[str, Any]] = []
        # name/variation and notes are canonical exercise-row fields. canonical_id
        # is a resolver output (not a persisted string column on historical rows),
        # so the readback may legitimately derive a more specific key.
        for key in ("name", "variation"):
            if (canonical_readback or {}).get(key) != after.get(key):
                mismatches.append({"field": key, "expected": after.get(key), "actual": (canonical_readback or {}).get(key)})
        if notes_supplied and (canonical_readback or {}).get("notes") != expected_canonical_notes:
            mismatches.append({"field": "notes", "expected": expected_canonical_notes, "actual": (canonical_readback or {}).get("notes")})
        if mismatches:
            return action_error(
                "write_verification_failed",
                "Logged exercise was written, but canonical readback did not match the requested after-state.",
                status=500,
                workout_id=workout_id,
                exercise_index=exercise_index,
                mismatches=mismatches,
                canonical_readback=canonical_readback,
                execution=_execution("write", True, ["training_log"], "Write committed, but canonical verification failed."),
            )
        after = canonical_readback
        progress_conn = connections.get_training_db()
        try:
            progress = progress_payload_for_gpt(compute_session_progress(progress_conn, workout_id))
        finally:
            progress_conn.close()
    else:
        conn.close()
        refresh = None
        progress = None
    return jsonify(action_success("edit_logged_workout_exercise", dry_run=dry_run, parsed_payload={"workout_id": workout_id, "exercise_index": exercise_index, "notes_supplied": notes_supplied}, before=before, after=after, warnings=warnings, ids={"workout_id": workout_id, "exercise_index": exercise_index}, resolution=resolution, canonical_readback=None if dry_run else after, progress=progress, post_write_refresh=refresh, will_change=["training_log"], will_not_change=["training_plan"], execution=_execution("dry_run" if dry_run else "write", not dry_run, ["training_log"], "Previewed logged exercise edit." if dry_run else "Updated and canonically verified logged exercise.")))


@actions_v2_api.post("/training/edit-logged-set")
@require_ai_write
def edit_logged_set():
    body = _body()
    workout_id = _int_or_none(body.get("workout_id"))
    exercise_index = _int_or_none(body.get("exercise_index"))
    set_index = _int_or_none(body.get("set_index"))
    dry_run = _bool_value(body.get("dry_run"), default=False)
    if None in {workout_id, exercise_index, set_index}:
        return action_error("invalid_detail", "workout_id, exercise_index and set_index are required.", expected=["workout_id", "exercise_index", "set_index"], received={"workout_id": body.get("workout_id"), "exercise_index": body.get("exercise_index"), "set_index": body.get("set_index")}, example_valid_call={"workout_id": 284, "exercise_index": 2, "set_index": 1, "weight": 27.5, "reps": 4, "rpe": 8})
    detail = _load_workout_detail(workout_id)
    if not detail or exercise_index < 0 or exercise_index >= len(detail.get("exercises") or []):
        return action_error("not_found", "Workout or exercise_index not found.", status=404)
    exercise = detail["exercises"][exercise_index]
    if set_index < 0 or set_index >= len(exercise.get("sets") or []):
        return action_error("not_found", "set_index not found.", status=404)
    set_row = exercise["sets"][set_index]
    before = {key: set_row.get(key) for key in ("weight", "reps", "rpe")}
    after = {
        "weight": _float_or_none(body.get("weight")) if body.get("weight") is not None else set_row.get("weight"),
        "reps": _int_or_none(body.get("reps")) if body.get("reps") is not None else set_row.get("reps"),
        "rpe": _float_or_none(body.get("rpe")) if body.get("rpe") is not None else set_row.get("rpe"),
    }
    if not dry_run:
        conn = connections.get_training_db()
        try:
            conn.execute("UPDATE sets SET weight=?, reps=?, rpe=? WHERE id=?", (after["weight"], after["reps"], after["rpe"], set_row.get("set_log_id")))
            conn.commit()
        finally:
            conn.close()
        refresh = _refresh_training_after_live_write(workout_id)
        progress_conn = connections.get_training_db()
        try:
            progress = progress_payload_for_gpt(compute_session_progress(progress_conn, workout_id))
        finally:
            progress_conn.close()
    else:
        refresh = None
        progress = None
    return jsonify(action_success("edit_logged_set", dry_run=dry_run, parsed_payload={"workout_id": workout_id, "exercise_index": exercise_index, "set_index": set_index}, before=before, after=after, ids={"workout_id": workout_id, "exercise_index": exercise_index, "set_index": set_index}, progress=progress, post_write_refresh=refresh, will_change=["training_log"], will_not_change=["training_plan"], execution=_execution("dry_run" if dry_run else "write", not dry_run, ["training_log"], "Previewed logged set edit." if dry_run else "Updated logged set in training log.")))


def _delete_logged_workout_action(body: dict[str, Any]) -> tuple[dict[str, Any], int]:
    workout_id = _int_or_none(body.get("workout_id") or body.get("id"))
    dry_run = _bool_value(body.get("dry_run"), default=False)
    if workout_id is None:
        return {"ok": False, "error": {"code": "invalid_detail", "message": "workout_id or id is required"}}, 400
    conn = connections.get_training_db()
    try:
        workout = conn.execute("SELECT id, date_iso, name FROM workouts WHERE id=?", (workout_id,)).fetchone()
        if not workout:
            return {"ok": False, "error": {"code": "not_found", "message": "Workout not found."}}, 404
        exercise_count = int(conn.execute("SELECT COUNT(*) AS c FROM exercises WHERE workout_id=?", (workout_id,)).fetchone()["c"] or 0)
        set_count = int(conn.execute("SELECT COUNT(*) AS c FROM sets WHERE workout_id=?", (workout_id,)).fetchone()["c"] or 0)
        before = {"workout_id": workout_id, "date": workout["date_iso"], "session_name": workout["name"], "exercise_count": exercise_count, "set_count": set_count}
        if not dry_run:
            conn.execute("BEGIN")
            for table in ("training_pr_notice", "plan_checks"):
                if _table_exists(conn, table):
                    conn.execute(f"DELETE FROM {table} WHERE workout_id=?", (workout_id,))
            conn.execute("DELETE FROM sets WHERE workout_id=?", (workout_id,))
            conn.execute("DELETE FROM exercises WHERE workout_id=?", (workout_id,))
            deleted = int(conn.execute("DELETE FROM workouts WHERE id=?", (workout_id,)).rowcount or 0)
            conn.commit()
            refresh = _refresh_training_after_live_write(workout_id)
        else:
            deleted = 0
            refresh = None
        return action_success(
            "delete_logged_workout",
            dry_run=dry_run,
            parsed_payload={"workout_id": workout_id},
            before=before,
            after={} if not dry_run else before,
            ids={"workout_id": workout_id},
            post_write_refresh=refresh,
            will_change=["training_log"],
            will_not_change=["training_plan"],
            execution=_execution("dry_run" if dry_run else "applied_live", not dry_run and deleted > 0, ["training_log"], "Previewed logged workout deletion." if dry_run else "Deleted logged workout and dependent exercises/sets."),
        ), 200
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


@actions_v2_api.get("/training/plan-state")
@require_ai_read
def training_plan_state():
    requested_plan_id = _int_or_none(request.args.get("plan_id") or request.args.get("id"))
    plan = _load_training_plan_by_id(requested_plan_id) if requested_plan_id is not None else _active_plan()
    if requested_plan_id is not None and not plan:
        return _error("plan_not_found", "Requested plan not found.", 404)
    detail = str(request.args.get("detail") or "compact").strip().lower()
    core = _plan_core(plan)
    if requested_plan_id is not None and core.get("id") != requested_plan_id:
        return _error("plan_selection_mismatch", "Requested plan_id did not match the returned plan.", 500)
    if detail == "full":
        core["detail"] = "full"
        return _ok(plan=core)
    if detail == "day":
        day = str(request.args.get("day") or "").strip()
        if not day:
            return _error("invalid_request", "day is required for detail=day")
        try:
            return _ok(plan=_training_plan_day_payload(core, day))
        except ValueError as exc:
            return _error(str(exc), str(exc), 400)
    if detail == "exercise":
        day = str(request.args.get("day") or "").strip()
        exercise = str(request.args.get("exercise") or "").strip()
        if not day:
            return _error("invalid_request", "day is required for detail=exercise")
        if not exercise:
            return _error("invalid_request", "exercise is required for detail=exercise")
        try:
            return _ok(plan=_training_plan_exercise_payload(core, day, exercise))
        except ValueError as exc:
            return _error(str(exc), str(exc), 400)
    return _ok(plan=_compact_plan_core(core))


