@actions_v2_api.post("/recovery/data")
@require_ai_read
def recovery_data():
    body = _body()
    try:
        rows = _latest_hrv_rows(_limit(body.get("limit") or body.get("max_results"), 200, 1000))
        date_from = _parse_date(body.get("date_from"), "date_from")
        date_to = _parse_date(body.get("date_to"), "date_to")
        days = _int_or_none(body.get("days"))
        if not date_from and days is not None and days > 0:
            anchor_date = date.fromisoformat(date_to or _today())
            date_to = anchor_date.isoformat()
            date_from = (anchor_date - timedelta(days=max(1, days) - 1)).isoformat()
        if date_from:
            rows = [row for row in rows if str(row.get("date") or "") >= date_from]
        if date_to:
            rows = [row for row in rows if str(row.get("date") or "") <= date_to]
        annotations = _recovery_annotations(date_from, date_to)
        day_flags = _recovery_day_flags(date_from, date_to)
        polar_rows = _latest_polar_recovery_rows()
        polar_sleep = polar_rows.get("sleep") or {}
        polar_nightly = polar_rows.get("nightly") or {}
        polar_continuous = polar_rows.get("continuous") or {}
        by_date = {str(row.get("date") or ""): row for row in rows if row.get("date")}
        for candidate_date in {str(polar_sleep.get("date") or ""), str(polar_nightly.get("date") or ""), str(polar_continuous.get("date") or ""), *day_flags.keys()}:
            if not candidate_date:
                continue
            if date_from and candidate_date < date_from:
                continue
            if date_to and candidate_date > date_to:
                continue
            by_date.setdefault(candidate_date, {"date": candidate_date, "rmssd": None, "hr": None, "sleep_quality": None, "alcohol_flag": 0, "sickness_flag": 0})
        rows = sorted(by_date.values(), key=lambda row: str(row.get("date") or ""), reverse=True)
        for row in rows:
            row["annotations"] = annotations.get(str(row.get("date") or ""), [])
            date_key = str(row.get("date") or "")
            flag_row = day_flags.get(date_key) or {}
            row["sickness_flag"] = 1 if (_boolish_flag(flag_row.get("sickness_bool")) or _boolish_flag(row.get("sickness_flag"))) else 0
            row["alcohol_flag"] = 1 if (_boolish_flag(flag_row.get("alcohol_bool")) or _boolish_flag(row.get("alcohol_flag"))) else 0
            if polar_sleep.get("date") == date_key:
                row["sleep_score"] = polar_sleep.get("sleep_score")
                row["sleep_start"] = polar_sleep.get("sleep_start")
                row["sleep_end"] = polar_sleep.get("sleep_end")
                row["actual_sleep_minutes"] = polar_sleep.get("actual_sleep_minutes")
                row["awake_minutes"] = polar_sleep.get("awake_minutes")
                row["interruptions"] = polar_sleep.get("interruptions")
            if polar_nightly.get("date") == date_key:
                row["ans_status"] = polar_nightly.get("ans_status")
                row["recovery_indicator"] = polar_nightly.get("recovery_indicator")
                row["recovery_indicator_sublevel"] = polar_nightly.get("recovery_indicator_sublevel")
                row["ans_rate"] = polar_nightly.get("ans_rate")
                row["breathing_rate"] = _breathing_rate_from_polar_row(polar_nightly)
            if polar_continuous.get("date") == date_key:
                row["night_pulse"] = polar_continuous.get("resting_candidate_hr")
                row["min_hr"] = polar_continuous.get("min_hr")
                row["max_hr"] = polar_continuous.get("max_hr")
                row["avg_hr"] = polar_continuous.get("avg_hr")
            row["flag"] = "sick" if _boolish_flag(row.get("sickness_flag")) else "alcohol" if _boolish_flag(row.get("alcohol_flag")) else None
        return _ok(recovery={"group_by": body.get("group_by") or "day", "points": rows, "data_status": "ok" if rows else "no_rows_in_range"})
    except ValueError as exc:
        return _error("invalid_request", str(exc))


@actions_v2_api.post("/recovery/control")
@require_ai_write
def recovery_control():
    body = _body()
    try:
        command = _command_guard(body, RECOVERY_COMMANDS, "/recovery/control")
        result = _apply_recovery_live_command(command, body)
        _record_command(connections.get_core_db, "recovery", command, body, result)
        affected = ["hrv.hrv_measurements"] if command in {"set_alcohol_flag", "set_sickness_flag"} else ["hrv.recovery_day_annotations"]
        if command in {"set_alcohol_flag", "set_sickness_flag"} and int(result.get("day_flag_rows") or 0) > 0:
            affected.append("hrv.recovery_day_flags")
        return _ok(command=command, execution=_execution("applied_live", True, affected + ["core.actions_v2_command_log"], "Recovery command mutated the HRV database or its recovery annotations table."), result=result)
    except ValueError as exc:
        return _error("invalid_command" if "Unsupported" in str(exc) else "invalid_request", str(exc))


