@actions_v2_api.get("/nutrition/timing")
@require_ai_read
def nutrition_timing():
    try:
        date_from, date_to, days = _query_date_window(default_days=1, max_days=14)
        anchor_date = _parse_date(request.args.get("date"), "date") or _parse_date(request.args.get("date_to"), "date_to") or _today()
        include_items = _bool_value(request.args.get("include_items"), default=True)
        limit_items = _limit(request.args.get("limit_items"), 80, 200)
        training_time = request.args.get("training_time")
        if training_time not in (None, "") and _hhmm_to_minutes(training_time) is None:
            return _error("invalid_request", "training_time must be HH:MM")
        meals = _nutrition_logged_meals_with_items(date_from, date_to, limit_items, include_items)
        targets = _nutrition_targets()
        daily = _nutrition_daily(date_from, date_to, max(days, 14))
        by_date = {str(row.get("date")): row for row in daily}
        today_meals = [meal for meal in meals if str(meal.get("date") or "")[:10] == anchor_date]
        anchor_actuals = by_date.get(anchor_date) if isinstance(by_date.get(anchor_date), dict) else None
        if today_meals:
            totals = {
                "kcal": round(sum(_float_or_none(meal.get("kcal")) or 0 for meal in today_meals), 1),
                "protein": round(sum(_float_or_none(meal.get("protein")) or 0 for meal in today_meals), 1),
                "carbs": round(sum(_float_or_none(meal.get("carbs")) or 0 for meal in today_meals), 1),
                "fat": round(sum(_float_or_none(meal.get("fat")) or 0 for meal in today_meals), 1),
            }
            totals_status = "available"
        elif anchor_actuals and bool(anchor_actuals.get("logged")):
            totals = {key: _float_or_none(anchor_actuals.get(key)) for key in ("kcal", "protein", "carbs", "fat")}
            totals_status = "available"
        else:
            totals = None
            totals_status = "missing"
        for meal in today_meals:
            logged_at = meal.get("logged_at")
            meal["time_label"] = str(logged_at or "")[11:16] if logged_at else None
            meal.pop("totals", None)
        today_items = [item for meal in today_meals for item in (meal.get("items") or [])]
        today_macro_coverage = _nutrition_macro_coverage(today_items)
        today_data_warnings = [f"unresolved_food_macros:{name}" for name in today_macro_coverage.get("unresolved_food_names") or []]
        if today_macro_coverage.get("status") != "complete":
            today_data_warnings.append("today_totals_may_be_underestimated")
        training_minutes = _hhmm_to_minutes(training_time)
        meal_times = {int(meal["meal_id"]): _planned_meal_time_minutes(meal.get("logged_at") or meal.get("time_label")) for meal in today_meals}
        last_before = None
        if training_minutes is not None:
            before = [(minutes, meal) for meal in today_meals if (minutes := meal_times.get(int(meal["meal_id"]))) is not None and minutes <= training_minutes]
            last_before = before[-1] if before else None
        top_foods: dict[str, dict[str, Any]] = {}
        low_protein_days = []
        high_sugar_days = []
        for row_date, row in by_date.items():
            protein = _float_or_none(row.get("protein"))
            if protein is not None and _float_or_none(targets.get("protein")) is not None and protein < ((_float_or_none(targets.get("protein")) or 0) * 0.85):
                low_protein_days.append(row_date)
            sugar_total = 0.0
            for meal in meals:
                if meal.get("date") != row_date:
                    continue
                for item in meal.get("items") or []:
                    key = str(item.get("name") or "").strip()
                    if not key:
                        continue
                    bucket = top_foods.setdefault(key, {"name": key, "count": 0, "total_kcal": 0.0, "total_protein": 0.0})
                    bucket["count"] += 1
                    bucket["total_kcal"] += _float_or_none(item.get("kcal")) or 0
                    bucket["total_protein"] += _float_or_none(item.get("protein")) or 0
                    if (bucket["total_kcal"] == 0 and bucket["total_protein"] == 0) and bucket["count"] > 1:
                        bucket["macro_status"] = "unresolved_or_zero"
                    sugar_total += _float_or_none(item.get("sugar")) or 0
            if sugar_total >= 50:
                high_sugar_days.append(row_date)
        unresolved_foods_top: dict[str, int] = {}
        complete_days = 0
        partial_days = 0
        poor_days = 0
        for row_date in sorted(str(row.get("date") or "") for row in by_date.values() if str(row.get("date") or "").strip() and row.get("logged")):
            day_items = [item for meal in meals if str(meal.get("date") or "")[:10] == row_date for item in (meal.get("items") or [])]
            coverage = _nutrition_macro_coverage(day_items)
            if coverage["status"] == "complete":
                complete_days += 1
            elif coverage["status"] == "partial":
                partial_days += 1
            else:
                poor_days += 1
            for name in coverage.get("unresolved_food_names") or []:
                unresolved_foods_top[name] = unresolved_foods_top.get(name, 0) + 1
        def _sum_pre_window(key: str, minutes_back: int) -> float | None:
            if training_minutes is None:
                return None
            return round(
                sum(
                    (_float_or_none(meal.get(key)) or 0)
                    for meal in today_meals
                    if meal_times.get(int(meal["meal_id"])) is not None and (training_minutes - minutes_back) <= meal_times[int(meal["meal_id"])] <= training_minutes
                ),
                1,
            )
        coach_summary = {
            "training_time": training_time,
            "last_meal_before_training": _minutes_to_hhmm(last_before[0]) if last_before else None,
            "minutes_since_last_meal_at_training": (training_minutes - last_before[0]) if last_before and training_minutes is not None else None,
            "carbs_before_training_3h": _sum_pre_window("carbs", 180),
            "protein_before_training_3h": _sum_pre_window("protein", 180),
            "evening_kcal_after_18": round(sum((_float_or_none(meal.get("kcal")) or 0) for meal in today_meals if (meal_times.get(int(meal["meal_id"])) or -1) >= (18 * 60)), 1),
            "sugar_events": sum(1 for meal in today_meals for item in (meal.get("items") or []) if (_float_or_none(item.get("sugar")) or 0) >= 15),
            "macro_data_quality": today_macro_coverage.get("status"),
            "warnings": today_data_warnings,
        }
        coach_summary["interpretation_short"] = (
            f"Vor Training {round((coach_summary['minutes_since_last_meal_at_training'] or 0) / 60.0, 1)}h keine Meal und {(coach_summary['carbs_before_training_3h'] or 0)}g Carbs im 3h-Fenster."
            if training_time and coach_summary["last_meal_before_training"] is None
            else "Tagesmakros wahrscheinlich unterschätzt wegen nicht aufgelöster Stück-Foods."
            if today_macro_coverage.get("status") != "complete"
            else "Makro- und Meal-Timing heute gut lesbar."
        )
        if not include_items:
            for meal in today_meals:
                meal.pop("items", None)
        return _ok(
            date=anchor_date,
            range={"date_from": date_from, "date_to": date_to, "days": days, "anchor_date": anchor_date},
            targets={key: _float_or_none(value) for key, value in targets.items()},
            today={
                "totals": totals,
                "totals_status": totals_status,
                "meals": today_meals,
                "macro_coverage": today_macro_coverage,
                "data_warnings": today_data_warnings,
                "timing": {
                    "training_time": training_time,
                    "last_meal_before_training": coach_summary["last_meal_before_training"],
                    "minutes_since_last_meal_at_training": coach_summary["minutes_since_last_meal_at_training"],
                    "carbs_before_training_2h": _sum_pre_window("carbs", 120),
                    "carbs_before_training_3h": coach_summary["carbs_before_training_3h"],
                    "protein_before_training_3h": coach_summary["protein_before_training_3h"],
                    "evening_kcal_after_18": coach_summary["evening_kcal_after_18"],
                    "sugar_events": coach_summary["sugar_events"],
                },
            },
            last_days={
                "avg_kcal": _avg_float([row.get("kcal") for row in by_date.values()]),
                "avg_protein": _avg_float([row.get("protein") for row in by_date.values()]),
                "avg_carbs": _avg_float([row.get("carbs") for row in by_date.values()]),
                "avg_fat": _avg_float([row.get("fat") for row in by_date.values()]),
                "logged_days": sum(1 for row in by_date.values() if row.get("logged")),
                "top_foods": [
                    {
                        **item,
                        "total_kcal": round(item.get("total_kcal") or 0, 1),
                        "total_protein": round(item.get("total_protein") or 0, 1),
                    }
                    for item in sorted(top_foods.values(), key=lambda item: (-item["count"], -item["total_protein"], item["name"]))[:10]
                ],
                "low_protein_days": low_protein_days,
                "high_sugar_days": high_sugar_days,
                "macro_coverage_summary": {
                    "logged_days": sum(1 for row in by_date.values() if row.get("logged")),
                    "complete_days": complete_days,
                    "partial_days": partial_days,
                    "poor_days": poor_days,
                    "unresolved_foods_top": [
                        {"name": name, "count": count}
                        for name, count in sorted(unresolved_foods_top.items(), key=lambda item: (-item[1], item[0]))[:10]
                    ],
                },
            },
            coach_summary=coach_summary,
            data_status={"nutrition": _nutrition_domain_status().get("status"), "notes": []},
        )
    except ValueError as exc:
        return _error("invalid_request", str(exc))


@actions_v2_api.get("/nutrition/foods")
@require_ai_read
def nutrition_foods():
    try:
        query = str(request.args.get("query") or "").strip()
        limit = _limit(request.args.get("limit"), 20, 100)
        sort = str(request.args.get("sort") or "relevance").strip().lower()
        if sort not in {"relevance", "recent", "protein", "kcal"}:
            return _error("invalid_request", "sort must be relevance, recent, protein or kcal")
        conn = connections.get_nutrition_db()
        try:
            if not _table_exists(conn, "nutrition_foods"):
                return _ok(query=query or None, foods=[], count=0)
            where = []
            params: list[Any] = []
            if query:
                like = f"%{_nutrition_food_key(query)}%"
                where.append("(LOWER(name) LIKE ? OR LOWER(COALESCE(name_normalized, '')) LIKE ?)")
                params.extend([like, like])
            where_sql = f" WHERE {' AND '.join(where)}" if where else ""
            order_sql = {"protein": "p_per_100 DESC", "kcal": "kcal_per_100 DESC", "recent": "COALESCE(is_favorite, 0) DESC, id DESC", "relevance": "COALESCE(is_favorite, 0) DESC, id DESC"}[sort]
            rows = _rows(conn, f"SELECT id, name, unit_default, common_portion_size, kcal_per_100, p_per_100, c_per_100, f_per_100 FROM nutrition_foods{where_sql} ORDER BY {order_sql} LIMIT ?", tuple(params + [limit]))
        finally:
            conn.close()
        foods = [{"id": row.get("id"), "name": row.get("name"), "default_amount": _float_or_none(row.get("common_portion_size")) or 100.0, "unit": row.get("unit_default") or "g", "kcal": _safe_round(row.get("kcal_per_100"), 1), "protein": _safe_round(row.get("p_per_100"), 1), "carbs": _safe_round(row.get("c_per_100"), 1), "fat": _safe_round(row.get("f_per_100"), 1), "source": "nutrition_db"} for row in rows]
        return _ok(query=query or None, foods=foods, count=len(foods))
    except ValueError as exc:
        return _error("invalid_request", str(exc))


