@require_ai_read
def nutrition_meal_templates_v2():
    query = str(request.args.get("q") or "").strip()
    limit = _limit(request.args.get("limit"), 50, 200)
    return _ok(meal_templates=list_nutrition_meal_templates(query=query, limit=limit))


