@actions_v2_api.get("/cardio/summary")
@require_ai_read
def cardio_summary():
    try:
        date_from, date_to, days = _query_date_window(date_field="date_to", date_to_field="date_to", days_field="days", default_days=14, max_days=90)
        sport_type = str(request.args.get("sport_type") or "all").strip().lower()
        include_sessions = _bool_value(request.args.get("include_sessions"), default=True)
        limit = _limit(request.args.get("limit"), 20, 100)
        if sport_type not in {"run", "ergo", "stair", "all"}:
            return _error("invalid_request", "sport_type must be run, ergo, stair or all")
        conn = connections.get_runs_db()
        try:
            if not _table_exists(conn, "runs"):
                sessions = []
            else:
                cols = _columns(conn, "runs")
                rows = _rows(
                    conn,
                    f"""
                    SELECT id,
                           substr(date, 1, 10) AS date,
                           {"LOWER(COALESCE(sport_type, 'run'))" if "sport_type" in cols else "'run'"} AS sport_type,
                           {"distance" if "distance" in cols else "NULL"} AS distance_m,
                           {"moving_time" if "moving_time" in cols else "NULL"} AS duration_s,
                           {"avg_hr" if "avg_hr" in cols else "NULL"} AS avg_hr,
                           {"pace" if "pace" in cols else "NULL"} AS pace,
                           {"avg_power" if "avg_power" in cols else "NULL"} AS avg_power,
                           {"note" if "note" in cols else "NULL"} AS note
                    FROM runs
                    WHERE date(date) BETWEEN date(?) AND date(?)
                    ORDER BY date(date) DESC, id DESC
                    LIMIT ?
                    """,
                    (date_from, date_to, limit),
                )
                sessions = []
                for row in rows:
                    resolved_sport = row.get("sport_type") if row.get("sport_type") in {"run", "ergo", "stair"} else ("stair" if any(token in str(row.get("note") or "").lower() for token in ("stair", "stairs", "stairmaster", "stepmill", "etagen")) else "ergo" if any(token in str(row.get("note") or "").lower() for token in ("ergo", "watt", "rpm")) else "run")
                    if sport_type != "all" and resolved_sport != sport_type:
                        continue
                    duration_min = (_float_or_none(row.get("duration_s")) or 0) / 60.0 if _float_or_none(row.get("duration_s")) is not None else None
                    sessions.append(
                        {
                            "id": row.get("id"),
                            "date": row.get("date"),
                            "sport_type": resolved_sport,
                            "duration": _fmt_duration_from_seconds(row.get("duration_s")),
                            "distance_km": _safe_round(((_float_or_none(row.get("distance_m")) or 0) / 1000.0), 2) if _float_or_none(row.get("distance_m")) is not None else None,
                            "avg_power_w": _safe_round(row.get("avg_power"), 1),
                            "avg_hr": _safe_round(row.get("avg_hr"), 1),
                            "pace": _fmt_pace_from_min_per_km(row.get("pace")),
                            "z2_share_estimate": 0.8 if _float_or_none(row.get("avg_hr")) is not None and (_float_or_none(row.get("avg_hr")) or 0) < 150 else 0.3 if _float_or_none(row.get("avg_hr")) is not None else None,
                            "source": "manual",
                            "_duration_min": duration_min,
                            "_hard": bool(_float_or_none(row.get("avg_hr")) and (_float_or_none(row.get("avg_hr")) or 0) >= 155),
                            "_pace_min": _float_or_none(row.get("pace")),
                        }
                    )
        finally:
            conn.close()
        run_sessions = [item for item in sessions if item["sport_type"] == "run"]
        ergo_sessions = [item for item in sessions if item["sport_type"] in {"ergo", "stair"}]
        return _ok(
            range={"date_from": date_from, "date_to": date_to, "days": days},
            summary={
                "total_sessions": len(sessions),
                "run_count": len(run_sessions),
                "ergo_count": len(ergo_sessions),
                "total_duration_min": round(sum(item.get("_duration_min") or 0 for item in sessions), 1),
                "z2_minutes_estimate": round(sum((item.get("_duration_min") or 0) * (item.get("z2_share_estimate") or 0) for item in sessions), 1),
                "hard_sessions": sum(1 for item in sessions if item.get("_hard")),
                "latest_session_date": sessions[0]["date"] if sessions else None,
            },
            run={"count": len(run_sessions), "distance_km": round(sum(_float_or_none(item.get("distance_km")) or 0 for item in run_sessions), 2), "avg_pace": _fmt_pace_from_min_per_km(_avg_float([item.get("_pace_min") for item in run_sessions], 3)), "avg_hr": _avg_float([item.get("avg_hr") for item in run_sessions], 1), "latest": ({k: v for k, v in run_sessions[0].items() if not k.startswith("_")} if run_sessions else None)},
            ergo={"count": len(ergo_sessions), "duration_min": round(sum(item.get("_duration_min") or 0 for item in ergo_sessions), 1), "avg_power_w": _avg_float([item.get("avg_power_w") for item in ergo_sessions], 1), "avg_hr": _avg_float([item.get("avg_hr") for item in ergo_sessions], 1), "estimated_distance_km": round(sum(_float_or_none(item.get("distance_km")) or 0 for item in ergo_sessions), 2), "latest": ({k: v for k, v in ergo_sessions[0].items() if not k.startswith("_")} if ergo_sessions else None)},
            sessions=[{k: v for k, v in item.items() if not k.startswith("_")} for item in sessions] if include_sessions else [],
            data_status={"runs": _runs_state().get("data_status")},
        )
    except ValueError as exc:
        return _error("invalid_request", str(exc))


