@actions_v2_api.post("/runs/control")
@require_ai_write
def runs_control():
    body = _body()
    try:
        command = _command_guard(body, RUN_COMMANDS, "/runs/control")
        result = {k: v for k, v in body.items() if k != "command"}
        if command == "create_run":
            result = _create_run_live(body)
        elif command == "create_cardio_session":
            result = _create_cardio_session_live(body)
        elif command in {"edit_run", "edit_cardio_session"}:
            result = _edit_run_live(body, dry_run=_bool_value(body.get("dry_run"), default=False))
        elif command == "delete_run":
            result = _delete_run_live(body)
        elif command == "delete_cardio_session":
            result = _delete_cardio_session_live(body)
        elif command == "set_run_type":
            _parse_date(body.get("date"), "date", required=True)
            if not body.get("run_type"):
                return _error("invalid_request", "run_type is required")
            _set_state(connections.get_runs_db, "next_run_type", {"date": body["date"], "run_type": body["run_type"]})
        elif command == "update_run_block":
            _set_state(connections.get_runs_db, "run_block", {"name": body.get("active_run_block") or body.get("name")})
        is_dry_run = command in {"edit_run", "edit_cardio_session"} and _bool_value(body.get("dry_run"), default=False)
        if not is_dry_run:
            _record_command(connections.get_runs_db, "runs", command, body, result)
        sidecar_applied = command in {"set_run_type", "update_run_block"}
        live_applied = command in {"create_run", "create_cardio_session", "edit_run", "edit_cardio_session", "delete_run", "delete_cardio_session"} and not is_dry_run
        return _ok(
            command=command,
            execution=_execution(
                "dry_run" if is_dry_run else "applied_live" if live_applied else "applied_sidecar" if sidecar_applied else "logged_only",
                live_applied,
                ["runs.runs", "runs.actions_v2_command_log"] if live_applied else [] if is_dry_run else ["runs.actions_v2_state", "runs.actions_v2_command_log"] if sidecar_applied else ["runs.actions_v2_command_log"],
                "Preview only. No data changed." if is_dry_run else "Run command mutates canonical run sessions in runs.runs." if live_applied else "Run command writes only V2 sidecar state; canonical run sessions are not mutated." if sidecar_applied else None,
            ),
            result=result,
        )
    except ValueError as exc:
        return _error("invalid_command" if "Unsupported" in str(exc) else "invalid_request", str(exc))


