@actions_v2_api.get("/training/today-loads")
@require_ai_read
def training_today_loads():
    try:
        date_iso = _parse_date(request.args.get("date") or _today(), "date", required=True) or _today()
        include_history = _bool_value(request.args.get("include_history"), default=True)
        history_limit = _limit(request.args.get("history_limit"), 8, 20)
        requested_day = str(request.args.get("day") or "").strip()
        requested_label = str(request.args.get("session_label") or "").strip().lower()
        plan_core = _plan_core(_active_plan())
        weekday = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"][date.fromisoformat(date_iso).weekday()]
        session_info = (plan_core.get("days") or {}).get(requested_day or weekday) or {}
        if requested_label:
            for info in (plan_core.get("days") or {}).values():
                if str(info.get("label") or "").strip().lower() == requested_label:
                    session_info = info
                    break
        resolved_session = _plan_session_for_date(date_iso)
        if not requested_day and not requested_label:
            # Default reads must follow the same rolling resolver as Daily,
            # Card and Decision Context, not the legacy weekday projection.
            session_info = {
                "label": resolved_session.get("name"),
                "events": [],
                "exercises": [
                    {
                        "display_name": item.get("name"),
                        "name": item.get("name"),
                        "variation": item.get("variation"),
                        "device": item.get("device") or item.get("equipment"),
                        "sets": item.get("planned_sets"),
                    }
                    for item in (resolved_session.get("exercises") or [])
                    if isinstance(item, dict)
                ],
            }
        plan_exercises = session_info.get("exercises") or []
        requested_names = [item.get("display_name") or item.get("name") for item in plan_exercises if isinstance(item, dict)]
        history_payload = _exercise_history(requested_names, None, date_iso, include_history, True, True) if requested_names else []
        history_by_name = {str(item.get("resolved_name") or item.get("name") or "").strip(): item for item in history_payload}
        exact_resolution_by_display = {
            str((item.get("resolution") or {}).get("resolved_to", {}).get("display_name") or item.get("resolved_name") or item.get("name") or "").strip(): item.get("resolution") or {}
            for item in history_payload
        }
        board = get_core_daily_board(date_iso, create_if_missing=False) or {}
        # This endpoint is retained for history/reference inspection only.
        # GPT Decision Context is the only authority for today's prescription.
        decision_intent = "gpt_only"
        do_not_output_weights = True
        core_notes = ["Legacy-Referenzansicht: keine Coaching- oder Progressionsentscheidung ableiten; maßgeblich ist training_today_decision_context."]
        exercises = []
        history_statuses = []
        for ex in plan_exercises:
            display_name = ex.get("display_name") or ex.get("name")
            hist = history_by_name.get(str(display_name))
            resolution = exact_resolution_by_display.get(str(display_name)) or {}
            resolved_to = (resolution.get("resolved_to") or {}) if isinstance(resolution, dict) else {}
            recent_sets = []
            history_desc = _sort_history_desc((hist or {}).get("history") or [])
            for entry in history_desc[:history_limit]:
                best = entry.get("best_set") or {}
                recent_sets.append({"date": entry.get("date"), "weight": best.get("weight"), "reps": best.get("reps"), "rpe": best.get("rpe"), "e1rm": entry.get("e1rm")})
            current_window = _current_window_history(recent_sets, date_iso, 60)
            best_recent = next((item for item in current_window if item.get("weight") is not None and item.get("date")), None)
            if best_recent is None:
                best_recent = next((item for item in recent_sets if item.get("weight") is not None and item.get("date")), None)
            reference_source = "exact_variation" if str(resolved_to.get("display_name") or "").strip() == str(display_name).strip() else "base_name_alternative" if resolved_to else "fallback"
            meta = _training_reference_meta((best_recent or {}).get("date"), reference_source, anchor_date=date_iso)
            rounding = _rounding_rule(ex.get("device"), ex.get("variation"), display_name)
            top_weight = _apply_rounding(_float_or_none((best_recent or {}).get("weight")), rounding) if best_recent else None
            backoff = _apply_rounding((top_weight or 0) * 0.92, rounding) if top_weight is not None else None
            rep_range = ex.get("rep_range") or {}
            rep_min = rep_range.get("min") or 6
            rep_max = rep_range.get("max") or 10
            suggestion_status = meta["status"]
            history_statuses.append(suggestion_status)
            exercises.append(
                {
                    "display_name": display_name,
                    "name": ex.get("name"),
                    "variation": ex.get("variation"),
                    "planned_sets": ex.get("sets"),
                    "rep_range": rep_range,
                    "rpe_targets": ex.get("rpe_list") or [],
                    "last_performances": recent_sets if include_history else recent_sets[:1],
                    "best_recent_set": best_recent,
                    "suggestion": {
                        "status": suggestion_status,
                        "reference_date": meta["reference_date"],
                        "reference_age_days": meta["reference_age_days"],
                        "reference_source": reference_source,
                        "confidence": meta["confidence"],
                        "warnings": meta["warnings"],
                        "top_set": {"weight": top_weight, "reps_target": f"{rep_min}-{min(rep_max, max(rep_min, rep_min + 2))}", "rpe_cap": 8.5} if best_recent and not do_not_output_weights else None,
                        "backoff_sets": ([{"weight": backoff, "reps_target": f"{max(rep_min, 8)}-{max(rep_max, 10)}"}] if backoff is not None and not do_not_output_weights else []),
                        "progression_note": "Keine Vorgabe hier ableiten; training_today_decision_context verwenden.",
                    },
                    "rounding": rounding,
                }
            )
        if any(status == "available" for status in history_statuses):
            history_status = "fresh"
        elif any(status == "stale_reference" for status in history_statuses):
            history_status = "stale" if all(status == "stale_reference" for status in history_statuses) else "partial"
        else:
            history_status = "missing"
        return _ok(
            date=date_iso,
            session={"label": session_info.get("label"), "source": "rolling_resolver" if not requested_day and not requested_label else plan_core.get("source"), "time": ((session_info.get("events") or [{}])[0]).get("time") if session_info.get("events") else None},
            core_constraints={"decision_intent": decision_intent, "rpe_cap": None, "volume_multiplier": None, "allow_progression": False, "notes": core_notes},
            core_contract_notes=core_notes,
            exercises=exercises,
            data_status={"plan": "fresh" if plan_core.get("available") else "missing", "history": history_status, "core": "fresh" if board else "missing"},
            deprecated=True,
            authoritative_source="training_today_decision_context",
        )
    except ValueError as exc:
        return _error("invalid_request", str(exc))


