@actions_v2_api.post("/training/today/decision")
@require_ai_write
def training_today_decision():
    body = _body()
    day_iso = None
    try:
        day_iso = _parse_date(body.get("date") or _today(), "date", required=True)
        normalized_body = _canonicalize_training_ai_decision_payload(body, _training_decision_context_payload(day_iso))
        saved = _save_training_ai_decision(day_iso, normalized_body)
        # A GPT decision is the canonical frontend training card.  Evict both
        # the embedded dashboard snapshot and its dedicated card snapshot
        # before performing the readback so no old CORE/autopilot card remains
        # visible after a successful write.
        _invalidate_core_dashboard_snapshots(day_iso)
        card = _training_today_card_payload(day_iso)
        _record_command(connections.get_core_db, "training", "save_training_decision", normalized_body, {"date": day_iso, **saved, "readback_status": card.get("status")})
        return _ok(
            date=day_iso,
            decision_id=saved["decision_id"],
            status=saved["status"],
            card_url=f"{BASE_PATH}/training/today/card?date={day_iso}",
            readback={
                "ok": str(card.get("date") or "") == day_iso and str(card.get("status") or "") in {"fresh", "stale"},
                "date": card.get("date"),
                "status": card.get("status"),
                "items_count": len(card.get("items") or []),
                "generated_at": card.get("ai_decision", {}).get("created_at"),
            },
            execution=_execution(
                "applied_live",
                True,
                ["core.training_ai_decisions", "core.actions_v2_command_log"],
                "Training AI decision was validated and persisted.",
            ),
        )
    except ValueError as exc:
        code = str(exc)
        try:
            parsed = json.loads(code)
        except Exception:
            parsed = None
        log_body = normalized_body if "normalized_body" in locals() and isinstance(normalized_body, dict) else body
        log_result = {"ok": False, "error": parsed if isinstance(parsed, dict) else {"code": code, "message": code}, "date": day_iso}
        try:
            _record_command(connections.get_core_db, "training", "save_training_decision", log_body, log_result)
        except Exception:
            pass
        if isinstance(parsed, dict) and parsed.get("code") == "missing_required_fields":
            return (
                jsonify(
                    {
                        "ok": False,
                        "error": {
                            "code": "missing_required_fields",
                            "message": "missing required fields",
                            "details": {"fields": parsed.get("fields") or []},
                        },
                    }
                ),
                400,
            )
        if code in {"invalid_json", "missing_required_fields", "unknown_planned_session", "stale_context_hash", "invalid_action", "invalid_weight"}:
            return _error(code, code.replace("_", " "))
        return _error("invalid_request", code)


@actions_v2_api.get("/life/today")
@require_ai_read
def life_today():
    try:
        date_iso = _parse_date(request.args.get("date") or _today(), "date", required=True) or _today()
        days = _limit(request.args.get("days"), 1, 7)

        # For load and training_fit, use today's payload
        calendar_id = str(request.args.get("calendar_id") or "").strip() or None
        range_today = _calendar_range_payload(date_iso, date_iso, calendar_id=calendar_id)
        today_payload = (range_today.get("days") or [{}])[0]
        plan_core = _plan_core(_active_plan())
        weekday = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"][date.fromisoformat(date_iso).weekday()]
        session_info = (plan_core.get("days") or {}).get(weekday) or {}
        planned_time = ((session_info.get("events") or [{}])[0]).get("time") if session_info.get("events") else None

        free_windows = today_payload.get("free_windows") or []
        school_load = "medium" if int(today_payload.get("event_count") or 0) >= 4 else "low" if int(today_payload.get("event_count") or 0) > 0 else "none"
        evening_load = "medium" if today_payload.get("available") and not any((_hhmm_to_minutes(item.get("start")) or 10**9) <= (18 * 60) <= (_hhmm_to_minutes(item.get("end")) or -1) for item in free_windows) else "low"
        realistic = True
        warning = None
        if planned_time and today_payload.get("available"):
            planned_minutes = _hhmm_to_minutes(planned_time)
            if planned_minutes is not None and free_windows and not any((_hhmm_to_minutes(item.get("start")) or 10**9) <= planned_minutes <= (_hhmm_to_minutes(item.get("end")) or -1) for item in free_windows):
                realistic = False
                warning = "calendar_window_tight"

        if days == 1:
            calendar_out = {
                "available": bool(today_payload.get("available")),
                **({"reason": today_payload.get("reason")} if not today_payload.get("available") else {}),
                "calendar_scope": range_today.get("calendar_scope") or "all_readable_calendars",
                "calendars_checked": range_today.get("calendars_checked") or [],
                "warnings": range_today.get("warnings") or [],
                "events": today_payload.get("events") or [],
                "event_count": int(len(today_payload.get("events") or [])),
            }
            data_freshness_notes = []
        else:
            # Range requested
            end_iso = (date.fromisoformat(date_iso) + timedelta(days=(days - 1))).isoformat()
            range_payload = _calendar_range_payload(date_iso, end_iso, calendar_id=calendar_id)
            all_events = []
            for d in (range_payload.get("days") or []):
                for e in (d.get("events") or []):
                    all_events.append(e)
            calendar_out = {"available": any(d.get("available") for d in (range_payload.get("days") or [])), "calendar_scope": range_payload.get("calendar_scope") or "all_readable_calendars", "calendars_checked": range_payload.get("calendars_checked") or [], "warnings": range_payload.get("warnings") or [], "events": all_events, "event_count": len(all_events), "days": range_payload.get("days")}
            data_freshness_notes = [f"days_window={days}"]

        return _ok(
            date=date_iso,
            calendar=calendar_out,
            load={"school_load": school_load, "work_load": "none", "evening_load": evening_load, "free_windows": [{"start": item.get("start"), "end": item.get("end"), "duration_min": item.get("minutes")} for item in free_windows], "sleep_risk": "low" if evening_load in {"low", "none"} else "medium", "tomorrow_pressure": "unknown"},
            training_fit={"planned_time": planned_time, "realistic": realistic, "warning": warning},
            data_status={"calendar": "fresh" if calendar_out.get("available") else "missing", "notes": data_freshness_notes},
        )
    except ValueError as exc:
        return _error("invalid_request", str(exc))


