        ("get", "/liva/state", "getLivaState", "Read data freshness state", None, False, "Domain freshness and availability for LIVA data. Use this when the user asks whether LIVA is current, stable or missing data."),
        ("get", "/calendar/today", "getCalendarToday", "Read today's calendar", None, False, "Read today's cached calendar events and free blocks from the existing calendar sync cache only. Never writes and never calls Google directly."),
        ("get", "/calendar/range", "getCalendarRange", "Read calendar range", None, False, "Read cached calendar events for a date range grouped by day from the existing synced calendar store."),
        ("get", "/calendar/search", "searchCalendarEvents", "Search calendar events", None, False, "Search cached calendar events by title, description or location within an optional date range."),
        ("get", "/daily/context", "getDailyContext", "Read daily context", None, False, "Read a compact daily context with calendar, recovery, weight and the current training decision status. Use it to see whether a fresh GPT coaching decision already exists or must be regenerated."),
        ("get", "/core/state", "getCoreState", "Read CORE state", None, False, "Current LIVA CORE decision mode and override state."),
