        ("get", "/endurance/approval", "getEnduranceApproval", "Read endurance approval", None, False, "Reads Intervals.icu endurance approval for the day, including original workout, LIVA execution mode and final recommendation."),
        ("post", "/endurance/control", "controlEnduranceApproval", "Control endurance approval", "EnduranceControlRequest", True, "Sets the LIVA execution mode for an Intervals.icu endurance workout. Does not write to Intervals.icu."),
